quests[13833] = { id = 13833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut ist dicker", description = "Der Blutzahnfrenzy ist ein quirliger kleiner Fisch, der für ein Rezept zur Heilung von infizierten Wunden verwendet wird. Wir könnten ein paar von ihnen gebrauchen, wenn Ihr helfen wollt.\n\nWie der Name schon sagt, trinken sie gerne Blut. Die einzige mir bekannte Art und Weise, die kleinen Teufel zu fangen, ist, Blut ins Wasser zu schütten und dann darin zu angeln.\n\nBeschmiert Euch also mit Blut... Tötet dazu einfach eine der Bestien in der Boreanischen Tundra und springt anschließend ins Wasser. Ihr werdet im Nu den perfekten Köder haben.", sourceObjective = "Marcia Balzer in Dalaran möchte, dass Ihr ihr 5 Blutzahnfrenzys bringt.", progress = "Irgendwelches Glück mit den Blutzahnfrenzys gehabt? Vergesst nicht, was ich Euch über das Blut gesagt habe.", completion = "Ihr seid mutig, {name}. Hoffe, dass Ihr beim Vorbereiten Eures Angelplatzes keine Gliedmaßen verloren habt. Wenn Ihr noch immer wild aufs Fischen seid, dann kommt morgen wieder und wir werden uns mehr darüber unterhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13834] = { id = 13834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährlich köstlich", description = "Die besten Angelplätze sind oft die gefährlichsten. Für diejenigen, die dreist genug sind, bietet sich Tausendwinter an - dort sind großzügige Fänge zu machen.\n\nGenau genommen ist es der einzige Ort, wo man den sagenhaften Schreckensfisch fangen kann - ein Fisch, tödlich und köstlich zugleich. Bringt mir ein paar und wir können weiterreden.", sourceObjective = "Marcia Balzer in Dalaran möchte, dass Ihr ihr 10 Schreckensfische bringt.", progress = "Seid auf der Hut, wenn Ihr hinter dem Schreckensfisch her seid.", completion = "Du meine Güte! Ihr habt Euch ein paar Schreckensfische gefangen. Das erinnert mich an die Zeit, als...\n\n<Marcia erinnert sich an Geschichten von Abenteuer und Fischfang und wird sie so lange erzählen, wie Ihr nur zuhören wollt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[13835] = { id = 13835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schildbrecherangriff beherrschen", description = "Ihr werdet lernen müssen, wie man die Verteidigung Eures Gegners durchbrechen kann, um im berittenen Kampf erfolgreich zu sein. Nehmt diese Lanze und steigt auf das angebundene Streitross der Quel'dorei gleich außerhalb des Pavillons.\n\nSprecht mit Valis Windhetzer, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Valis wird Euch die Grundlagen des Schildbrecherangriffs beibringen und wie man mit ihm ein Distanzziel verwundbar macht.", sourceObjective = "Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel'dorei außerhalb des Pavillons. Sprecht mit Valis Windhetzer und wendet die Fähigkeit \"Schildbrecher\" gegen 2 ungeschützte Distanzziele an. Kehrt anschließend zu Späherin Shalyndria beim Argentumturnierplatz zurück.", progress = "Habt Ihr die Übungen mit dem \"Schildbrecher\" abgeschlossen?", completion = "Prägt Euch Valis' Lektionen ein, {name}. Es wird den Unterschied zwischen Sieg und Niederlage Eurer berittenen Kämpfe bedeuten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13836] = { id = 13836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arm dran, Arm ab!", description = "Ich habe von einem tragischen Zwischenfall im Gefängnis von Dalaran gehört; ein besonders brutaler Insasse hat einer Wache einen Arm abgerissen und ihn ins Wasser geworfen. Die Leute von der \"Ersten Hilfe\"-Station haben versprochen, dass sie den Arm wieder annähen können, falls wir ihn zurückbringen.\n\nIhr angelt einfach lange genug im Wasser vor der Violetten Festung, und ich verwette meine Lieblingsangelrute darauf, dass der Arm auftaucht. Findet ihn und bringt ihn zu Olisarra der Gütigen hier in Dalaran. Sie wird wissen, was zu tun ist.", sourceObjective = "Olisarra die Gütige in Dalaran möchte, dass Ihr ihr den abgetrennten Arm bringt.", progress = "Seid gegrüßt. Habt Ihr etwas für mich?", completion = "Oh, seid gegrüßt, {name}. Marcia hat gesagt, dass Ihr den fehlenden Arm des armen Kerls vorbeibringen würdet.\n\nAußerdem hat sie mir diese Tasche hier dagelassen, um sie Euch als Belohnung zu geben. Sie riecht scheußlich und ich kann es kaum erwarten, den Handel abzuschließen, falls Ihr nichts dagegen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13837] = { id = 13837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Ansturmangriff beherrschen", description = "Euer stärkster Angriff im berittenen Kampf ist zweifellos 'Sturmangriff'. Nehmt diese Lanze und steigt auf das Streitross der Quel'dorei, das gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Rugan Stahlbauch, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Rugan wird Euch sagen, wie diese mächtige Fähigkeit zu verwenden ist und Euch ein paar grundlegende Strategien beibringen.", sourceObjective = "Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel'dorei außerhalb des Pavillons. Sprecht mit Rugan Stahlbauch und wendet die Fähigkeit 'Sturmangriff' gegen 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Avareth Flinkstoß beim Argentumturnierplatz zurück.", progress = "Beherrscht Ihr nun das \"Anstürmen\"?", completion = "Mit etwas Erfahrung und Übung wird Euer Ansturm tödlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13838] = { id = 13838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schildbrecherangriff beherrschen", description = "Ihr werdet lernen müssen, wie man durch die Verteidigung Eures Gegners brechen kann, um im berittenen Kampf erfolgreich zu sein. Nehmt diese Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher gleich außerhalb des Pavillons.\n\nSprecht mit Valis Windhetzer, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Valis wird Euch die Grundlagen des Schildbrecherangriffs beibringen und wie man mit ihm ein Distanzziel verwundbar macht.", sourceObjective = "Nehmt Eure Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher. Sprecht mit Valis Windhetzer und wendet die Fähigkeit 'Schildbrecher' gegen 2 ungeschützte Distanzziele an. Kehrt anschließend zu Galathia Morgenglanz beim Argentumturnierplatz zurück.", progress = "Habt Ihr die Übungen mit dem \"Schildbrecher\" abgeschlossen?", completion = "Prägt Euch Valis' Lektionen ein, {name}. Es wird den Unterschied zwischen Sieg und Niederlage Eurer berittenen Kämpfe bedeuten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13839] = { id = 13839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Ansturmangriff beherrschen", description = "Euer stärkster Angriff im berittenen Kampf ist zweifellos 'Sturmangriff'. Nehmt diese Lanze und steigt auf das Streitross der Quel'dorei, das gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Rugan Stahlbauch, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Rugan wird Euch sagen, wie diese mächtige Fähigkeit zu verwenden ist, und Euch ein paar grundlegende Strategien beibringen.", sourceObjective = "Nehmt Eure Lanze und steigt auf den angebundenen Falkenschreiter der Sonnenhäscher außerhalb des Pavillons. Sprecht mit Rugan Stahlbauch und wendet die Fähigkeit 'Sturmangriff' gegen 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Amariel Sonnenschwur beim Argentumturnierplatz zurück.", completion = "Mit etwas Erfahrung und Übung wird Euer Ansturm tödlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13840] = { id = 13840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE", description = "Gack... gack... gack... GAGGACK!\n\nGack... gack... gack.\n\nDas Huhn sieht zu Euch hinauf und beginnt dann, mit seinen Krallen am Boden zu scharren. Ihr glaubt, dass es ein Wort schreibt, aber Ihr seid Euch nicht sicher, was es ist. Könnte es das sein... S-A-L-D-E-A-N? Bevor Ihr fragen könnt, dreht sich das Huhn weg und kümmert sich um seine Angelegenheiten.", sourceObjective = "Beschafft Euch etwas Spezialhühnerfutter und kehrt zu dem Huhn zurück, das sich mit Euch angefreundet hat. Wenn Ihr es gefunden habt, dann benutzt erst /cheer, ehe Ihr dem Huhn das Spezialhühnerfutter gebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13841] = { id = 13841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entschuldigungsschreiben für Höllschrei", description = "Das könnte mein Ende bedeuten... Vielleicht sind meine Taten nicht so gut durchdacht gewesen, wie sie hätten sein sollen...\n\nDie gute Nachricht ist, dass wir einen Angriff zurückgeschlagen haben, der anderenfalls den Untergang des Splitterholzpostens zur Folge gehabt hätte. Lasst uns beten, dass Kommandant Höllschrei es genauso sieht.\n\nIch werde sicherlich nach Orgrimmar gerufen werden, um mich für meine Taten zu rechtfertigen.\n\nBitte, {name}, eilt mir voraus und überreicht diesen Brief an Garrosh.\n\nTut was in Eurer Macht steht, um ihn mir gegenüber milde zu stimmen.", sourceObjective = "Draaka will, dass Ihr den Brief der Erklärung an Garrosh Höllschrei in Orgrimmar überbringt.\n\nBereitgestellter Gegenstand:", completion = "Narren!!\n\nDieses Weib Draaka hat sich von einem Dämonen beeinflussen lassen!\n\n<Garrosh mustert Euch einen Augenblick lang.>\n\nIch rieche seinen Einfluss auch an Euch, {class}...", sourceObjectiveStatus = "unverified-source-field" }
quests[13842] = { id = 13842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tod steht ihm gut", description = "Die Dämonen wollen nichts weiter, als uns wieder von ihrer üblen Magie abhängig zu machen. Diese Abhängigkeit kann nur dazu führen, dass das gesamte Orcvolk zu Sklaven wird.\n\nIhr wünscht, dass Draaka ungeschoren davon kommt? Dann müsst Ihr den Handlanger der Dämonen finden, der sie beeinflusst hat und ihn vernichten!\n\nWenn Ihr mir nicht bald den Kopf dieses Wesens bringt, dann sorge ich dafür, dass sowohl Eurer wie auch Draakas Kopf aufgespießt werden!", sourceObjective = "Sprecht mit Durak in den Splitterholzminen.", progress = "Habt Ihr mir den Kopf des Feindes gebracht, {race}?", completion = "Grah... nun gut.\n\nIch werde das Kopfgeld wieder zurücknehmen, das ich auf Euren Kopf ausgesetzt hatte. Obwohl ich versucht bin, Euer Leben dennoch zu beenden, schon allein aus Prinzip.\n\nPasst nur gut auf, dass Ihr niemals wieder meinen Zorn weckt, {name}. Jetzt geht mir aus den Augen...", sourceObjectiveStatus = "unverified-source-field" }
quests[13843] = { id = 13843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Konstruktionsset: Schrottbot", description = "Ihr durchsucht die Datenbanken der Prototypenkonsole und findet dabei ein Schema für ein Schrottbotkonstruktionsset. Mit Eurer Ingenieursfertigkeit könntet Ihr lernen, Konstruktionssets wie dieses selbst herzustellen.Ihr erlernt:", sourceObjective = "Benutzt die Prototypenkonsole in der Bibliothek des Erfinders.", sourceObjectiveStatus = "unverified-source-field" }
quests[13844] = { id = 13844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Althalaxx plündern", description = "Bevor Ihr Euch gleich wieder in die Schlacht stürzt, möchte ich Euch über ein paar neue Entwicklungen in Kenntnis setzen, {class}. Meine Späher berichten mir, dass der Turm von Althalaxx von den Verlassenen überrannt wird.\n\nVor dem Angriff war dieser trostlose Turm die Heimat eines fanatischen Zweigs des Schattenrats, der von dem gefallenen Hochgeborenen Athrikus Narassin angeführt wurde. Narassin ist längst tot, aber wir dürfen es nicht ignorieren, falls etwas von seinem Werk weiterbesteht. Beschafft Euch seine Forschung und tötet den Kommandant der Verlassenen, der die Ruinen plündert.", sourceObjective = "Findet Narassins Foliant in den Ruinen von Althalaxx und tötet Teegan Holloway, den Kommandanten der Verlassenen.", progress = "Narassin selbst bereitet uns keinen Ärger mehr, aber wenn sein Lebenswerk in die falschen Hände gerät, könnte sich das dunkle Wissen jahrzehntelanger Studien über unseren Köpfen zusammenbrauen. Habt Ihr etwas finden können?", completion = "Mal sehen, was wir hier haben... Bei Elune, seine Notizen allein schon sind in einem halben Dutzend Sprachen geschrieben. Und ist das Blut? Dieses Archiv lässt mich erschauern, aber immerhin sind wir in Sicherheit. Es wird dauern, bis wir alle Notizen entziffern können.\n\nOh, Eure Belohnung? Ja, hier. Eine nette Abwechslung, mal nicht mit untoten Dieben zu arbeiten. Jetzt zurück in den Kampf mit Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[13845] = { id = 13845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versiegelte Giftphiole", description = "Diese Giftphiole sieht besonders gefährlich aus. Womöglich könnte jemand in Dalaran daran interessiert sein.", sourceObjective = "Bringt die versiegelte Giftphiole zu Alchemist Cinesra in die Kanalisation von Dalaran.", progress = "Ist das, was ich denke, {class}?", completion = "Ihr seid mutig, das hier mit Euch herumgetragen zu haben. Wenn nur ein Tropfen auf Eure Haut gekommen wäre, hättet Ihr auf schmerzlichste Weise den Tod gefunden.\n\nErlaubt mir, Euch dafür zu entlohnen... Gift von außergewöhnlicher Stärke kann ich immer gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13846] = { id = 13846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Beitrag leisten", description = "Die besten der Champions kommen jeden Tag zur Kapelle, um der Argentumbeichtpatin zuzuhören.\n\nIhr solltet sehen, wie sehr sie von ihr inspiriert werden, {name}. Sie ziehen nicht nur für den Argentumkreuzzug in den Kampf, sondern geben auch noch sehr viel Geld in den Klingenbeutel, wenn ich ihn herumtrage.\n\nWollt Ihr womöglich auch einen Beitrag leisten?", sourceObjective = "Sprecht mit Knappe Artie, um einen Beitrag von 10 Gold an den Argentumkreuzzug zu leisten.", progress = "Wollt Ihr einen Beitrag leisten?", completion = "Habt Dank. Ich weiß einfach, dass es der Kreuzzug gut einsetzen wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[13847] = { id = 13847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Hauptmann Joseph Holley beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat bestätigt, was die Kreuzfahrer ohnehin schon wussten: dass unsere Krieger mehr sind als bloße Dekoration für den Exerzierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13848] = { id = 13848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überbringer schlechter Nachrichten", description = "Seit Beginn der Belagerung des Splitterholzpostens hat es keine Nachricht nach dort draußen geschafft. Inzwischen muss Kommandant Grimmfang sich Sorgen machen.\n\nIch entsende Euch zum Zoramstrand, um unseren Bericht abzuliefern. Er enthält keine guten Nachrichten, aber zumindest erfährt er dann die Fakten.\n\nSprecht mit Vhulgra, wenn Ihr bereit zum Aufbruch seid.", sourceObjective = "Kadrak will, dass Ihr mit Kommandant Grimmfang am Zoramstrand sprecht.\n\nBereitgestellter Gegenstand:", completion = "<Kommandant Grimmfang runzelt die Stirn, als er den Bericht liest.>\n\nDas sind in der Tat schlechte Nachrichten.\n\nMögen die Geister sie beschützen, bis wir unseren Weg bis zum Splitterholzposten erkämpft haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[13849] = { id = 13849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Astranaar brennt!", description = "{class}, Astranaar steht in Flammen!\n\nSchnell, nehmt diesen Wassereimer und löscht das Feuer, bevor nichts mehr übrig ist!", sourceObjective = "Löscht 15 Feuer.", completion = "Habt Dank!\n\nJetzt ist es an der Zeit, sich um die Horde zu kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13850] = { id = 13850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gifttoleranz", description = "Ihr wollt eine Gifthaut reiten? Dann hab' ich schlechte Neuigkeiten für Euch.\n\nDie Gifthautravasaurier, die bestehen aus nichts als Gift: giftiges Blut, giftiger Speichel, giftige Haut. Ihr steigt auf einen drauf und fallt nach ein paar Stunden tot runter.\n\nIhr müsstet zuerst gegen ihre Gifte resistent werden, bevor ich Euch einen verkaufe, und das dauert ganz schön lange... Ihr müsstet mit ihrem giftigem Blut bespritzt werden, wenn Ihr sie bekämpft. Und zwar sehr oft. Wenn Ihr wirklich daran interessiert seid: Die Gifthäute bevorzugen die nördliche Gegend der Marschen nordwestlich von hier.", sourceObjective = "Mor'vek im Krater von Un'Goro behauptet, dass wenn man 20-mal von dem Blut eines Gifthautravasauriers vergiftet wurde, auf einem reiten könnte, ohne zu sterben. Greift die Saurier an, um vielleicht vergiftet zu werden.", completion = "Ihr habt es geschafft? Ihr habt es wirklich geschafft?!\n\nHo ho! Dickköpfig wie meine Frau seid Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[13851] = { id = 13851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir die Vorbereitungen für das Turnier treffen, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Clara Torkelbräu beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir würdige Verbündete sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13852] = { id = 13852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Klick Radspanner beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit hat gezeigt, dass wir den Anhängern des Argentumkreuzzugs ebenbürtig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13853] = { id = 13853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feuer erwidern", description = "Die meisten Feuer sind unter Kontrolle, aber wir müssen etwas gegen diese Windreiter unternehmen!\n\nSchnell, {name}, Ihr müsst in eine unserer Glevenschleudern klettern und das Feuer erwidern!", sourceObjective = "Verwendet eine Schleuder von Astranaar, um 15 von Höllschreis Vandalen und ihre Wachwindreiter abzuschießen.", completion = "Wir sind gerettet! Ihr habt genug abgeschossen. Den Rest sollten wir selbst erledigen können.\n\nIch kann Euch gar nicht genug danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13854] = { id = 13854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Ranii beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat bestätigt, was die Kreuzfahrer ohnehin schon wussten: dass unsere Krieger mehr sind als bloße Dekoration für den Exerzierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13855] = { id = 13855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Airae Sternensucher beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", progress = "Habt Ihr an der Seite der Kreuzfahrer im Hof der Knochen gedient?", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass sie sich im Kampf gegen den Lichkönig auf uns verlassen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13856] = { id = 13856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Morah Worgschwester beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", progress = "Habt Ihr an der Seite der Kreuzfahrer im Hof der Knochen gedient?", completion = "Eure Tapferkeit auf dem Feld hat bestätigt, was die Kreuzfahrer ohnehin schon wussten: dass unsere Krieger die besten auf Azeroth sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13857] = { id = 13857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Gahju beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir angesichts der Diener des Lichkönigs keine Angst kennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13858] = { id = 13858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Anka Klauenhuf beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache un 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir loyale Verbündete im Kampf gegen den Lichkönig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13859] = { id = 13859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Aneera Thuron beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir bereit sind, jedem Gegner zu trotzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13860] = { id = 13860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Tierführer Dretch beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Der Argentumkreuzzug hat gesehen, wie entschlossen wir sind, und sie wissen, dass unsere Krieger die Sache zu Ende bringen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13861] = { id = 13861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht vor der Zitadelle", description = "Während einige von uns auf dem Turnier alles geben, bereiten unsere Brüder den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", completion = "Es ermutigt uns vom Argentumkreuzzug, jemanden wie Euch zu haben, der Seite an Seite mit uns gegen den Lichkönig kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[13862] = { id = 13862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht vor der Zitadelle", description = "Während einige von uns auf dem Turnier alles geben, bereiten unsere Brüder den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", completion = "Es ermutigt uns vom Argentumkreuzzug, jemanden wie Euch zu haben, der Seite an Seite mit uns gegen den Lichkönig kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[13863] = { id = 13863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht vor der Zitadelle", description = "Während sich einige der Kreuzfahrer auf das Turnier vorbereiten, wurden andere ausgesandt, um die Hochburg des Feindes, die Eiskronenzitadelle, anzugreifen.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", completion = "Wir sind nie vor der Geißel zurückgewichen, haben sie das Fürchten gelernt und diese Kampagne wird nicht anders sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13864] = { id = 13864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht vor der Zitadelle", description = "Während sich einige der Kreuzfahrer auf das Turnier vorbereiten, wurden andere ausgesandt, um die Hochburg des Feindes, die Eiskronenzitadelle, anzugreifen.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", completion = "Wir haben die Geißel an allen Fronten bekämpft, haben sie das Fürchten gelernt und diese Kampagne wird nicht anders sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13865] = { id = 13865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drei Anführer sind drei zu viel", description = "Hört gut zu, {class}.\n\nIn dieser Region gibt es drei Kommandanten der Elfen, die ihre Bemühungen gezielt auf das Holzfällerlager richten. Sie zu töten, würde sicherlich Panik und ein Durcheinander anrichten. Hoffentlich ausreichend, sodass wir unsere Mission erfolgreich durchführen können.\n\nWo Ihr schon dabei seid: Die Vernichtung ihrer Späher kann unserer Sache nur dienlich sein.", sourceObjective = "Krokk will, dass Ihr Dorinar, Arminon, Endolar und 12 Eschentalspäher tötet.\n\nSprecht mit Kadrak im Splitterholzposten, falls Ihr das Geheimsignalpulver verliert.", completion = "Gute Arbeit, {class}.\n\nBei ihnen herrscht ein heilloses Durcheinander. Seht sie Euch an!", sourceObjectiveStatus = "unverified-source-field" }
quests[13866] = { id = 13866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Schutzwall!", description = "Diese Wälder mögen ruhig sein, aber unsere Feinde lauern hinter jedem Baum. Ich habe schon so manchen Orc mit Pfeilen in seinem Rücken entdeckt und die Waffe noch nicht gezückt.\n\nHier ist es tückisch hinter den feindlichen Linien, aber wir könnten starke Arme und kluge Köpfe dort unten im Schutzwall von Mor’shan gebrauchen. Kadrak bereitet eine Offensive von dort aus vor – er zieht Taten den Worten vor. Ihr werdet Euch gut mit ihm verstehen.\n\nSprecht mich wieder an, wenn Ihr bereit seid und ich fliege Euch dorthin.", sourceObjective = "Sprecht mit Kulg Blutspritzer an der Grenze zwischen Eschental und Azshara, um zum Schutzwall von Mor’shan gebracht zu werden. Meldet Euch bei Kadrak, wenn Ihr dort eintrefft.", completion = "Ihr kommt genau zur rechten Zeit, {class}. Der alte Kulg schleicht schon zu lange durch diese Wälder. Er wird übervorsichtig und fürchtet sich vor jedem Schatten. Wir werden diesen Wald nicht länger fürchten – die Zeit ist gekommen, das Eschental ein für alle Mal zu unterwerfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13867] = { id = 13867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eindämmung der Furbolgbedrohung", description = "Direkt im Norden von Astranaar sind die Distelfellfurbolgs. Meine Späher berichten, dass ihre Anzahl in den letzten Monaten stark zugenommen hat. Wenn sie zu schnell anwächst, fassen sie vielleicht den Mut, Astranaar direkt anzugreifen!\n\nBegebt Euch ins Lager der Distelfelle und tötet so viele von ihnen, wie Ihr könnt.\n\nIch werde hier in Astranaar bleiben und Euren Bericht erwarten. Elune sei mit Euch, {class}.", sourceObjective = "Tötet 15 Furbolgs im Lager der Distelfelle in Eschental.", completion = "Gute Arbeit, {name}.\n\nWir stehen unter der ständigen Bedrohung durch die Furbolgs. Hoffentlich wird sie das etwas länger von uns fernhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13868] = { id = 13868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechter Einfluss?", description = "Als Ihr die Habseligkeiten der toten Furbolgs durchsucht, die vor Euch liegen, fällt ein kleiner, offensichtlich von Trollen erschaffener Glücksbringer auf den Boden.\n\nAls Ihr den Glücksbringer berührt, bekommt Ihr umgehend das Gefühl, dass es im Wald nicht mit rechten Dingen zugeht. Ein Gefühl der Unruhe und Verderbtheit durchdringt das Objekt.\n\nIhr hüllt es in ein Tuch, verstaut es in Eurem Gepäck und beschließt, es Raene Wolfsläufer zu zeigen, wenn Ihr das nächste Mal in Astranaar seid.", sourceObjective = "Überbringt den TrollglücksbringerRaene Wolfsläufer in Astranaar im Eschental.", progress = "Was beunruhigt Euch, {class}?", completion = "Ein Trollglücksbringer? Was fangen die Furbolgs mit so einem Ding an?\n\nIhr habt recht. Ein Gefühl von Verderbtheit umgibt dieses Artefakt... Sogar ich kann das spüren.\n\nEs gibt hier jemanden, der in der Lage sein müsste, zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13869] = { id = 13869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Überreste", description = "Die Satyrn haben den Bäumen fürchterlichen Schaden zugefügt, aber das ist nichts im Vergleich zu dem Gemetzel, das die Orcs veranstaltet haben!\n\n<Das Urtum zittert sichtbar vor Wut. Seine Blätter fallen rings um Euch zu Boden.>\n\n{race}, begebt Euch die Straße entlang zum Holzfällerlager und holt die Überreste dieser Bäume, Treants und Urtume, welche die Horde in ihren besten Jahren gefällt hat.", sourceObjective = "Sammelt 10 Stück Holz des Kriegshymnenklans.", progress = "Habt Ihr die Überreste, {race}?", completion = "Ich lebe schon lange friedlich in diesem Wald, aber wenn ich sehe, was diese Orcs hier veranstalten, dann würde ich sie am liebsten in Grund und Boden stampfen!\n\nIch werde diesem Holz jetzt seine letzte Ruhe geben. Habt Dank für Eure Hilfe, {name}. Ich werde es Euch nie vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13870] = { id = 13870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besser geht’s nicht", description = "Nun gut, {class}, besser geht es nicht.\n\nDie Elfen sind dabei, sich von Euren letzten Taten zu erholen. Das ist der günstigste Augenblick, um in das Holzfällerlager vorzustoßen!\n\nBegebt Euch dorthin und sprecht mit Vorarbeiter Gorthak. Er wird Euch erklären, wie Ihr die Diplomatin am sichersten begleitet.\n\nViel Glück!", sourceObjective = "Krokk will, dass Ihr das Holzfällerlager des Kriegshymnenklans betretet und mit Vorarbeiter Gorthak sprecht.", completion = "<Gorthak seufzt enttäuscht.>\n\nWenn Ihr doch nur vor einer Stunde eingetroffen wäret...\n\nDie Diplomatin wurde von einem Auftragsmörder der Elfen tödlich verwundet.\n\nWie der Feind in der Lage war, das Lager unentdeckt zu infiltrieren bleibt uns ein Rätsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[13871] = { id = 13871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachen!", description = "Es ist nicht so, als ob ich nicht schon genug um die Ohren hätte!\n\nDiesen Ort am Laufen zu halten ist schon schwer genug, ohne dass die Elfen und Draenei uns ständig belästigen.\n\nJetzt schleicht obendrein noch ein Auftragsmörder im Lager umher, der eine wichtige Diplomatin getötet hat... Während meiner Wache!\n\nWer auch immer es war, er kann noch nicht weit sein, {class}. Durchsucht das Lager, bis Ihr ihn findet und dann rächt die Diplomatin!\n\nZumindest kann ich dann den Kopf des Mörders in Händen halten, wenn ich mich vor Höllschrei rechtfertigen muss.", sourceObjective = "Vorarbeiter Gorthak will, dass Ihr ihm den Kopf eines Assassinen der Kaldorei bringt.", progress = "Mich interessiert nur eins, {race}.\n\nIst der Auftragsmörder tot?", completion = "Gute Arbeit, {class}.\n\nEine letzte Bitte – Es ist vermutlich das Beste, wenn keiner meiner Arbeiter erfährt, dass dieser Mörder jemals existiert hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13872] = { id = 13872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Weisheit der Worgen", description = "Der Mann, der mir direkt gegenübersteht, ist als Hephaestus Pilger bekannt. Er ist einer der Worgen.\n\nEr und seine Schwester kamen vor nicht allzu langer Zeit nach Astranaar, als sie einen neuen Ort zum Leben suchten. Soweit ich das sagen kann, ist er daran interessiert, dem Irdenen Ring bei der Katastrophe zu helfen. Seine Schwester ist sogar noch mächtiger. Sie ist nach Osten gereist, um dem Schamanen zu helfen, sich um den Vulkan zu kümmern.\n\nVielleicht kann er helfen. Bringt den Glücksbringer zu ihm und hört, was er darüber denkt.", sourceObjective = "Bringt den Trollglücksbringer zu Hephaestus Pilger in Astranaar im Eschental.", progress = "<Der Worgen sieht Euch ausdruckslos an, als Ihr Euch nähert.>", completion = "<Er sieht auf die Holzschnitzerei in Eurer ausgestreckten Hand. Der Worgen greift danach und nimmt sie an sich.>", sourceObjectiveStatus = "unverified-source-field" }
quests[13873] = { id = 13873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sheelahs Vermächtnis", description = "Ich... Ich kann nicht glauben, dass sie von uns gegangen ist. Es ist alles so schnell gegangen...\n\nIch muss Euch wohl danken, dass Ihr meine Herrin gerächt habt. Dafür habt meinen Dank und den von Silbermond.\n\nIn Ihrer Weisheit hat meine Lady Ihr Ende vorausgesehen. Sie hat ein Sendschreiben vorbereitet für den Fall, dass ihr irgendetwas zustoßen würde.\n\nWir sollten uns einem Gefolge aus Orgrimmar anschließen, am Wegekreuz nördlich von hier. Bitte, {race}, trefft sie an unserer statt und sorgt dafür, dass die Nachricht übergeben wird.", sourceObjective = "Wächter Menerin will, dass Ihr Sheelahs versiegelten Brief an Wächter Gurtar übergebt.\n\nBereitgestellter Gegenstand:", completion = "<Gurtar hört Euch zu, als Ihr ihn über Sheelahs Tod unterrichtet.>\n\nIch werde dies Höllschrei persönlich übergeben, {race}.\n\nIn der Zwischenzeit könntet Ihr etwas für mich tun...", sourceObjectiveStatus = "unverified-source-field" }
quests[13874] = { id = 13874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Bann der Glücksbringer", description = "Die Furbolgs begehren etwas, das ihnen nicht gehört.\n\n<Hephaestus dreht den Glücksbringer in seiner Hand und lässt ihn dann fallen.>\n\nDiese Schnitzerei besitzt die Eigenschaft, langsam jene zu verderben, die keine Trolle sind. Soweit ich sehen kann, haben die Furbolgs das schon einmal gemacht. Manche lernen’s nie.\n\nZweifellos horten sie die meisten Glücksbringer in der Höhle der Distelfelle nördlich ihres Dorfes.", sourceObjective = "Sammelt 8 Trollglücksbringer.", progress = "Glaubt Ihr, dass Ihr schon alle Trollglücksbringer aus der Höhle der Distelfelle gesammelt habt?\n\nFalls auch nur einer verbleibt, wird der Stamm der Distelfelle weiterhin von ihm beeinflusst werden und schließlich diesen Ort angreifen.", completion = "<Hephaestus nickt langsam, während er Euch direkt in die Augen blickt.>\n\nIhr habt vermutlich die Distelfelle vor sich selbst beschützt, zumindest vorerst. Jedenfalls so lang sie nun davon absehen können, mächtige Objekte zu stehlen, die ihnen nicht gehören.\n\nSoweit ich das sehe, haben die Nachtelfen Probleme mit dem anderen Furbolgstamm im Süden. Darüber möchte Raene mit Euch sprechen.\n\nWie dem auch sei, es gibt dringlichere Angelegenheiten, bei denen ich Euch um Eure Unterstützung bitten möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[13875] = { id = 13875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurtars Bitte", description = "Ich hätte noch eine persönliche Bitte an Euch, {class}.\n\nEs ist viele Monde her, seitdem ich meine Liebste gesehen habe, Draaka. Es werden noch viele weitere verstreichen, bis wir uns wiedersehen können. Ich fürchte, dass nach so langer Zeit ihre Liebe für mich schwinden wird.\n\nDieser Zopf hat für uns beide eine besondere Bedeutung, und auch der dornige Blutkelch, die Blume, die in dieser Region wächst.\n\nIch bitte Euch, diese Blumen zu pflücken und sie mit dieser Schnur zu binden. Dann übergebt Draaka das Geschenk in meinem Namen.", sourceObjective = "Wächter Gurtar will, dass Ihr den Blutkelchzopf an Draaka im Splitterholzposten übergebt.", progress = "Hallo, {name}.", completion = "<Draaka erfasst sofort die Bedeutung dieses Geschenks und beginnt zu weinen.>\n\nOh, {name}. Habt Dank für dieses Geschenk! Es bedeutet mir mehr, als Ihr ahnen könnt.\n\nEr hat nicht vergessen...", sourceObjectiveStatus = "unverified-source-field" }
quests[13876] = { id = 13876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu weit entfernt", description = "Ja, ich spreche Eure Sprache, {race}.\n\nWir Furbolgs waren schon einmal Opfer dieser Form von Verderbnis. Vor nicht allzu langer Zeit stahl unser Anführer den Götzen von Remulos. Das von Dämonen verderbte Ding verhexte den gesamten Stamm und unsere Erlösung wurde nur notdürftig durch einen Druiden herbeigeführt, der Broll Bärenfell heißt.\n\nAber dieses Mal haben wir nicht gestohlen. Die Trolle von Zoram'gar gaben uns die Glücksbringer als ein Zeichen der Freundschaft. Eine tödliche Freundschaft, wie es scheint.\n\nUnser Häuptling Dal Blutklaue ist nicht mehr zurechnungsfähig. Betretet die Höhle und kehrt mit seinen Glücksbringern zurück.", sourceObjective = "Gelangt in den Besitz von Blutklaues Sammlung.", progress = "Nun? Die Zukunft der Distelfelle lastet auf Euren Schultern, {race}.", completion = "Es wurde getan, was getan werden musste. Da Dal unser Anführer ist, hat seine Erkrankung durch die Trollglücksbringer uns zerstört.\n\nFür die Gesundheit und die Würde unseres Stammes war es gut, dass Ihr es wart, Fremdling. Auf diese Weise wird es keinen Bürgerkrieg unter uns geben und wir finden leicht einen neuen Anführer... hoffentlich jemanden, der nicht so schnell Fremden vertraut. Vielleicht habe auch ich mich dessen schuldig gemacht?\n\nHier, erlaubt mir unsere Schuld zu begleichen, bevor sich unsere Wege für immer trennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13877] = { id = 13877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tanz auf dem Vulkan", description = "<Der Worgen starrt Euch durchdringend an, bevor er seine Bitte vorträgt.>\n\nDer Vulkan droht, ganz Eschental zu verschlingen, wenn wir nicht rasch handeln. Lasst Euch gesagt sein, dass dies kein natürlicher Ausbruch war.\n\nMeine Schwester Sabina ist mächtig. Sie ist nach Osten zur Grenze des Lavastroms am Donnergipfel direkt nördlich der Straße gegangen. Dort erbittet sie die Hilfe anderer Elemente gegen den Feuerlord, der diese Zerstörung verursacht hat.\n\n{name}, begebt Euch zu ihr und helft ihr, so gut Ihr könnt.", sourceObjective = "Sprecht mit Sabina Pilger am südlichen Rand des Lavastroms am Donnergipfel in Eschental.", completion = "Mein Bruder muss Euch gesandt haben. Er hätte das nicht getan, wenn Ihr nicht in der Lage wäret, etwas zu tun, was getan werden muss.\n\nIch hoffe um unser aller Willen, dass er recht hat.\n\nDie Elementare hier sind nun meine Verbündeten. Ihr müsst tun, was sie Euch sagen, wenn wir die Zerstörung vom Rest des Eschentals verhindern wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13878] = { id = 13878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch Feuer und Flamme", description = "Helft mir, {class}! Schweinemenschen kommen und zünden Ställe an – Feuer! Feuer!\n\n<Dorak jammert etwas Unverständliches, bevor es Euch gelingt, ihn zu beruhigen.>\n\nWölfe drinnen noch angekettet. Jemand muss die kleinen Wölfe retten!", sourceObjective = "Brecht die Ketten auf und befreit die Wölfe aus den brennenden Ställen", completion = "Ihr habt die Wölfe gerettet! So mutig! Eines Tages bekommt Ihr vielleicht einen Wolf wie diesen als Reittier.\n\n<Dorak sieht auf die brennenden Ställe, dann zum nahegelegenen Fluss.>\n\nWas soll ich nun tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[13879] = { id = 13879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnergipfel", description = "Seid gegrüßt, {class}!\n\nIch gratuliere zu Eurem siegreichen Angriff auf Astranaar. Die Elfen werden diese Schmach nicht so schnell vergessen, die sie durch Eure Hand erlitten haben.\n\nAber Ihr müsst wissen, dass die Elfen nicht das einzige Hindernis sind, dass der Eroberung des Eschentals durch die Horde im Wege steht...\n\nIm Osten benötigt ein Schamane des Irdenen Rings Hilfe bei einer anderen Krise. Ihr findet ihn in der Nähe des Fußes des Vulkans Donnergipfel.", sourceObjective = "Broyk will, dass Ihr Stikwad am Donnergipfel findet.", completion = "<Der Goblin starrt Euch an und blinzelt einige Male bevor er spricht.>\n\nDie Geister haben mir geflüstert, dass diese Hilfe bald eintrifft.\n\nVerzeiht meine Überraschung, aber ich hatte darauf gehofft, dass die Geister jemanden schicken der etwas... heldenhafter ist.\n\nDie Elementare sind meine Vertrauten. Hört sie an und leistet ihren Anordnungen Folge. Falls wir scheitern, wird vom Eschental nichts mehr übrigbleiben, für das es sich zu kämpfen lohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13880] = { id = 13880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heiße Lava", description = "<Der riesenhafte Erdelementar starrt auf Euch herab.>\n\nDer Lavastrom muss aufgehalten werden, wenn wir überleben wollen. Ich werde Euch einen Teil meiner Kraft übertragen. Verwendet sie, um die Lavafelsspalten zu füllen!", sourceObjective = "Verwendet das Geschenk der Erde, um 8 Lavafelsspalten zu füllen.", progress = "Fertig?", completion = "Gut gemacht, {race}. Lord Magmathars Feuer ist nun gefangen und wieder fest in der Erde verschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13881] = { id = 13881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgezehrt", description = "Meine größte Sorge gilt den Distelbärfamilien, die diese Wälder behausen. Südlich von hier, hinter dem Bärenschrein, ist eine gesamte Generation der Bären erkrankt. Schrecklich erkrankt.\n\n{name}, ich weiß nicht, woran sie leiden, aber es scheint sie von innen aufzuzehren. Der Gedanke, dass eine gesamte Generation nicht mehr zu retten ist, ist entsetzlich, aber wir müssen sie töten, damit ihre Körper der Erde zurückgegeben werden.\n\nUnd was noch wichtiger ist, wir müssen den Ursprung der Krankheit finden. Untersucht den See, aus dem die Bären trinken.", sourceObjective = "Tötet 6 aufgezehrte Distelbären und untersucht den See, von dem die Distelbären trinken.", completion = "<Kathrena schaudert bei der Beschreibung der in Mitleidenschaft gezogenen Tiere und dem furchtbaren Gerät auf dem Boden des Sees.>\n\n{name}, das ist grauenvoll. Was ist das für ein Ding und wo kommt es her? Etwas zehrt diese Tiere auf, sowohl körperlich als auch spirituell. Ich hatte damit gerechnet, dass die Satyrn oder eine Krankheit die Schuld trügen, aber es scheint einen doch eher... unnatürlichen Grund dafür zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13882] = { id = 13882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Samenkörner des Lebens", description = "Etwas versucht, das Leben aus Dunkelküste aufzuzehren! Ich werde mich umhören, ob jemand etwas über - das Ding - weiß, das Ihr gefunden habt. In der Zwischenzeit müssen wir uns aber auch um die Wildtiere kümmern, damit ihnen nicht noch weiteres Leid geschieht.\n\nKönnt Ihr ein paar Materialien für mich besorgen? Ich brauche Leben in allen möglichen Formen. Sprecht mit Onu hier am Hain, um die Saat der Erde zu erhalten. Fangt einen Dunkelküstenirrwisch, um die Saat des Himmels zu erhalten, und besorgt die Saat des Meeres von den Seemuschelschalen an der Küste westlich von hier.", sourceObjective = "Sammelt die Saat der Erde, die Saat des Meeres und die Saat des Himmels.", progress = "Leben ist mächtig, {name}. Konzentriert in seiner reinsten Form kann es alles überstehen. Eines Tages wird auch Dunkelküste von den Wunden genesen. Habt Ihr alles gefunden, was ich brauche?", completion = "Perfekt - das ist alles, was ich brauche. Hattet Ihr Spaß beim Irrwischfangen? Als kleines Mädchen habe ich immer Irrwische in Eschental herumgejagt.\n\n<Kathrena schwelgt in Erinnerungen. Plötzlich verdunkelt sich ihr Blick.>\n\nIch befürchte, ich weiß, womit wir es hier zu tun haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13883] = { id = 13883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wrack neben dem anderen", description = "Stümperhaftes Handwerk! Es gibt keine andere Erklärung...\n\nDiese Schiffe müssen in großer Eile zusammengeflickt worden sein. Ganze Panzerungsplatten fallen ab, ohne jemals einen Treffer abgefangen zu haben!\n\nIch zeige ihnen, wie man es richtig macht. Aber zuerst müsst Ihr für mich die Teile vom Meeresboden bergen.\n\nKehrt mit den Teilen zu mir zurück und ich erledige den Rest.", sourceObjective = "Bergt 10 Teile versunkenes Altmetall.", progress = "Habt Ihr die Panzerungsplatten geborgen, {race}?", completion = "Gute Arbeit, {race}.\n\nIch werde ihnen zeigen, wie ein gepanzertes Schiff gebaut werden sollte!", sourceObjectiveStatus = "unverified-source-field" }
quests[13884] = { id = 13884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerlöscher", description = "Wir müssen uns zunächst um Lord Magmathars Lakaien kümmern, wenn wir dieses Gebiet zurückerobern wollen und der hitzigen Zerstörung des Waldes Einhalt gebieten wollen.\n\nDie Lavawüter auf dem Strom im Norden werden durch ihr Element gestärkt. Ich fürchte, wenn Ihr auf Euch gestellt seid, habt Ihr keine Chance gegen sie.\n\nWenn Ihr bereit seid, sprecht mich wieder an und ich werde einen meiner Helfer für Euch beschwören.", sourceObjective = "Tötet 10 Lavawüter. Falls Ihr einen weiteren gefrierenden Woger benötigt, sprecht mit Arctanus.", completion = "Ihr habt Euch auf dem Schlachtfeld wacker geschlagen. Dennoch hat Lord Magmathar Euch leider bemerkt und die Zerstörung, die Ihr über seine Lakaien gebracht habt.\n\nIhr werdet Euch um ihn kümmern müssen, oder er verbrennt Euch bei lebendigem Leibe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13885] = { id = 13885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung Dunkelküstes", description = "Nun da wir wissen, dass unsere Vorsorgemaßnahmen funktionieren, sollten wir so viel Land abdecken wie möglich.\n\nWir können einen der Hippogryphen benutzen, aber alleine kann ich nichts ausrichten. Sprecht mit meinem Freund Orseus beim Flugmeister vor dem Hain. Sagt ihm Bescheid, wenn Ihr soweit seid. Ich werde Euch dort treffen. Wir werden Dunkelküste von der Luft aus abdecken und so viele Tiere wie möglich schützen!", sourceObjective = "Sprecht mit Orseus vor dem Hain der Uralten und besteigt einen Hippogryphen. Beschützt aus der Luft 8 Weißschwanzhirsche und -rehe, 8 ergraute Distelbären und 8 Mondpirschermatriarchinnen oder Mondpirscherpatriarchen vor der Verzehrung.", completion = "Die Tiere sind also in Sicherheit. Ich danke Euch, vielen Dank!\n\nJetzt müssen wir unsere Aufmerksamkeit dem Ursprung der Verzehrung widmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13886] = { id = 13886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vortex", description = "Es ist an der Zeit, {name}. Wenn Ihr Euch gewappnet habt, sprechen wir wieder miteinander und ich werde einen Wirbelnden Vortex beschwören, der Eure Schritte zu den Himmeln über dem Donnergipfel beschleunigt.\n\nLeitet die Kraft des Irdenen Rings durch den Elementar, um Lord Magmathar zu vernichten, sodass wir ihn wieder ins Gleichgewicht bringen.", sourceObjective = "Verwendet die Kräfte des Wirbelnden Vortexes, um Lord Magmathar zu vernichten.", completion = "Es ist vollbracht. Die Kräfte des Feuers sind beruhigt und die vier Elemente befinden sich wieder in Harmonie.\n\nIhr habt den Rest des Eschentals mit Eurem Mut und Euren heldenhaften Taten gerettet, {name}. Wir schulden Euch unseren ewigen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[13887] = { id = 13887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gifthauteier", description = "Jetzt, da Ihr gegen das Sauriergift immun geworden seid, könnt Ihr mit den Tieren und ihren Eiern sicher umgehen. Gifthäute sind ziemlich bösartig und müssen vom Moment des Schlüpfens an trainiert werden.\n\nWenn Ihr einen reiten wollt, dann werdet Ihr ein ungeschlüpftes Ei benötigen. In den gesamten Marschen verteilt gibt es einige Ravasauriernester. Sucht nach Eiern mit helleren Schalen - das sind diejenigen, aus denen später Gifthäute schlüpfen werden.\n\nWenn Ihr mir einige Eier bringt, werde ich Euch gestatten, eins zu behalten und unter meiner Aufsicht aufzuziehen.", sourceObjective = "Bringt Mor'vek im südöstlichen Teil der Marschen 4 Eier von Gifthautravasauriern.", progress = "Habt Ihr die Eier gefunden?", completion = "Gute Arbeit. Wirklich, ich bin erstaunt, dass Ihr so viele gefunden habt. Ihre Zahl scheint in jedem Gelege zurückgegangen zu sein.\n\nIch werde Euch einen der frisch geschlüpften Gifthäute aufziehen lassen. Er wird sich vermutlich nicht zieren, Euch wissen zu lassen, was er braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13888] = { id = 13888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vortex", description = "Es ist an der Zeit, {name}. Wenn Ihr Euch gewappnet habt, sprechen wir wieder miteinander und ich werde einen Wirbelnden Vortex beschwören, der Eure Schritte zu den Himmeln über dem Donnergipfel beschleunigt.\n\nLeitet die Kraft des Irdenen Rings durch den Elementar, um Lord Magmathar zu vernichten, sodass wir ihn wieder ins Gleichgewicht bringen.", sourceObjective = "Verwendet die Kräfte des Wirbelnden Vortexes, um Lord Magmathar zu vernichten.", completion = "Ihr habt es geschafft! Die Geister haben sich doch nicht getäuscht!\n\nDie Kräfte des Feuers sind beruhigt und die vier Elemente befinden sich wieder in Harmonie.\n\nDem Rest des Eschentals bleibt dieses Schicksal der Flammen erspart. Der Irdene Ring ist Euch zu ewigem Dank verpflichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13889] = { id = 13889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sooooo hungrig", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen sind grob, aber Ihr könnt die Umrisse von Dimetrodonten, Stegodonten und Pterrordaktylen ausmachen. Als der Raptor die Zeichnung vervollständigt hat, sieht er wieder zu Euch auf, fletscht seine Zähne und schnappt ein paar Mal mit dem Maul.\n\nAnscheinend hat Euer Gifthautjunges Hunger auf frisches Fleisch von diesen Tieren. Findet und tötet Dimetrodonten, Stegodonten oder Pterrordaktylen im Krater von Un'Goro und füttert Euer hungriges Junges mit ihrem Fleisch.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 15 frische Dinosaurierfleischstücke an ihn verfüttert.", completion = "Das Gifthautjunge scheint mit der gewaltigen Mahlzeit, die Ihr ihm serviert habt, durchaus zufrieden. Es lässt sich allerdings schwer sagen, wann es wieder hungrig sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13890] = { id = 13890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schürt das Feuer", description = "Dies ist keine leichte Aufgabe, {race}!\n\nEs treffen weitere Schiffe ein und ohne den Leuchtturm werden sie sich verirren – oder noch Schlimmeres! Hiermit wird Euch die Aufgabe übertragen, sein Feuer am Brennen zu erhalten.\n\nSammelt den Tran der Hydras in diesen Gewässern und bringt ihn dann zu dieser Schmiede hier, damit daraus Öl hergestellt wird.\n\nWerft Ihr dieses Öl in das Feuer des Leuchtturms, wird uns das die Zeit verschaffen, die wir benötigen.", sourceObjective = "Kommandant Grimmfang in Zoram'gar will, dass Ihr das Öl einer Nebelpeitscherhydra ins Feuer des Leuchtturms gießt.", completion = "Gute Arbeit, {race}!\n\nKeine Schiffe werden mehr auf Grund laufen - dank Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[13891] = { id = 13891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verschlinger Dunkelküstes", description = "Jetzt, da die Kreaturen Dunkelküstes in Sicherheit sind, sollten wir unsere Aufmerksamkeit dem Artefakt widmen, das Ihr im See gefunden habt. Ich glaube, es handelt sich dabei um die Arbeit der Diener der Alten Götter. Wir werden diese Feinde mit den lebensspendenden Energien zerstören, die Dunkelküste besitzt! Bringt den Lebensbringerschössling zum Ufer des Sees südlich von hier. Bewegt ihn über die Wasser des Sees; das sollte das alte Artefakt ausschalten.\n\nSeid vorsichtig, {name}. Das Artefakt wird sicherlich von irgendetwas bewacht.", sourceObjective = "Verwendet den Lebensbringerschössling am Ufer des flachen Sees südlich des Hain der Uralten und zerstört das verschlingende Artefakt und seinen Bewacher.", progress = "Ich wage es gar nicht, zu fragen, {name}, konntet Ihr das Artefakt zerstören? Was ist mit dem Bewacher?", completion = "Bei Elune, wie seht Ihr denn aus? Das muss ein heftiger Kampf gewesen sein! Ihr seid voller... nun, es sieht ein wenig wie Fischsuppe aus...\n\nWenn ein einfacher Diener solch Leid hier in Dunkelküste auslösen kann, möchte ich mir gar nicht erst überlegen, welche Katastrophen einer der Altvorderen anrichten könnte.\n\nWenigstens sind die Tiere vorerst in Sicherheit. Ich werde den von Euch geschaffenen Schössling pflanzen, um dem zerstörten Land bei der Regeneration zu helfen. Ich danke Euch, {name}! Ich würde Euch ja umarmen, aber, ihr wisst ja... Fischsuppe.", sourceObjectiveStatus = "unverified-source-field" }
quests[13892] = { id = 13892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Spuren hinterlassen", description = "Südwestlich von hier liegt der Leichnam eines Wesens, das in irgendeiner Verbindung zu den Alten Göttern steht, die die Schattenhammerkultisten verehren.\n\nEs wurde vor unserer Zeit besiegt - wenn nicht von den Titanen selbst, so sicherlich von einer ihrer Schöpfungen.\n\nIn der letzten Zeit haben wir zunehmend Aktivitäten der Kultisten beobachtet und das kann nur bedeuten, dass uns etwas Schreckliches bevorsteht.\n\nWir müssen herausfinden, was sie dort vorhaben, und warum. Nehmt diese Figur. Sie wird Euch dabei helfen, bei Euren Untersuchungen unbemerkt zu bleiben.", sourceObjective = "Schleicht in die Meistergleve und beobachtet mit Hilfe der Pantherfigur die Schattenhammerkultisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13893] = { id = 13893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soggoth und Kronn", description = "Die Meistergleve ist der Ort einer uralten Schlacht, {name}. Die Titanen haben zwanzig ihrer Steinriesen gegen Soggoth ausgesandt.\n\nVon diesen zwanzig Riesen hat nur einer überlebt.\n\nAuf den Tafeln steht geschrieben, dass Kronn, der größte aller Steinriesen, sich von Soggoths Ranken hat einfangen lassen - nur lange genug, um dem Schädel der Kreatur näher zu kommen - nahe genug für sein mächtiges Schwert.\n\nEs ist gut, dass er tot ist... wir haben nicht wirklich zwanzig weitere Steinriesen zur Verfügung, um ihn erneut aufzuhalten.", sourceObjective = "Kehrt mit den neuen Informationen zu Larien beim Hain der Uralten zurück.", completion = "Die Geschichte des Zwerges ist besorgniserregend... doch sehr aufschlussreich. Es scheint, als hätten wir mehr als eine Möglichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13895] = { id = 13895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schlummernden Uralten", description = "Wir haben keine zwanzig Steinriesen, um uns dem Feind anzunehmen, aber wir Riesen aus uraltem Holz sind so stark wie jeder Fels.\n\nSeht Euch um, {race}. Mein Volk schläft... und doch werden sie dem Horn des Bewahrers folgen, wenn es von ihnen verlangt wird.\n\nIhr könnt Aros, den Bewahrer des Hains, jenseits der Brücke nordöstlich von hier finden.\n\nBerichtet ihm vom Ernst der Lage.", sourceObjective = "Findet Aros nordöstlich vom Hain der Uralten in Dunkelküste.", completion = "Aros Körper ist leblos, doch er ist noch warm. Vielleicht sind seine Mörder in der Nähe.", sourceObjectiveStatus = "unverified-source-field" }
quests[13896] = { id = 13896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgegrabenes Wissen", description = "Hört gut zu, {name}. Wir müssen mehr über unseren Feind in Erfahrung bringen.\n\nSüdwestlich von hier, hinter der Meistergleve, sind ein paar Ausgrabungsleiter der Zwerge, die die Ruinen in der Nähe untersuchen.\n\nVielleicht haben sie Wissen zu Tage gebracht, das uns nützlich sein könnte.", sourceObjective = "Sprecht mit Archäologe Groff bei Wirrbarts Ausgrabung.", completion = "Ja, wir wissen das eine oder andere über Soggoth. Die Frage ist, ob Ihr wirklich mehr erfahren möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13897] = { id = 13897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Dunkelküste", description = "Die Urtume des Hains sind uns zu Hilfe gekommen, {name}. Ich sehe selbst in diesem Augenblick durch ihre Augen.\n\nDer Schattenhammer muss sein Ritual schneller durchführen als ursprünglich geplant und bisher haben sie nur einen Teil des gefürchteten Soggoth wieder zum Leben erwecken können.\n\nZerstört diesen Teil, bevor es zu spät ist, {name}. Ich werde andernorts gebraucht.\n\nKehrt zu den Druiden am Hain der Uralten zurück, wenn Ihr fertig seid. Sie werden Euch weitere Anweisungen erteilen.", sourceObjective = "Tötet den Avatar von Soggoth in der Meistergleve.", completion = "Nun können wir in Frieden ruhen, {name}. Es scheint, als wurde Dunkelküste gerettet. Und Ihr verdient den Dank dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[13898] = { id = 13898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blatt wendet sich gegen uns", description = "Wir können die Naga nicht ungestraft davonkommen lassen, {name}. Der Mord an dem Bewahrer des Hains ist eine Kriegserklärung.\n\nIhr könnt ihre Höhle auf der Insel Nazj'vel weit im Südwesten finden.\n\nÜberbringt ihnen eine deutliche Nachricht.", sourceObjective = "Tötet 8 Myrmidonen der Dunkelschuppen.", completion = "Gut gemacht, {name}. Die Naga wünschen die Zerstörung und Unterwerfung aller Oberflächenbewohner. Zögert nicht, sie aus unseren Landen zu vertreiben und sie zurück in die schattigen Tiefen des Ozeans zu drängen, dort, wo sie hin gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[13899] = { id = 13899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegsfürst der Dunkelschuppen", description = "Wenn die Naga sich mit dem Schattenhammer verbünden wollen, so gnade ihnen Elune.\n\nBegebt Euch zu ihrer Höhle auf der Insel Nazj'vel und findet den Anführer der Naga, den Kriegsfürst Zornrücken.\n\nVielleicht kann das Horn der Urtume noch gerettet werden.", sourceObjective = "Tötet Kriegsfürst Zornrücken in Nazj'vel.", completion = "Der Kriegsfürst scheint das Horn nicht bei sich zu haben. Möglicherweise sprach er die Wahrheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13900] = { id = 13900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Opfer für Azshara", description = "Der Kriegsfürst sagte, dass das Horn der Urtume als Opfergabe an Azshara oben in Nazj'vel gegeben wurde.\n\nVielleicht ist es noch nicht zu spät, das alte Relikt vor der Zerstörung zu retten.", sourceObjective = "Haltet die Priesterinnen der Dunkelschuppen davon ab, das Horn der Urtume oben in Nazj'vel Azshara zu opfern.", completion = "Ihr habt gute Arbeit geleistet, {name}. Leider ist die Schlacht noch nicht gewonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13901] = { id = 13901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefe Verzweiflung", description = "Dieses Nagaproblem erweist sich als größer, als es auf den ersten Blick ersichtlich war, {class}. Es scheint, als ob sich die Situation nicht einfach dadurch klärt, dass wir ihre Anzahl verringern. Um sie in ihre Schranken zu weisen, müssen wir einen nachhaltigeren Eindruck auf sie machen.\n\nReist zum nördlichen Ende des Zoramstrands und betretet die Tiefschwarze Grotte. Sobald Ihr dort seid, zeigt den Naga, dass ihre Anwesenheit in diesem Gebiet nicht länger toleriert werden wird!", sourceObjective = "Tötet 6 Gezeitenpriesterinnen der Tiefschwarzen Grotte.", completion = "Ausgezeichnet!\n\nDie Naga sollen zurück ins Meer, wo sie hergekommen sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[13902] = { id = 13902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Offensive festigen", description = "Unsere Arbeit in Dunkelküste ist längst nicht vorbei. Wir haben die Landmassen vor dem Zerbersten bewahrt, aber unsere Feinde sind noch immer stark hier vertreten.\n\nIch möchte, dass Ihr südlich von hier ein paar Druiden am Hain der Uralten aufsucht. Sie werden von einem alten Freund von mir angeführt, von Balren von der Klaue.\n\nSagt ihnen, die Zeit ist reif, um die Schlacht zu unseren Feinden zu bringen. Ich werde nachkommen und sie unterstützen, sobald wir diese Gegend stabilisiert haben.", sourceObjective = "Sprecht mit Balren von der Klaue am Hain der Uralten in Dunkelküste.", completion = "Wenn Malfurion Euch vertraut, so werde ich es ihm gleichtun. Ihr werdet sehen, dass unsere Feinde im Süden weitaus zahlreicher sind als wir.\n\nWo rohe Gewalt und Übermacht gegen uns sind, werden Strategie und Täuschung unsere größten Vorteile sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13903] = { id = 13903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorishigelee", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen des Jungen scheinen verschiedene Arten großer Insekten darzustellen, vielleicht die Gorishisilithiden. Das Junge beendet seine Zeichnung, zeigt mit einem kurzen Arm darauf, schnappt mit dem Kiefer und leckt sich das Mäulchen.\n\nEs möchte wohl, dass Ihr zur Wuchernden Narbe, im Zentrum des südlichen Kraters von Un'Goro geht und Silithidenfleisch sammelt. Wenn Ihr das Fleisch habt, gebt es Eurem hungrigen Jungen zu fressen.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 10 Stück Silithidenfleisch an ihn verfüttert.", completion = "Das Gifthautjunge grinst Euch mit spitzen Zähnen zufrieden an und rollt sich dann zum Schlafen zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13904] = { id = 13904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pochiert, gerührt oder roh?", description = "Der Magen des Gifthautjungen knurrt, als es mit seinen Ärmchen wedelt, um Eure Aufmerksamkeit zu bekommen. Es beginnt, die Umrisse von Silithiden in die Erde zu kratzen, darunter einige Ovale. Es sieht Euch hoffnugsvoll an und deutet auf die Kreise.\n\nSie können nur Silithideneier darstellen. Der Giftige Unterschlupf im westlichen Tanaris, nahe der Grenze zum Krater von Un'Goro, wäre sicherlich ein guter Ort, um die Eier zu finden, die Euer kleines Junges haben möchte.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 12 Silithideneier an ihn verfüttert.", completion = "Euer Junges leckt sich das Mäulchen, nachdem es die Riesenportion Silithideneier verschlungen hat. Für einen Moment glaubt Ihr, es sieht ein wenig enttäuscht aus, dass die Fütterungszeit schon vorbei ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13905] = { id = 13905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sengende Rocfedern", description = "Das Junge sieht Euch für einen Moment an, ein wenig, als ob es sich fragt, ob Ihr verstehen werdet. Es kratzt ein Bild von einem Paar Federn in die Erde, bevor es mit einer Klaue auf die Lederbänder um seine Ellbogen und Knie zeigt.\n\nEs sieht nicht hungrig aus, aber wofür könnten die Federn gut sein?\n\nEs will sie wohl als Schmuck haben, wie Ihr ihn an den anderen Raptoren gesehen habt. Die größten Federn findet man bei den sengenden Rocs, welche die großen Tierknochen in der westlichen Tanariswüste umschwärmen, nordöstlich des Disteltals.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr ihm 5 Federn von sengenden Rocs bringt.", progress = "Euer Gifthautjunges sieht Euch erwartungsvoll an.", completion = "Das Gifthautjunge nimmt die Federn an sich und begutachtet sie, während es einige an seine Armbänder hält.", sourceObjectiveStatus = "unverified-source-field" }
quests[13906] = { id = 13906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie werden so schnell erwachsen", description = "Durch Eure fachmännische Fütterung und Pflege wird Euer Gifthautjunges schnell heranwachsen. Im Laufe seines Wachstums werden seine ersten Zähne durch bleibende ersetzt. Solltet Ihr die Milchzähne aufbewahren, werdet Ihr mit Leichtigkeit sagen können, wann es ausgewachsen genug sein wird, um zugeritten zu werden.\n\nEuer Junges wird Euch wissen lassen, was es braucht - gebt also genau Acht. Bringt mir Euren kleinen Ravasaurus und die Materialien für Euren Sattel, wenn er all seine Zähnchen verloren hat, und ich werde mich um den Rest kümmern.", sourceObjective = "Bringt 20 Gifthautzähnchen, das Gifthautjunge, 20 Stück Runenstoff, 20 unverwüstliches Leder und 80 Gold zu Mor'vek im südöstlichen Teil des Marschlands im Krater von Un'Goro.", progress = "Habt Ihr gut auf den Raptor achtgegeben?", completion = "Sieht aus, als hättet Ihr die Aufzucht überstanden, ohne einander umzubringen.\n\nDa, alles ist fertig. Ich habe Euren Gifthautravasaurus so abgerichtet, dass er Euch folgt, wenn Ihr in diese Pfeife blast.\n\nNur wenige besitzen die nötige Hingabe, um einen der kleinen Ravasaurier per Hand großzuziehen, aber sie sind die Mühe auf jeden Fall wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13907] = { id = 13907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen säubern", description = "Die Großbärte aus Eisenschmiede haben mich geschickt, um nach Wirrbarts Ausgrabung zu sehen, als sie von dem Desaster erfuhren. Seht Euch nur um! Wertvolle Artefakte in das Meer geschwemmt und monatelange Ausgrabungen in wenigen Minuten zunichtegemacht.\n\nAls die Gezeitenwelle eintraf, vernichtete sie die Lager der Murlocs an der Küste. Gute Nachrichten? Nein, kein Glück für uns. Die Überlebenden suchen in den Ruinen Unterschlupf und fügen der Ausgrabung mehr Schaden zu, als es die Elemente je gekonnt hätten. Könntet Ihr Eure Watstiefel anziehen und Euch für mich um die Sache kümmern?", sourceObjective = "Tötet 10 Orakel der Grauflossen oder Flüchtlinge der Grauflossen, die in Wirrbarts Ausgrabung Unterschlupf suchen.", completion = "Bravo, {name}! Schauen wir die Lage doch jetzt noch einmal an.\n\nWie? MEHR Murlocs? Ich schwöre bei meinen Steinen, je mehr Murlocs man tötet, umso mehr scheinen aufzutauchen. Oder bilde ich mir das nur ein? Wir brauchen eine andere Vorgehensweise.", sourceObjectiveStatus = "unverified-source-field" }
quests[13908] = { id = 13908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufsatteln", description = "Euer Ravasaurus ist stark und gesund, und Ihr habt Euch wirklich gut aneinander gewöhnt. Ihr werdet ihn reiten können, sobald ich Euren Sattel und das Zaumzeug fertiggestellt habe. Genau wie Ihr müssen die Materialien speziell behandelt werden, um den Giften zu widerstehen, die der Raptor erzeugt.\n\nAlles, was Ihr tun müsst, ist mir etwas unverwüstliches Leder, Runenstoff und Geld für den Rest des Materials zu bringen. Dann werde ich den Sattel im Handumdrehen fertiggestellt haben.", sourceObjective = "Bringt Mor'vek im südöstlichen Teil der Marschen im Krater von Un'Goro 20 unverwüstliche Leder, 20 Runenstoff und 80 Gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[13909] = { id = 13909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibgut übrig?", description = "Wir werden eine Lösung finden, {name}. Wir brauchen nur ein bisschen zwergische Raffinesse. Denk nach, Groffy, denk schon!\n\nDie Murlocs wollen doch nur Unterschlupf, oder? Lasst uns konstruktiv sein. Das meine ich wortwörtlich.\n\nWährend der Katastrophe wurden alle möglichen Sachen an Land geschwemmt und ein paar der alten Hütten der Murlocs sind bestimmt noch benutzbar. Lauft an der Küste entlang und sucht für Murlocs geeignete Baumaterialien. Ihr werdet nicht lange suchen müssen.", sourceObjective = "Findet 5 Stück verwertbare Grauflossentrümmer an der Küste und am Wasser in der Nähe von Wirrbarts Ausgrabung.", progress = "Nass genug für Euch?", completion = "<Archäologe Groff schaut die Trümmer durch.>\n\nNaja, es findet sich kaum etwas, auf dem nicht herumgetrampelt wurde oder das nicht wie eine Toilette heruntergespült aussieht. Aber mit einem Dach drauf wird es schon ausreichen.\n\nSagt mir, {name}, habt Ihr Euch je als Architekten gesehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[13910] = { id = 13910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Zuhause", description = "Können wir es bauen? Natürlich! Westlich von der Ausgrabung habe ich ein Banner an der Küste aufgestellt. Der Sand ist stabil und eignet sich ebenso gut als Bauort wie jeder andere. Nehmt mein Werkzeug und die Trümmerstücke und baut diesen störrischen Plagegeistern ein neues Zuhause.", sourceObjective = "Baut eine Hütte für die Murlocs an der von Groff markierten Stelle an der Küste in der Nähe.", progress = "Und, was macht unser neues Heim mit Meerblick?", completion = "Haha, das klingt nach einem guten Haufen, den Ihr da gebaut habt. Sind sie darauf angesprungen? Gut, gut. Sehen wir mal, ob mein Plan erfolgreich ist.\n\n<Archäologe Groff beobachtet, wie aus allen Richtungen massenweise Murlocs zum Strand gelaufen kommen. Seine Augenbrauen ziehen sich enger und enger zusammen.>\n\nWas habe ich nur getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[13911] = { id = 13911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der geistesabwesende Ausgrabungsleiter", description = "Und wer seid Ihr nochmal? {name}? Kenne ich Euch? Wenn die Liga Euch schickt, dann könnt Ihr ihnen gleich sagen, dass ich hierbleibe! Ich gehe nicht ohne meinen Fund. Ich hielt ihn bereits in den Händen! Und dann brach plötzlich Geschrei aus. Und es wurde nass.\n\nHört gut zu, wer immer Ihr auch seid, ich habe alle Ereignisse von dem Tag der Gezeitenwelle in meinem Tagebuch aufgeführt. Und ich weiß auch, wo zu suchen ist. Nach dem Tagebuch, nicht nach dem Fund. Helft mir, eins zu finden, damit wir das andere finden können. Oder umgekehrt! Könnt Ihr mir folgen? Gut, dann folgt mir!", sourceObjective = "Eskortiert den verwirrten Ausgrabungsleiter Wirrbart zu seinem Tagebuch. Sprecht mit Juniorarchäologe Ferd, wenn Ihr fertig seid.", completion = "Ah, Ihr konntet dem Ausgrabungsleiter helfen, sein Tagebuch zu finden! Ich hätte nie gedacht, dass es die ganze Zeit hier war.\n\nEines Tages müsst Ihr mich zu der anderen Ausgrabungsstätte bringen, von der er dauernd erzählt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13912] = { id = 13912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammige Geheimnisse", description = "Hinter Wirrbarts vergesslichem Äußeren befindet sich der Geist eines Genies, ein Mysterium im Gewand eines Senilen. Ich werde den alten Herrn nicht aufgeben. Seht hier, was ich in seinen Notizen gefunden habe... nicht hier... nein, das ist eine Einkaufsliste... Hier, auf der Seite, auf der er versucht herauszufinden, welches Jahr es ist: die Scheibe!\n\nWir glauben, dass es sich bei diesem Artefakt der Titanen um eine Art verschlüsselte Speicherscheibe handelt. Wir waren gerade dabei, es vorsichtig auszugraben, als das Desaster losbrach und nun hoffen wir, dass es sich noch immer in den Ruinen befindet. Taucht und sucht für mich danach!", sourceObjective = "Findet eine schlammverkrustete uralte Scheibe in den Ruinen in der Nähe.", progress = "Ihr habt sie gefunden? Das ist gut. Groff möchte von hier so schnell wie möglich aufbrechen.", completion = "Spektakulär! Gute Arbeit, {name}! Wirrbart würde Euch sicher persönlich danken, wenn er sich an Euren Namen erinnern könnte.\n\nSeht Euch die Oberfläche der Scheibe an - diese mikroskopisch kleinen Verzierungen sind fantastisch. Dieses Rad enthält mit Sicherheit viele Informationen, wir müssen nur herausfinden, wie wir sie verstehen können...", sourceObjectiveStatus = "unverified-source-field" }
quests[13913] = { id = 13913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben unsere Gnome", description = "Der Sprengstofftrupp der Gnome, die wir aus der Tüftlerstadt angefordert haben, ist letzte Woche eingetroffen. Gerade rechtzeitig, um uns bei einem Angriff der Horde zu unterstützen. An dem Tag haben wir viele Soldaten verloren. Der Großteil der Gnomtruppen ist gefallen. Jetzt steht uns das Wasser bis zum Hals, die Silberwindzuflucht ist verloren und wir haben nur noch ein dutzend Gnome.\n\nIch flehe Euch an, helft uns, {name}. Reist nach Osten zur Silberwindzuflucht und seht Euch nach überlebenden Gnomen um. Sie wurden alle von einem großen, gnadenlosen Orc namens Thundrak weggekarrt. Findet ihn und Ihr findet unsere Gnome.", sourceObjective = "Rettet Boog den \"Zahnradflüsterer\" und Minx aus Schmerzensmeister Thundraks Wagen der nimmer endenden Agonie.", completion = "Habt Dank, {name}. Traurige Kunde bringt Ihr vom Rest der Gnomtruppe, aber zumindest konntet Ihr ein paar retten. Dafür bin ich Euch dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[13914] = { id = 13914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sengende Rocfedern", description = "Das Junge sieht Euch für einen Moment an, ein wenig, als ob es sich fragt, ob Ihr verstehen werdet. Es kratzt ein Bild von einem Paar Federn in die Erde, bevor es mit einer Klaue auf die Lederbänder um seine Ellbogen und Knie zeigt.\n\nEs sieht nicht hungrig aus, aber wofür könnten die Federn gut sein?\n\nEs will sie wohl als Schmuck haben, wie Ihr ihn an den anderen Raptoren gesehen habt. Die größten Federn findet man bei den sengenden Rocs, welche die großen Tierknochen in der westlichen Tanariswüste umschwärmen, nordöstlich des Disteltals.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr ihm 5 Federn von sengenden Rocs bringt.", progress = "Euer Gifthautjunges sieht Euch erwartungsvoll an.", completion = "Das Gifthautjunge nimmt die Federn an sich und begutachtet sie, während es einige an seine Armbänder hält.", sourceObjectiveStatus = "unverified-source-field" }
quests[13915] = { id = 13915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sooooo hungrig", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen sind grob, aber Ihr könnt die Umrisse von Dimetrodonten, Stegodonten und Pterrordaktylen ausmachen. Als der Raptor die Zeichnung vervollständigt hat, sieht er wieder zu Euch auf, fletscht seine Zähne und schnappt ein paar Mal mit dem Maul.\n\nAnscheinend hat Euer Gifthautjunges Hunger auf frisches Fleisch von diesen Tieren. Findet und tötet Dimetrodonten, Stegodonten oder Pterrordaktylen im Krater von Un'Goro und füttert Euer hungriges Junges mit ihrem Fleisch.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 15 frische Dinosaurierfleischstücke an ihn verfüttert.", progress = "Das Gifthautjunge leckt sich das Maul und legt den Kopf schräg.", completion = "Das Gifthautjunge scheint mit der gewaltigen Mahlzeit, die Ihr ihm serviert habt, durchaus zufrieden. Es lässt sich allerdings schwer sagen, wann es wieder hungrig sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13916] = { id = 13916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pochiert, gerührt oder roh?", description = "Der Magen des Gifthautjungen knurrt, als es mit seinen Ärmchen wedelt, um Eure Aufmerksamkeit zu bekommen. Es beginnt, die Umrisse von Silithiden in die Erde zu kratzen, darunter einige Ovale. Es sieht Euch hoffnugsvoll an und deutet auf die Kreise.\n\nSie können nur Silithideneier darstellen. Der Giftige Unterschlupf im westlichen Tanaris, nahe der Grenze zum Krater von Un'Goro, wäre sicherlich ein guter Ort, um die Eier zu finden, die Euer kleines Junges haben möchte.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 12 Silithideneier an ihn verfüttert.", progress = "Das Junge sieht Euch an.", completion = "Euer Junges leckt sich das Mäulchen, nachdem es die Riesenportion Silithideneier verschlungen hat. Für einen Moment glaubt Ihr, es sieht ein wenig enttäuscht aus, dass die Fütterungszeit schon vorbei ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13917] = { id = 13917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorishigelee", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen des Jungen scheinen verschiedene Arten großer Insekten darzustellen, vielleicht die Gorishisilithiden. Das Junge beendet seine Zeichnung, zeigt mit einem kurzen Arm darauf, schnappt mit dem Kiefer und leckt sich das Mäulchen.\n\nEs möchte wohl, dass Ihr zur Wuchernden Narbe, im Zentrum des südlichen Kraters von Un'Goro geht und Silithidenfleisch sammelt. Wenn Ihr das Fleisch habt, gebt es Eurem hungrigen Jungen zu fressen.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 10 Stück Silithidenfleisch an ihn verfüttert.", completion = "Das Gifthautjunge grinst Euch mit spitzen Zähnen zufrieden an und rollt sich dann zum Schlafen zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13918] = { id = 13918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verbindung der Titanen", description = "Mit der Scheibe ergeben auch ein paar unserer früheren Funde jetzt mehr Sinn. Kurz nach meiner Ankunft hat Ausgrabungsleiter Wirrbart etwas gefunden, dass er für einen prähistorischen Toaster hielt.\n\nIch glaube eher, dass diese Kiste mit Öffnungen ein Lesegerät für besondere Daten ist. Leider ist es auseinandergefallen und mit dem Rest unseres Basislagers weggeschwemmt worden, als die Gezeitenwelle über uns hereinbrach!\n\nEs ist aber sicherlich nicht weit gekommen, {name}. Die Einzelteile sind bestimmt im Sand vergraben. Hier, nehmt meinen einwandfrei funktionierenden Detektor für vergrabene Artefakte, um den Strand damit abzusuchen.", sourceObjective = "Benutzt den Detektor für vergrabene Artefakte am Strand in der Nähe von Wirrbarts Ausgrabung, um 5 uralte Gerätefragmente zu finden. Fügt sie zusammen, um das uralte geschlitzte Gerät zu erhalten.", progress = "Habt Ihr alle Teile des geschlitzten Gerätes zusammengefügt? Möglicherweise müssen wir noch die Überreste von Wirrbarts Pausenbrot von der Datenschnittstelle des uralten Geräts entfernen.", completion = "Ja, ja, JA, das ist es! Seht her, dieser Schlitz hat genau die gleiche Größe wie die uralte Scheibe, genau, wie ich vermutet hatte. Hier ist Eure Belohnung, {name} - Ihr habt sie Euch redlich verdient.\n\n\n\nSeid Ihr bereit, Euch der Geschichte zu stellen? Lasst uns herausfinden, was uns die Uralten zu sagen haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[13919] = { id = 13919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ausflug zum Mondbrunnen", description = "Es hat nicht funktioniert.\n\n<Ein besorgter und verzagter Ausdruck zeichnet Pelturas' Gesicht, als er die Träne aus der Suppe entfernt und sie vorsichtig wäscht.>\n\nDer Ausbruch des Donnergipfels muss sie auf irgendeine Weise beeinträchtigt haben. Ihr müsst die Träne zum Mondbrunnen der Reinheit bringen. Er liegt noch immer unversehrt und von der Macht der Göttin beschützt am südöstlichen Fuß des Vulkans.\n\nDort wascht Ihr sie in den heiligen Wassern von Elune. Was danach geschieht, vermag ich nicht zu sagen. Ich fürchte um das Leben meiner Tochter. Es liegt nun in Euren Händen, {name}.", sourceObjective = "Nehmt Elunes Träne und reinigt sie in den Wassern des Mondbrunnens der Reinheit im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[13920] = { id = 13920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bevor Ihr geht...", description = "In Höllschreis Wacht wird jede Hilfe gebraucht, {name}. Aber bevor Ihr Euch auf den Weg macht, gibt es noch etwas, das hier erledigt werden muss.\n\nDie meisten unserer verderblichen Waren sind während eines Angriffs der Allianz auf See verloren gegangen. Wir müssen genug Nahrungsmittel sammeln, um den Eschentalfeldzug durchführen zu können.\n\nReist nach Osten. Dort findet Ihr reichlich Wild. Kehrt mit dem besten Fleisch zurück, das Ihr für unsere Truppen finden könnt!", sourceObjective = "Bringt 5 Hirschsteaks zu Kommandant Grimmfang in Zoram'gar.", progress = "Ja, {race}?", completion = "Dieses Wildbret sollte die Stimmung unserer Soldaten für die bevorstehende Schlacht heben. Hier habt Ihr etwas für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13921] = { id = 13921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jener, der nach Vergebung sucht", description = "<Eine Stimme aus dem Mondbrunnen durchflutet Euren Geist und gibt Euch ein Gefühl absoluten Friedens.>\n\nIhr sucht eine Heilung für das Kind, aber wisset, das alles seinen Preis hat. Im Osten liegt der Rajenbaumturm. Vor dem Turm neben dem Mondbrunnen steht jemand, welcher der Verderbnis anheimgefallen ist.\n\nAvrus Böswisper sucht Vergebung und Erlösung, {name}. Werdet Ihr ihm helfen, seinen Wunsch zu erfüllen und dadurch Euer eigenes Ziel zu erreichen?", sourceObjective = "Sprecht mit Avrus Böswisper beim Rajenbaumturm im Eschental.", completion = "<Der Satyr grinst spöttisch, aber als ihm klar wird, dass Ihr nicht hier seid, um ihn zu züchtigen, ändert sich sein Gesichtsausdruck.>\n\nEndlich naht meine Erlösung. Ich habe lange auf diesen Tag gewartet und ich glaube, ich weiß, wie ich Euch im Gegenzug dazu helfen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[13922] = { id = 13922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Händen des Widernatürlichen", description = "Mein ehemaliger Klan, die Teufelshufe von Nachtflucht, hat den Himmelssturzsee vor einiger Zeit überfallen. Sie haben Mondsteine geraubt, die in dieser Gegend einzigartig sind.\n\nDiese Mondsteine sind dafür bekannt, große Heilkräfte zu besitzen und können sicherlich dafür verwendet werden, das kleine Mädchen zu heilen, das krank in Astranaar liegt.\n\nNachtflucht liegt an der Straße im Osten, die nach Norden führt. Von ihr zweigen verschiedene Pfade in Richtung Osten ab, die in die Hügel führen und dort findet ihr meine reuelosen Brüder. Sie haben, was Ihr sucht.", sourceObjective = "Erlangt 5 gefallene Mondsteine.", progress = "Fünf Mondsteine werden benötigt, um sicherzustellen, dass das Mädchen geheilt wird.", completion = "Ihr habt alle Mondsteine, die benötigt werden. Und dennoch wird gesagt, dass ein Leben geopfert werden muss, um ein anderes zu retten.\n\nIch werde sicherstellen, dass die Mondsteine Relara um jeden Preis heilen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13923] = { id = 13923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Höllschreis Wacht", description = "Auf ins Schlachtgetümmel, {race}!\n\nHöllschreis Wacht ist eine unserer am stärksten umkämpften Fronten im Eschental. Die Erfahrung wird Euch nützen... vorausgesetzt, Ihr überlebt.\n\nWenn Ihr bereit seid, sprecht mit Andruk. Ich habe mit ihm besprochen, dass er Euch direkt zu Eurem Posten bringt.\n\nSobald Ihr dort eintrefft, macht Hauptmann Goggath ausfindig. Er wird Euch weitere Anweisungen erteilen.\n\nBringt Schmerz und Tod über Eure Feinde! Für die Horde!", sourceObjective = "Sprecht mit Hauptmann Goggath in Höllschreis Wacht.", completion = "Als Kind kommt ihr hierher, {race}.\n\nAls {class} der Horde mit reichlich Kampferfahrung sollt Ihr wieder gehen!\n\nEntweder das, oder Ihr endet als Rabenfutter...", sourceObjectiveStatus = "unverified-source-field" }
quests[13924] = { id = 13924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ende gut", description = "Habt Dank, dass Ihr mich von einem Schicksal errettet habt, das schlimmer ist als der Tod, {name}! Ihr habt mich und das Kind gerettet!\n\nNun, das Kind ist fast gerettet. Alles was Ihr tun müsst, ist die Mondsteine die Straße Richtung Westen nach Astranaar zu bringen. Händigt die Steine Pelturas aus. Er wird wissen, was zu tun ist.\n\nGeht in Frieden. Elune sei gepriesen!", sourceObjective = "Überreicht die geheiligten Mondsteine Pelturas Weißmond in Astranaar im Eschental.", progress = "{name}, seid Ihr das? Seid Ihr mit dem Heilmittel für Relara zurückgekehrt?", completion = "Oh, {name}, Ihr habt meine Tochter gerettet! Ich weiß, dass die Macht der Mondsteine meiner Tochter Ihre Kraft zurückgeben wird!\n\nEure Hilfe war unermesslich wertvoll und ich kann sie Euch nie vollständig vergelten, aber... Bitte, nehmt das hier. Abgesehen von Relara, ist dies mein wertvollster Besitz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13925] = { id = 13925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stückchen Vorbeugen", description = "Seid Ihr vertraut mit den Altvorderen, {name}? Onu und ich sind uns sicher, dass das von Euch im See gefundene Artefakt nur ihr Werk sein kann. Und es verzehrt Dunkelküste weiterhin. Irgendetwas hat die von uns lang totgeglaubten Schrecken erweckt. Ein Schrecken, dem weder Ihr noch ich gewachsen sind. Aber zuerst müssen wir uns um die Wildtiere kümmern.\n\nHier, in diesem Schössling ist die ganze Lebensessenz, die Ihr mir gebracht habt. Ich glaube, wir können damit die Fauna der Gegend retten. Versucht es zuerst an einem nicht verzehrten Bären, Hirsch oder Mondpirscher und berichtet mir, was geschieht!", sourceObjective = "Testet den Lebensbringerschössling an einem gesunden ergrauten Distelbären, Weißschwanzhirsch, Mondpirscherpatriarchen oder einer gesunden Mondpirschermatriarchin in der Nähe.", progress = "Der Schössling, den Ihr bei Euch tragt, wächst ohne Unterbrechung an Macht. Leben ist erneuerbar, {name}. Hat es funktioniert?", completion = "Interessant... Es scheint, als könnte unser Heilmittel die Wildtiere retten, aber Ihr habt noch etwas anderes gesehen? Etwas Bösartiges, Wütendes gespürt?\n\nDas ist ein gutes Zeichen, {name}. Wer auch immer hinter diesem Problem steckt ärgert sich, und das bedeutet, das wir auf dem richtigen Weg sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13926] = { id = 13926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleines Waisenkind Roo von den Orakeln", description = "Die Waisen haben sich auf eine Gelegenheit gefreut, einen Freund wie Euch zu treffen, {name}. Es ist wunderbar, dass Ihr zugestimmt habt, Euch um einen von ihnen zu kümmern.\n\nNehmt diese Pfeife. Mit Ihr könnt Ihr das Waisenkind rufen, das Ihr unter Eure Fittiche nehmen möchtet. Sie wird nur für begrenzte Zeit funktionieren - de facto nicht länger als die Kinderwoche selbst dauert.\n\nBitte, {name}, ruft Euer Waisenkind. Es wird sich freuen, Euch zu treffen und mit Euch zusammen die Sehenswürdigkeiten von Nordend anzusehen.", sourceObjective = "Sprecht mit Waisenmatrone Aria und benutzt dann die Pfeife des Orakelwaisenkindes, um das Waisenkind zu rufen, für das Ihr während der Kinderwoche sorgen werdet.", progress = "Du dich um uns kümmern?", completion = "Du bringst uns weg von Wauwaujungen? Gut. Wir dich schon mögen. Wauwaujunge haben alle unsere Lieblingsspielzeuge weggenommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13927] = { id = 13927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleines Waisenkind Kekek von den Wolvar", description = "Die Waisen haben sich auf eine Gelegenheit gefreut, einen Freund wie Euch zu treffen, {name}. Es ist wunderbar, dass Ihr zugestimmt habt, Euch um einen von ihnen zu kümmern.\n\nNehmt diese Pfeife. Mit Ihr könnt Ihr das Waisenkind rufen, das Ihr unter Eure Fittiche nehmen möchtet. Sie wird nur für begrenzte Zeit funktionieren - de facto nicht länger als die Kinderwoche selbst dauert.\n\nBitte, {name}, ruft Euer Waisenkind. Es wird sich freuen, Euch zu treffen und mit Euch zusammen die Sehenswürdigkeiten von Nordend anzusehen.", sourceObjective = "Sprecht mit Waisenmatrone Aria und benutzt dann die Pfeife des Wolvarwaisenkindes, um das Waisenkind zu rufen, für das Ihr während der Kinderwoche sorgen werdet.", progress = "Waisenfrau sagen, Kekek mit dir gehen.", completion = "Du bringst Kekek zum Jagen? Ist gut von alter Waisendame wegzukommen, die Kekek nicht jagen lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13928] = { id = 13928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Gefallenen", description = "Meine Schildwachen und ich haben von Bewahrer Ordanus den Befehl erhalten, hier zu bleiben und den Turm zu verteidigen. Bisher konnten wir die Horde erfolgreich zurückschlagen, aber jetzt schlagen sie einen Bogen um uns und greifen unseren Zufluchtsort im Norden direkt an.\n\nDer Bewahrer schickt seine Dryaden aus, um die Bäume zu verteidigen, aber sie scheinen der Vorhut der Kriegshymnenorcs nicht gewachsen.\n\nIhr müsst dorthin und so viele Leichen der Lachenden Schwestern einsammeln, wie Ihr könnt. Bringt sie zu Halannia im Baum am Zufluchtsort. Sie wird wissen, was zu tun ist.", sourceObjective = "Sammelt 10 Leichen der Lachenden Schwestern.", progress = "Ich bin erstaunt, dass Ihr die Reihen der Horde durchbrechen konntet und es geschafft habt, hier hereinzukommen, {race}.", completion = "Habt Dank, {class}. Wir haben alle Hände voll damit zu tun, diesen Zufluchtsort zu verteidigen, aber wenn ich wieder zu Atem komme, werde ich dafür sorgen, dass diese Schwestern ins Leben zurückkehren, wenn es der Göttin gefällt.\n\nIhr habt Euren Heldenmut bewiesen... Wir könnten Eure Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13929] = { id = 13929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der grööößte Baum überhaupt!", description = "Bevor der große Krieg passiert war und wir das Dorf verlassen haben, wir erinnern uns dran, wie Soo-say uns vom größten von allen Bäumen erzählt hat!\n\nSoo-say es nennen Grauschlund oder so. Soo-say uns erzählen, es ist in der Mitte von den Kritzlihügeln. Nein, warte. Das nicht was Soo-say gesagt hat. Soo-say sagt Grizzlyhügel. Jetzt wir uns erinnern! Großer Baum und in der Mitte von Grizzlyhügeln. Kann gar nicht übersehen!\n\nDu uns bringen dahin, oki? Wir uns anschauen den großen Baum von innen? Soo-say sagen, große Bärenleute leben auch im Baum. Vielleicht wir sie auch sehen.", sourceObjective = "Besucht mit Eurem Waisenkind Roo den Grauschlund. Falls er nicht anwesend ist, wenn Ihr den großen Baum betretet, solltet Ihr nach ihm rufen.", completion = "Wir haben nicht gewusst, dass Bäume sooo groß werden können. Nee. Vielleicht die Großen hatten besonderen Plan für sie?", sourceObjectiveStatus = "unverified-source-field" }
quests[13930] = { id = 13930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimat der Bärenleute", description = "Hochschamane Rakjak uns immer Geschichten von mächtigen Kriegern erzählt, auch von weit weit weg. Manchmal er hat erzählt über riesige Bärenleute, wo einen großen Krieg um eine große Baumstadt kämpfen.\n\nVielleicht du bringt Kekek dort hin, Baum anschauen, Kampf anschauen! Hochschamane Rakjak erzählt Kekek, die große Baumstadt Grauschlund steht in der Mitte von den Grizzlyhügeln.\n\nKekek hat nie eine Stadt gesehen, bevor er kennengelernt hat die Waisendame, aber die Stadt hier hat keine Krieger, nur Männer in lila Kleidern. Kekek will richtige Krieger sehen, die um eine richtige Stadt kämpfen.", sourceObjective = "Besucht mit Eurem Waisenkind Kekek den Grauschlund. Falls er nicht anwesend ist, wenn Ihr den großen Baum betretet, solltet Ihr nach ihm rufen.", completion = "Das sein Kekeks Art von Stadt. Bärenleute kämpfen genauso um ihr Zuhaus, wie Wildherzen es tun. Waisendame sagt Kekek, er soll nicht mit anderen Welpen kämpfen. Kekek kämpft trotzdem.", sourceObjectiveStatus = "unverified-source-field" }
quests[13931] = { id = 13931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Jahr, ein neues Souvernir", description = "Wir versorgen nicht nur jedermann mit Gebräu, sondern wir haben auch Krüge zu vergeben! Wunderschöne Andenken, die auf die legalste Weise überhaupt erworben wurden! Hier habt Ihr einen Gutschein.\n\nSprecht mit Blix, er hält sich irgendwo hinten beim Braufestlager auf. Er ist ziemlich seltsam, vor allem weil er jetzt immer diese Brille trägt. Er wird Euren Gutschein entgegennehmen und kümmert sich auch sonst um alle Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Was ist das? Ein Gutschein für einen Braufestkrug? Ihr trinkt also gerne? Großartig! Sobald Ihr den Krug habt, solltet Ihr Euch ein paar Schluck gönnen... und noch ein paar mehr... und mehr... Dann, und das ist wichtig, kommt wieder hierher zu mir.\n\nIch weiß doch, dass Ihr wieder hierherkommt. Wenn Ihr Eure Gutscheine einlösen möchtet, dann müsst Ihr hierher zu mir.\n\nNaja, hier ist der Krug. Vergesst nicht, später noch einmal mit mir zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13932] = { id = 13932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Jahr, ein neues Souvernir", description = "Beim Braufest geht es nicht nur um Widderrennen, sondern auch ums Trinken! Solltet Ihr einen Moment Zeit haben, dann bringt diesen Gutschein zu Belbi Blitzknips. Sie hält sich irgendwo im hinteren Teil des Braufestlagers auf. Falls Ihr sie nicht sehen könnt, keine Sorge, sie wird Euch mit Sicherheit entdecken.\n\nNaja, bringt Ihr auf jeden Fall diesen Gutschein für Euren kostenlosen Braufestkrug. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Ooch, es ist nur ein Gutschein für einen Braufestkrug... vielleicht gebt Ihr Euch ja auch nur so unnahbar. So, hier habt Ihr den diesjährigen Krug.\n\nIch nehme an, dass ich Euch noch öfter hier sehen werde. Denn wenn Ihr Eure Gutscheine einlösen möchtet, dann bin ich Euer Mädel hier...\n\noder vielleicht seins...\n\nooohhh.... oder seins...", sourceObjectiveStatus = "unverified-source-field" }
quests[13933] = { id = 13933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bronzedrachenschrein", description = "Manchmal Hochorakel Soo-say erzählt Geschichten über Schreine für Drachendinger, nicht wie großer Regenstein, aber anders. Soo-say sagt uns, vielleicht wir uns dort selbst sehen, aber nicht wie in Glitzer-Glitzer. Soo-say meint, wir uns dort sehen, wie wenn in vielen Jahren später.\n\nBringst du uns dorthin? Wir uns erinnern, Schrein für Bronzedrachendinger ist in einem Ort, der Drachenöde heißt. Soo-say sagt, großer Regenstein zeigt ihm Schrein im Nordosten vom Wyrmruhtempel, oder nordwestlich von einem Ort, den die Trockenhäute Feste Wintergarde nennen. Wir gehen?", sourceObjective = "Besucht mit Eurem Waisenkind Roo den Bronzedrachenschrein. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Wir sind sehr glücklich, dass du uns hierhergebracht hast, {name}. Wir haben uns immer Sorgen gemacht, was mit uns passieren würde, als Waisenmatrone uns in Sholazar gefunden hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13934] = { id = 13934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bronzedrachenschrein", description = "Als Kekek noch ein Welpe war, er hat die Ältesten oft von einem Schrein reden hören, weit weg. Manchmal sie sagen, dass die Bronzedrachendinger dort alles über die Zukunft wissen.\n\nKekek dir sagt, er wird großer Krieger sein, wir jetzt gehen nachsehen. Bronzedrachendingschrein ist irgendwo in Drachenöde, nordöstlich von Drachendingtempel, was Wyrmruh genannt wird und nordwestlich von Menschenstadt, was Wintergarde heißt.\n\nWir dort hingehen und Zukunft anschauen. Beweisen, dass Waisendame unrecht hat. Kekek sein Krieger, kein Lümmel.", sourceObjective = "Besucht mit Eurem Waisenkind Kekek den Bronzedrachenschrein. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Du siehst? Kekek nie genug davon bekommt zu sagen, \"Kekek dir das gesagt.\"\n\nVielleicht du jetzt auch andere Sachen glauben, die Kekek sagt, wie, dass Himmel grün ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13935] = { id = 13935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt den Baum!", description = "Wir haben die Kraft des Herzens des Waldes dazu verwendet, um den Baum gegen die Horde zu verteidigen, aber seine Kraft ist nicht grenzenlos. Wir müssen sie dazu einsetzen, die Schlacht zu ihnen zu tragen!\n\nSchattumbra, die große Katze des Waldes, streift in der Nähe umher. Von ihr sollen wir unsere Hilfe beziehen. Ihr werdet eins mit dem Schatten von Schattumbra. Ihr werdet die Essenz des Panthers in Euch aufnehmen und diejenigen vernichten, die es wagen, die Macht des Eschentals herauszufordern.", sourceObjective = "Sprecht mit Halannia, um den Schatten von Schattumbra zu beschwören und verwendet dessen Kraft, um 50 Feinde des Kriegshymnenklans am Rajenbaum zu vernichten.", completion = "Eine grausamer Anblick, aber die Feinde des Eschentals haben es verdient. Die Horde maßt es sich an, zu glauben, dass sie uns unseren geliebten Wald nehmen kann.\n\nSie begehen einen tödlichen Fehler!\n\nIhr habt den Rajenbaum vor der Zerstörung bewahrt, {name}. Sicherlich finden wir eine Belohnung, die unseres Champions würdig ist?", sourceObjectiveStatus = "unverified-source-field" }
quests[13936] = { id = 13936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twidels Narretei", description = "Verspätungen, Verspätungen, Verspätungen! Ich bin mit meiner Weisheit am Ende!\n\nMir wurde gesagt, dieser Goblin sei brillant... dass er ein Gerät entwickeln würde, das die Feinde zur Unterwerfung zwingt. Bisher hat er nichts als leere Versprechen gemacht. Wenn er noch einmal mit leeren Händen zu mir kommt, werfe ich ihn persönlich von dieser Klippe!\n\nGeht zu ihm und sprecht mit ihm, {class}. Lasst ihn wissen, dass mein Geduldsfaden bald reißt!", sourceObjective = "Hauptmann Goggath will, dass Ihr mit Twidel in Höllschreis Wacht sprecht.", completion = "Hör mir mal zu, {class}!\n\nDer Boss weiß die Kunst und das Handwerk, die zur Herstellung besten Sprengstoffs gehört einfach nicht zu würdigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13937] = { id = 13937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei den Wunderwerken", description = "Haben wir Zeit für noch einen Halt? Wir haben gehört, dass Dalaran hat einen Spielzeugladen, aber wir dürfen nie hingehen. Waisendame sagt, zu viele Waisen würden sich in Laden drängen. Vielleicht können wir gehen, nur wir?\n\nKönnen wir ein kleines Papierzeppelin haben? Wir denken, sie haben so was bei Wunderwerke in Dalaran. Wir wollten schon immer mit so was spielen. Vielleicht du uns eins zuwerfen?", sourceObjective = "Kauft einen kleinen Papierzeppelin bei den Wunderwerken und werft ihn Eurem Waisenkind, Roo, zu.", completion = "Das hat Spaß gemacht! Wir mögen Spielzeugladen. Vielleicht Waisenmatrone uns irgendwann mitnehmen. Wir fragen. Vielleicht fragst du sie auch?", sourceObjectiveStatus = "unverified-source-field" }
quests[13938] = { id = 13938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei den Wunderwerken", description = "Du bringen Kekek zu noch einen Ort? Waisenfrau sagt, dass Dalaran Spielzeugladen hat, der Wunderwerke heißt, aber Kekek den noch nie gesehen. Sie sagt, dass, wenn ein Waisenkind hingeht, sie jeden hinbringen muss. Vielleicht du bringen Kekek dorthin?\n\nKekek hat andere Kinder gesehen, die mit kleinen Papierzeppelin spielen? Kekek gehört, dass die von Wunderwerken kommen. Vielleicht du einen besorgen und ihn gemeinsam mit Kekek herumwerfen?", sourceObjective = "Kauft einen kleinen Papierzeppelin bei den Wunderwerken und werft ihn Eurem Waisenkind, Kekek, zu.", completion = "Kekek mag mit Papierzeppelin spielen. Nicht so gut wie jagen, aber damit gibt's was zu tun, wenn es langweilig sein im Waisenhaus.", sourceObjectiveStatus = "unverified-source-field" }
quests[13940] = { id = 13940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Traum verlassen", description = "Gut festhalten, {name}. Die Reise zurück in die wirkliche Welt kann Geist und Körper von Unvorbereiteten etwas mitnehmen.", sourceObjective = "Sprecht mit Malfurion beim Auge des Vortex in Dunkelküste.", completion = "Ihr kommt gerade rechtzeitig zurück, {name}. Ich weiß nicht, wie viel länger wir noch aushalten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13942] = { id = 13942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombenbasteln", description = "Ich bin hier zweifellos einer Sache auf der Spur!\n\nIch habe genug flüchtige Stoffe aus unserem Arsenal, um den Sprengstoff herzustellen, den Goggath haben will, aber ich muss ihn stabilisieren und in die Bomben füllen.\n\nIch brauche Ton – und nicht einfach irgendeinen Ton... mondberührten Ton.\n\nIhn findet man nur an den nördlichen Ufern von Astranaars Seen, und er besitzt die Eigenschaften, die ich brauche um meiner Entdeckung zur größtmöglichen Wirkung zu verhelfen!", sourceObjective = "Twidel in Höllschreis Wacht will, dass Ihr ihm 10 Proben mondberührten Ton bringt.", progress = "Zeigt her, was Ihr mir gebracht habt, {race}.", completion = "Das ist PERFEKT!\n\nOh, wartet, bis Ihr seht, was ich damit anstellen kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[13943] = { id = 13943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Deckel für die Scharmützler", description = "Unsere Kräfte sind noch nicht bereit, Astranaar anzugreifen, {class}. Sie wissen trotzdem, dass wir kommen und sie werden sich nicht damit zufrieden geben, stillzusitzen und auf uns zu warten. Am Fuße dieser Klippen haben sie ein Lager aufgeschlagen, von wo aus sie nachts ihre lästigen Angriffe starten.\n\nBevor diese Geplänkel ihre Kühnheit weiter steigern, will ich, dass Ihr ihnen einen Besuch mit dem Zorn der Horde abstattet! Kehrt zu mir zurück, wenn Ihr den Elfen ihr Mütchen ein wenig gekühlt habt.", sourceObjective = "Hauptmann Goggath will, dass Ihr 10 Scharmützler von Astranaar und 3 Offiziere von Astranaar tötet.", completion = "Gut gemacht, {race}. Aber es gibt hier noch reichlich zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13944] = { id = 13944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Gestalt, kurze Lunte", description = "<Twidel gestikuliert wild.>\n\nIch habs geschafft! Das sollte selbst Goggath zufriedenstellen!\n\nWir brauchen nur einen Test, der unsere Mühen eindrucksvoll beweist... ah, der Wagen!\n\nCheffe mäkelt doch schon seit Tagen, dass wir den verrotteten Schrotthaufen endlich wegschaffen sollen. Nutzt meinen Sprengstoff, um ihn in die Luft zu jagen. Wollen wir doch mal sehen, was der Hauptmann dann zu sagen hat!", sourceObjective = "Probiert die improvisierte Sprengstoffstange an dem liegengebliebenen Wagen in Höllschreis Wacht aus.", completion = "Twidel hat also eine Möglichkeit gefunden, diesen Sprengstoff zum Funktionieren zu bringen, wie?\n\nDas war aber auch Zeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[13945] = { id = 13945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr vor Ort", description = "Die Aggression der Knarzklauen begrenzt unsere Möglichkeiten. Niemand von uns ist davon begeistert, mit Klingen und Pfeilen gegen Kreaturen vorzugehen, mit denen wir einst befreundet waren, aber ich befürchte, dass sie sich bald gegen Dolanaar wenden werden.\n\nDie größere Sorge sind für mich die Furbolgs auf der Lichtung von Ban'ethil und im Grabhügel von Ban'ethil. Ihr müsst nach Westen reisen, in den Grabhügel vordringen und soviele der Knarzklauen töten, wie Ihr nur könnt. Wir bekommen wahrscheinlich nicht mehr viele Gelegenheiten, ihrer Stärke Einhalt zu bieten - beeilt Euch.", sourceObjective = "Tötet 20 Knarzklauenfurbolgs auf dem Grabhügel von Ban'ethil und in der Umgebung.", completion = "Beeindruckend. Ich hoffe, meine Jägerin hat ihren Teil getan.\n\nWenn wir mit diesem Eifer weitermachen, können wir Teldrassil vielleicht doch noch von der Korruption befreien, die Alexstrasza selbst nicht ausbrennen konnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[13946] = { id = 13946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergeltung der Natur", description = "Ich bin froh, dass Ihr bereit wart, Eure Fehler wieder gutzumachen - das sagt viel über Euren Charakter aus.\n\nIch habe noch eine Aufgabe für Euch. Ich habe einige Zornwurzelsamen gesammelt. Sie sind Teufelszapfen ähnlich, aber viel stärker. Die Natur reagiert oft sehr negativ auf Dämonen und diese Zornwurzelsamen beinhalten hochkonzentrierte Abwehrstoffe.\n\nNördlich von hier, am Teufelsfels, sind Grellkin, die nicht mehr zu läutern sind. Benutzt die Zornwurzelsamen, um sie auszulöschen, bevor sie zu einer größeren Bedrohung werden.", sourceObjective = "Verwendet Zornwurzelsamen, um 12 Teufelsfelsgrellkin zu töten.", completion = "Gut. Ich weiß, dass das wahrscheinlich nicht gerade angenehme Arbeit war, aber wir sind Euch sehr dankbar.\n\nIch fürchte um unseren geliebten Teldrassil... es sieht aus, als werde er von Tag zu Tag verderbter, und unsere Unkenntnis der Ursache quält mich sehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[13947] = { id = 13947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombenstimmung in Astranaar!", description = "Twidel hat also endlich einen geeigneten Sprengstoff erfunden, wie?\n\nEr hätte keinen besseren Augenblick wählen können. Während wir sprechen, bereiten die Elfen von Astranaar einen vernichtenden Angriff auf unserer Lager vor.\n\nLasst unsere neue Waffe aus dem Himmel auf sie niederregnen! Die Zerstörung von Astranaar wird ein Stich ins Herz aller Nachtelfen sein!\n\nSprecht mit Thraka, wenn Ihr bereit seid, mit dem Angriff zu beginnen.\n\nZielt gut, {class}.", sourceObjective = "Hauptmann Goggath will, dass Ihr Twidels improvisierten Sprengstoff verwendet, um 20 Schildwachen von Astranaar zu töten und 10 Schleudern von Astranaar zu zerstören.", progress = "Astranaar brennt!\n\nFür die Horde!", completion = "Die glorreichen Geschichten der Horde sollen noch lange von Euren Taten berichten.\n\nEure Bemühungen haben dem Feind einen vernichtenden Schlag zugefügt!", sourceObjectiveStatus = "unverified-source-field" }
quests[13948] = { id = 13948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbesserte Beobachtungen", description = "Die Kultisten sind anscheinend dabei, die Überreste eines Wesens auszugraben, das als Soggoth der Glitschige bekannt ist.\n\nVielleicht haben die höherrangigen Kultisten mehr Informationen für uns.", sourceObjective = "Schleicht mit Hilfe der Pantherfigur in die Meistergleve und beobachtet die Anführer der Schattenhammerkultisten auf der höheren Ebene.", completion = "Das sind schreckliche Neuigkeiten, {name}. Wenn Ihr recht habt, so müssen wir schnell und entschieden handeln.\n\nWir können nicht zulassen, dass \"Soggoth\" wieder zum Leben erweckt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13949] = { id = 13949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karawane am Wegekreuz", description = "<Halga grinst entwaffnend und hält eine enorme Feuerwaffe in die Höhe.>\n\nHabt Ihr jemals eine von diesen verwendet, {name}? Es ist ein Monster! Höllenfeuer mit Fadenkreuz. Zu schwer, um sie zu Fuß zu verwenden, aber perfekt, wenn man einer Karawane vorausreitet. Ich nenne sie den 'Straßenfeger'.\n\nWir müssen den Nachschub, den Ihr gesammelt habt, zum Wegekreuz bringen. Und ich rechne mit Schwierigkeiten. Ich hätte Euch gerne als Begleiter. Und als Feuerschutz. Sagt einfach, wenn Ihr bereit seid und ich setze Euch an die Spitze der nächsten Karawane.", sourceObjective = "Sprecht mit Halga Blutauge in der Fernwacht, um die nächste Wegekreuz-Karawane zu Grol'doms Hof zu begleiten.", progress = "Mok'ra, Fremdling. Seid Ihr hier aus der Fernwacht?", completion = "Ihr seid ein unverhoffter Anblick, {race}. Das ist die erste Karawane, die es in dieser Woche geschafft hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[13950] = { id = 13950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spielgefährten!", description = "Im Waisenhaus kann es schon sehr einsam werden, weißt du? Manchmal wollen wir mal rauskommen, neue Freunde finden.\n\nVielleicht kannst du uns irgendwohin mitnehmen, wo andere Junge sind? Wir haben von einem Ort gehört, der Zuflucht der Winterflossen genannt wird, in der großen Boreanischen Tundra. Wir glauben, dass es ganz weit drüben sein, im Nordwesten, in der Nähe der Kante der Kaltarrainsel.\n\nDie Waisendame sagen, dass jemand Tapferes dort ein paar Junge gerettet hat. Wir glauben, sie sind auch einsam. Wir glauben, sie brauchen Freunde. Bringst du uns hin?", sourceObjective = "Nehmt Euer Waisenkind, Roo, und besucht die Zuflucht der Winterflossen. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Das hat Spaß gemacht! Können wir irgendwann noch mal hingehen? Wir können es gar nicht abwarten, unseren neuen Freund wiederzusehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13951] = { id = 13951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spielgefährten!", description = "Kekek ist der Meinung, es gibt nicht genügend andere Welpen, die auch bei der Waisendame leben. Vielleicht gehen wir und besuchen ein paar?\n\nKekek kennt einen Stamm, der in der Drachenöde lebt, an einem Ort, der Schneewehenlichtung heißt. Du kennst? Schneewehenlichtung ist im Norden von einer Walrossstadt, die heißt Hafen Mo'aki, und im Süden von Rubindrachenschrein.\n\n<Kekek knurrt bei der Erwähnung der Tuskarr.>\n\nDu bringst Kekek da hin, zu ein paar von den Dörfern dort. Vielleicht treffen wir neue Wolvar und zeigen ihnen, wie stark die Wildherzen sind!", sourceObjective = "Nehmt Euer Waisenkind, Kekek, und besucht die Schneewehenlichtung. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Kekek mag neue Schneewehenfreunde, vielleicht kann irgendwann zurückkommen und zusammen jagen gehen. Vielleicht können wir Walrus-Leute umwerfen, wenn sie schlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13952] = { id = 13952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Menschengeist auf dem Friedhof von Sturmwind.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13953] = { id = 13953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga unter uns", description = "Der Schädel dieser Kreatur wurde wohl im Kampf mit Aros gebrochen. Es handelt sich anscheinend um eine Kreatur, die Euch bislang als Naga ein Begriff war.\n\nTrotz ihrer monströsen Gestalt sind die Naga Nachtelfen, die von der arkanen Magie von Königin Azshara verformt wurden.\n\nSie haben sich wohl dazu entschlossen zu verhindern, dass Ihr das Horn der Urtume erhaltet.", sourceObjective = "Kehrt zu Balren von der Klaue beim Hain der Uralten in Dunkelküste zurück.", completion = "Die Naga haben sich mit den Schattenhammerkultisten verbündet? Das hat uns gerade noch gefehlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13954] = { id = 13954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Drachenkönigin", description = "In einer von Hochorakels Soo-says Geschichten es heißt, die Großen haben die Drachen gemacht und auch die Königin für die Drachen. Wir wollen sie sehen! Würdest du uns mitnehmen zur Spitze des Wyrmruhtempels? Wir erinnern uns, dass Soo-say uns erzählt hat, dass das Tempeldings in der Mitte der Drachenöde war.\n\nWir wollen wirklich so gerne die Drachenkönigin treffen. Sie muss so groß und schön sein. Vielleicht hilft sie uns, neue Eltern zu finden.\n\nDu uns nehmen mit?", sourceObjective = "Nehmt Euer Waisenkind, Roo, und besucht Alexstrasza die Lebensbinderin auf der Spitze des Wyrmruhtempels. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Glaubst du, sie hat schon mal ein Orakel gesehen? Wir vielleicht das erste, das sie jemals getroffen hat! Wir glauben, sie hat uns gemocht, aber wir nicht sicher. Sie nicht redet viel. Nee. Aber hat Spaß gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[13955] = { id = 13955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Drachenkönigin", description = "Kekek hat Drachen immer gemocht. Wollte immer einer sein, aber Waisendame hat nein gesagt. Aber sie hat gesagt, dass vielleicht du Kekek zur Drachenkönigin bringen kannst.\n\nKekek glaubt, Waisendame hat einmal eine gute Idee. Du bringst Kekek zum Wyrmruhtempel in der Drachenöde? Fliegen ganz hoch bis zur Spitze, um Drachenkönigin zu sehen. Sie muss riesig groß sein, damit sie Königin von allen Drachen ist. Kekek kann es gar nicht erwarten, sie zu sehen!", sourceObjective = "Nehmt Euer Waisenkind, Kekek, und besucht Alexstrasza die Lebensbinderin auf der Spitze des Wyrmruhtempels. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Die Königin war nicht, was Kekek erwartet hat, aber Kekek versteht warum. Die Besucher von Königin werden zerquetscht, wenn sie immer großer Drache ist! Trotzdem, will das irgendwann mal sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13956] = { id = 13956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Großen treffen", description = "Hochorakel Soo-say erzählt uns immer, wie die Großen Schreine gebaut haben und wir ihnen Glitzer-Glitzer geben, aber er hat Große nie gesehen. Niemand hat Große gesehen, vielleicht weißt du, wo wir einen finden?\n\nSoo-say erzählt uns, die Großen haben ein Tor gebaut und es in die Mitte vom Süden von Sholazar gestellt. Soo-say sagt nicht, wo es hinführt, aber vielleicht er führt zu einem Großen! Bringt uns durch das Tor, damit wir es rausfinden können, {name}.", sourceObjective = "Nehmt Euer Waisenkind, Roo, und besucht den Etymidian auf der Terrasse des Formers. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Wir haben einen Großen getroffen! Nur schade, dass er geschlafen hat, aber wir verstehen. Wir schlafen auch gerne! Vielleicht haben wir von Großen das Schlafen gelernt, so wie wir auch von ihnen von Schreinen und Glitzer-Glitzer erfahren haben!\n\nKönnen wir zurückkommen und den Großen noch mal besuchen, wenn er nicht schläft?", sourceObjectiveStatus = "unverified-source-field" }
quests[13957] = { id = 13957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der mächtige Hemet Nesingwary", description = "Weißt du, wen Kekek immer schon mal treffen wollte? Hemet Nesingwary.\n\nVielleicht kannst du Kekek mitnehmen, um ihn zu sehen? Der Älteste Harkek hat uns alles von ihm erzählt. Er kommt nach Sholazar, um die größten Tiere weit und breit zu jagen! Sogar Älteste der Wildherzen respektieren Hemet Nesingwary als großen Jäger.\n\nDer Älteste Harkek hat Kekek erzählt, dass Nesingwarys Basislager in der Mitte der Westseite von Sholazar, beim Fluss, der Meeresklammstrom genannt wird. Können wir ihn besuchen und lernen, wie man wie Hemet jagt?", sourceObjective = "Nehmt Euer Waisenkind, Kekek, und besucht Hemet Nesingwary in Nesingwarys Basislager. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Hilfst du Kekek, ein Buch zu lernen? Dann kann Kekek jagen mit Hemet Nesingwary!", sourceObjectiveStatus = "unverified-source-field" }
quests[13958] = { id = 13958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kritischer Zustand!", description = "Wir halten den Feind gut auf Trab. Der Sieg rückt immer näher!\n\nAber es ist noch nicht Zeit zum Feiern, {class}. Es bleibt noch viel zu tun, bevor die Horde das Eschental für sich beanspruchen kann.\n\nBeim Rajenbaum im Osten hat eine Schlacht begonnen. Berichten zufolge sind viele Mitglieder der Horde verwundet.\n\nBringt diese Heilvorräte dorthin und übergebt sie an Thagg. Erzählt ihm von unserem Angriff auf Astranaar. Vielleicht fördert es den dortigen Kampfgeist.", sourceObjective = "Goggath will, dass Ihr das Schlachttriagenverbandsset zu Thagg beim Rajenbaum bringt.\n\nBereitgestellter Gegenstand:", completion = "<Thagg hört aufmerksam zu, während Ihr ihm von Eurem Angriff auf Astranaar berichtet.>\n\nDas sind in der Tat gute Nachrichten, {race}. Aber im Moment brauchen wir hier etwas mehr als nur gute Nachrichten.\n\nDieses Schlachttriagenverbandsset können wir hier gut gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13959] = { id = 13959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Waisenhaus", description = "Wir viel Spaß mit dir hatten, {name}. Wir uns wünschen so sehr, du könntest <unser Papa/unsere Mama> sein, aber du uns jetzt zur Waisenmatrone Aria in Dalaran zurückbringen musst.\n\nDu uns vielleicht irgendwann wieder besuchen kommen? Es toll war, Winterflossenjungen zu treffen und Drachenkönigin zu sehen. Es uns wird keiner glauben, dass wir einen Großen getroffen haben!\n\nWir dich werden vermissen, {name}. Wir versprechen, dir mal einen Brief zu schreiben, oki?", sourceObjective = "Bringt Euren Schutzbefohlenen zurück zum Waisenhaus in Dalaran, indem Ihr der Waisenmatrone Aria in Dalaran die Pfeife des Orakelwaisenkindes überreicht.", completion = "Hört sich an, als hätte der kleine Roo diese Woche viel Spaß gehabt. Ich weiß, dass er sehr einsam war im Waisenhaus und unbedingt ein paar neue Freunde finden wollte. Vielen, vielen Dank, dass Ihr Euch um ihn gekümmert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13960] = { id = 13960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Waisenhaus", description = "Weißt du was? So schlecht bist du gar nicht, {name}. Du nimmst Kekek mit zu Orten, an denen was los ist. Kekek trifft viele neue Freunde und macht Dinge, die kein anderer Welpe macht.\n\nDu und Hemet Nesingwary und Schneewehenwelpen alle neue beste Freunde. Vielleicht du irgendwann das Grünehügelbuch bringen? Kekek verspricht, dir auch ab und zu zu schreiben, um zu sagen, wie die Dinge stehen. Vielleicht sogar nett sein zu Großzungenkindern.\n\nKekek muss jetzt zur Waisenmatrone Aria zurückkehren, zurück in Lilaleutestadt.", sourceObjective = "Bringt Euren Schutzbefohlenen zurück zum Waisenhaus in Dalaran, indem Ihr der Waisenmatrone Aria in Dalaran die Pfeife des Wolvarwaisenkindes überreicht.", completion = "Habt Dank dafür, dass Ihr Euch bereit erklärt habt, diese Woche auf Kekek achtzugeben. Ich weiß, er kann etwas anstrengend sein, aber ich glaube, dass er durch etwas mehr individuelle Zuwendung und einen etwas größeren Freundeskreis große Fortschritte machen könnte. Ohne Zweifel wird er noch wochenlang von seinen Abenteuern mit Euch erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13961] = { id = 13961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quetscht sie aus", description = "Es entspricht unserem Instinkt, einfach auf unsere Angreifer wie wild einzudreschen, aber die Weisheit gebietet einen anderen Weg. Wir sollten einen dieser Eindringlinge der Stacheleber befragen und so viel wie möglich herausfinden. Nehmt dieses Netz, {name}, und fesselt einen Plünderer der Stacheleber, der unseren Hof westlich von hier angreift. Schlagt die Bestie bewusstlos und bringt sie zu mir.", sourceObjective = "Verwendet Grol'doms Netz, um einen Plünderer der Klingenmähnen zu fesseln und schleppt ihn zurück zu Togrik auf Grol'doms Hof.", progress = "Springt mit unserem Gefangenen nicht all zu wild um. Um die Fragen beantworten zu können, muss er seinen Kopf auf dem Rumpf behalten.", completion = "Ohje. Dieser Stacheleber sollte verhört werden, nicht weichgeklopft!", sourceObjectiveStatus = "unverified-source-field" }
quests[13962] = { id = 13962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pattsituation", description = "Die Triagenverbandssets werden uns helfen, den Kampf weiterzuführen, aber wir befinden uns in einer Pattsituation.\n\nDie Dryaden sterben relativ schnell, aber ihr Anführer lässt sie kurz nach ihrem Fall immer wieder auferstehen. Wir stehen einem endlosen Strom dieses Ungeziefers gegenüber!\n\nBewahrer Ordanus versteckt sich in diesem mutierten Baum. Unsere Bemühungen, uns bis zu ihm durchzukämpfen, waren bisher vergeblich. Vielleicht könntet Ihr zu ihm gelangen, während wir mit seinen Dryaden kämpfen...\n\nDas ist sicherlich ein Kinderspiel für jemanden, der Astranaar erobert hat. Nein?", sourceObjective = "Thagg im Rajenbaum will, dass Ihr Bewahrer Ordanus tötet.", completion = "Sehr gut, {name}.\n\nIhr habt vollbracht, was mir nicht gelungen ist. Ihr habt meine Achtung.", sourceObjectiveStatus = "unverified-source-field" }
quests[13963] = { id = 13963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jedes Mittel ist recht", description = "Ich schätze, ein Schwung kaltes Wasser wird ihn wieder zu Bewusstsein kommen lassen. Was glaubt Ihr, wird er uns mitzuteilen haben?\n\nIch nehme ihn in dem Viehstall hinter mir in Gewahrsam. Ich glaube nicht, dass er lange bewusstlos bleiben wird. Findet so viel heraus, wie Ihr könnt bezüglich der Frage, warum die Stacheleber unsere Höfe angreifen! Die Befragungsmethoden überlasse ich Euch.", sourceObjective = "Verhört den Gefangenen der Klingenmähnen. Falls er nicht dort oder bewusstlos ist, kann Togrik ihn für Euch wiederbeleben.", completion = "Sehr interessant – diese Biester scheinen jemanden zu kennen, der 'Tortusk' heißt und der sie bezaubert und verängstigt. Er ist ein mächtiger Anführer, der sein Volk sowohl zu Heldentaten als auch zu Gräueltaten zu bewegen vermag... Aber wir Orcs können das besser nachvollziehen als alle anderen.\n\nWir sollten unsere Aufmerksamkeit auf diesen Tortusk richten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13964] = { id = 13964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Turm", description = "Wir haben die Silberwindzuflucht verloren! Alles, was ich weiß, ist, dass es einen Überraschungsangriff der Horde gab und dass sie irgendwie die Elementarwächter des Mystralsees gegen uns aufgebracht haben.\n\nDie Überlebenden sind bis zur Sternenstaubspitze zurückgefallen. {name}, sie benötigen Eure Hilfe.\n\nBegebt Euch nach Südsüdost. Dort findet ihr den Turm am Eingang des Steinkrallenpasses, der Euch in das Steinkrallengebirge führt. Ich bin mir sicher, dass Ihr dort Schildwache Velene Sternenschlag findet, die dort den Gegenschlag unterstützt.", sourceObjective = "Sprecht mit Schildwache Velene Sternenschlag auf der Sternenstaubspitze.", completion = "Freut mich, Euch endlich kennenzulernen, {name}. Ich kenne alle Eure Heldentaten und lasst mich Euch sagen, dass ich beeindruckt bin!\n\nGlaubt Ihr, dass Ihr uns Eure Kundigkeit zur Verfügung stellen könntet?", sourceObjectiveStatus = "unverified-source-field" }
quests[13965] = { id = 13965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaut nach den Edunes", description = "{name}, falls Ihr einen Augenblick erübrigen könnt, würde ich gerne Eure Hilfe in einer kleinen Angelegenheit in Anspruch nehmen.\n\nIch habe schon längere Zeit nichts mehr von meinen Freunden den Edunes gehört. Ich frage mich, ob Ihr auf einen Sprung nach Westen bei ihnen vorbeischauen könnt?\n\nIch danke Euch. Ihr Landhaus liegt auf einem kleinen Grundstück westlich des Schreins von Aessina.", sourceObjective = "Sprecht mit Benjari Edune im Haus von Edune im Eschental.", completion = "Ihr sagt, Faldreas schickt Euch? Guter Mann.\n\nWie es der Zufall will, könnten wir Eure Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13966] = { id = 13966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk", sourceObjective = "Auf dem Schildchen des Geschenks steht:\n\nFrohe Feiertage, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13967] = { id = 13967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beim Ausdünnen der... Rotte?", description = "Die Furbolgs sind zahlreicher als wir es in diesen südlichen Gefilden erwartet hatten. Sie sind hier auch viel aggressiver als wir es gerne hätten.\n\nWir müssen unsere Kräfte aufteilen, denn wir müssen Elfen jagen und gleichzeitig das dringend benötigte Holz schlagen. Das bedeutet, dass Ihr mir helfen müsst, die Belästigung durch die Furbolgs zu beenden.\n\nIch muss hier Forschungen durchführen. In der Zwischenzeit brauche ich Euch für eine etwas tatkräftigere Aufgabe. Bringt mir die Ohren der Furbolgs in der Nähe. Sie sollen Tarkan beweisen, dass wir das Problem in Angriff nehmen.", sourceObjective = "Senani Donnerherz in der Silberwindzuflucht will, dass Ihr Euch 15 Furbolgohren von Totemikern der Fäulnisklauen und Ursa der Fäulnisklauen holt.", progress = "Und, {name}.\n\nIst es vollbracht?", completion = "Gute Arbeit, {race}!\n\nJetzt sollten sie eine Zeitlang ihre Wunden lecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13968] = { id = 13968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortusks Untergang", description = "Im Windschatten des Chaos' im Süden scheint dieser Schläger 'Tortusk' alle Flüchtlinge der Klingenmähnen unter seinem Banner versammelt zu haben. Unter seiner Führung verwandeln sie sich in dreckige, kleine Briganten. Mit dieser Sorte lässt sich nicht verhandeln. Tortusk muss vernichtet werden.\n\nWenn man unserem Gefangenen Glauben schenken kann, findet Ihr Tortusk südöstlich von hier an einem Ort namens Dornenhügel. Durchsucht die Felsen nach einer Stelle, von wo aus er einen guten Überblick über die Straße hat. Tötet ihn, {name}, und die unmittelbare Gefahr wird weichen.", sourceObjective = "Tötet den Anführer der Klingenmähnen Tortusk.", completion = "Ah, Tortusk hat sich also genauso verhalten, wie ich es vorhergesagt habe? Er sprang Euch direkt an die Gurgel? Es ist gut, dass er tot ist.\n\nDie Stacheleber der Klingenmähnen wurden von ihrer Führung im Südlichen Brachland getrennt. So ein Tier wie er sollte solche Macht zweifellos nicht besitzen. Vielleicht können wir ohne seinen Einfluss in einen Dialog mit den Überlebenden treten... Obwohl dort vielleicht auch hitzige Gemüter vorherrschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13969] = { id = 13969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind Grol'dom Kodos?", description = "Wenn Ihr nach Süden zum Dornenhügel reist, frage ich mich, ob Ihr unsere fehlenden Kodos ausfindig machen könntet? Nicht jede Karawane hat es über den Pass der Fernwacht geschafft. Diese Schläger der Klingenmähnen haben gestern Morgen ein Packtier entführt. Vielleicht ist es nicht mehr am Leben, aber falls es noch nicht tot ist, können wir es uns nicht leisten noch mehr Vieh zu verlieren.", sourceObjective = "Findet den vermissten Kodo von Grol'dom irgendwo auf dem Dornenhügel im Nördlichen Brachland.", completion = "Dieser mitgenommene Kodo steht mit drei Beinen im Grab, aber er atmet noch. Die Klingenmähnen haben seine Fracht noch nicht ausgeplündert. Falls er wiederbelebt werden kann, könntet Ihr vielleicht die gesamte Ladung retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13970] = { id = 13970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tierpflege", description = "Kodos sind zähe Kreaturen. Mit ein wenig Nahrung bekommen wir den Dicken vielleicht wieder auf die Beine.\n\nDie Klingenmähnen haben reichlich Getreide von früheren Karawanen geraubt. Ihr könnt das gestohlene Getreide in den nahegelegenen Lagern einsammeln.", sourceObjective = "Sammelt 5 Säcke gestohlenes Getreide aus den Lagern der Klingenmähnen auf dem Dornenhügel.", progress = "Die Kreatur hebt ihren Kopf nicht, aber sie sieht Euch mit großen und flehenden Augen an, in denen sich das Wasser sammelt.", completion = "Der Kodo ist unersättlich! Ihr hättet die Säcke genauso gut in ein großes Loch schütten können!\n\nDas Tier wird bereits wieder munter.", sourceObjectiveStatus = "unverified-source-field" }
quests[13971] = { id = 13971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Kodos", description = "Das riesenhafte Reptil erhebt sich langsam, stellt sich auf die Beine, die lose Erde des Brachlandes rieselt von seinen Gliedmaßen, in die das Leben zurückgekehrt ist. Instinktiv stapft das Tier zurück zu seinem Zuhause auf Grol'doms Hof.\n\nIhr wollt sicher mit Kranal Fiss sprechen, um sicherzugehen, dass es der Kodo geschafft hat.", sourceObjective = "Sprecht mit Kranal Fiss auf Grol'doms Hof, um Euch zu versichern, dass sein vermisster Kodo heil angekommen ist.", completion = "Das war Euer Werk, {race}? Ja, der vermisste Kodo ist vor ein paar Minuten eingetroffen. Es wird vieler Nächte bedürfen, die Wunden der bemitleidenswerten Bestie zu versorgen, aber dank Euch ist sie noch am Leben. Und Ihr habt die gesamte Fracht gerettet!\n\nBitte sucht Euch etwas von der Ausrüstung aus, die der Kodo transportiert hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13973] = { id = 13973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grol'doms Miliz", description = "Sie sind aus dem Nichts gekommen, {class}! Stacheleber wo man auch hinsieht. Borsten, Schnauzen und Hauer. Wir haben uns auf den Hof zurückgezogen, aber es kamen immer mehr.\n\nUnsere besten Verteidiger sind auf dem Schlachtfeld gefallen und wir haben kein Lebenszeichen von Bauer Ralton. Ihr müsst sie für mich angreifen! Haltet mir diese Schweine vom Leib, während ich die Verwundeten verteidige, bis Hilfe eintrifft.", sourceObjective = "Tötet 6 Plünderer der Klingenmähnen.", progress = "Ich sehe Rauch aus dem benachbarten Gebäude aufsteigen – was geht da draußen vor sich?", completion = "Ich sehe, Ihr habt Euren Weg mit Leichen gepflastert, {race}. Ich hätte es nicht besser machen können. Das Vieh ist vielleicht verloren, aber das Land bleibt das unsrige – dank Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[13974] = { id = 13974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twidels winziges Paket", description = "Woohoo!!\n\nSchaut nur, wie das brennt! Es ist revolutionär! Ein echter Durchbruch in der Explosionstechnik! Und das ist natürlich die einzige Technik, die zählt.\n\nAlle Goblins südlich von Nordend werden mich bewundern und beneiden!\n\nUnd ob Ihr es glaubt oder nicht, ich habe noch ein wenig an der Zusammensetzung gedreht, um sogar noch mehr Leistung herauszuholen!\n\nHier. Nehmt eine Probe dieses Zeugs und bringt sie nach Südosten in die Silberwindzuflucht. Mein Vetter Flooz kann es vielleicht brauchen, um die Horde bei der Eroberung dieses Ortes zu unterstützen.", sourceObjective = "Twidel möchte, dass Ihr Twidels winziges Paket zu Flooz in der Silberwindzuflucht bringt.\n\nBereitgestellter Gegenstand:", completion = "Na sieh mal einer an! Der kleine Twidel hat es diesmal echt geschafft. Das Zeug hat Astranaar in die Luft gejagt, sagt Ihr?\n\nWie Ihr seht, brauchen wir keine Hilfe, die Silberwindzuflucht zu erobern, aber Twidel war immer ein bisschen kleingeistig.\n\nWenn das Zeug wirklich so gut ist, wie Ihr behauptet, sind die Möglichkeiten endlos...", sourceObjectiveStatus = "unverified-source-field" }
quests[13975] = { id = 13975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Karawane zum Wegekreuz", description = "<Rocco überreicht Euch eine Schrotflinte, die Euch bekannt vorkommt.>\n\nIch habe mir erlaubt, Halgas Artillerie für Euch zu reinigen. Ich bin mir sicher, dass ich Euch nicht vor dem Rückstoß zu warnen brauche. Fragt mich einfach, wenn Ihr bereit seid, zum Wegekreuz aufzubrechen! Thork wartet dort auf Euch. Achtet darauf, dass Ihr ihm nicht pampig kommt.\n\nLasst Euch von nichts aufhalten, {name}, und wenn Euch jemand zu nahe kommt, versetzt ihm einfach einen Stoß mit dem Kolbenende Eurer Schrotflinte. Macht uns stolz!", sourceObjective = "Sprecht mit Rocco Peitschschwinger in Grol'doms Hof und begleitet seine Karawane den gesamten Weg zum Wegekreuz.", progress = "Wart Ihr der Jemand, den ich mit einer Schrotflinte am Ende meiner Karawane herumfuchteln sah?", completion = "Es wurde aber auch Zeit, dass ein paar Vorräte bis hierher durchkommen. Es ist schlimm genug, von Mulgore abgeschnitten zu sein, aber diese Stadt würde in die Binsen gehen, wenn wir unseren Handel mit Orgrimmar verlören.", sourceObjectiveStatus = "unverified-source-field" }
quests[13976] = { id = 13976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drei Männlein steh'n im Walde", description = "Habt Ihr Lust auf einen kurzen Abstecher in den Süden? Ich habe drei Freunde, von denen ich schon länger nichts gehört habe. Diese seltsamen Tentakel treten im Norden aus dem Boden hervor und bei all der dämonischen Aktivität wage ich es nicht, meine Familie alleinzulassen.\n\nBolyun hat sein Lager in der südwestlichen Ecke dieses Waldes aufgeschlagen - genau im Nordwesten dieses verdammten Schreins des Sengenden Feuers. Alenndaar und Harlown haben sich ihm angeschlossen, also müsste es ihnen eigentlich gut gehen, aber man kann nie wissen.\n\nHabt Dank, {name}.", sourceObjective = "Sprecht mit Bolyun in Bolyuns Lager im Eschental.", completion = "{class}, Ihr müsst achtsam sein! Kaliva die üble Dämonin, die uns angekettet hat, ist in der Nähe!", sourceObjectiveStatus = "unverified-source-field" }
quests[13977] = { id = 13977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massenproduktion", description = "Woohoo!! Habt Ihr das GESEHEN?!\n\nDamit müssen wir sofort in Produktion gehen.\n\nHier, bringt den Rest von diesem Zeug zu Jinx. Er richtet gerade unseren neuen Standort westlich von hier ein.", sourceObjective = "Flooz möchte, dass Ihr Twidels Bumm-Bumm-Pulver zu Jinx in den Stinkwerken bringt.", progress = "Was habt Ihr da, Boss?", completion = "<Jinx untersucht das Pulver einen Augenblick lang sorgfältig.>\n\nHmmm.\n\nIch brauche ein wenig Zeit. Aber ja, wir können das in eine Bombe packen…", sourceObjectiveStatus = "unverified-source-field" }
quests[13979] = { id = 13979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Expertengremium der Goblins", description = "Wenn wir die verdammten Bombenangriffe durch diese Goblinmachwerke stoppen könnten, wären wir in der Lage, einen Gegenangriff zu starten und die Silberwindzuflucht zurückzuerobern!\n\nMeiner Erfahrung nach sind Goblins entweder faul oder unproduktiv, oder so eifrig, dass sie sich mit ihrem Sprengstoff schließlich selbst in die Luft jagen. Zu unserem Unglück werden sie von dem genialen, leitenden Bombentechniker Splodier angeführt.\n\nBegebt Euch in die Stinkwerke an der Westseite der Zuflucht und kehrt nicht zurück, bis Ihr den Kopf des leitenden Bombentechnikers in Händen haltet.", sourceObjective = "Holt Euch Splodiers Kopf.", progress = "Habt Ihr den widerwärtigen, verwarzten Goblin zum Schweigen gebracht?", completion = "Das ist gut. Ohne ihn fallen ihre Techniker sicher wieder zurück in ihre alten Gewohnheiten, was zu weniger Bomben und mehr Unfällen führen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13980] = { id = 13980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie sind da draußen!", description = "Sie sind da draußen, {class}. Und sie sind uns auf den Fersen.\n\nEinige meiner Männer wurden tot aufgefunden. Elfenangriffe, ohne Zweifel.\n\nIch glaube, dass sie wegen Eurer Arbeit in Astranaar versessen darauf sind, unserem Fortschritt hier Einhalt zu gebieten. Ein letztes Aufbäumen vor der Niederlage!\n\nNehmt diese Brille. Sie hilft Euch dabei, auch den am besten getarnten Elf zu erkennen. Haltet sie mir vom Leib, während wir unsere Waffe für Euch vorbereiten.", sourceObjective = "Jinx in den Stinkwerken möchte, dass Ihr 12 Assassinen des Eschentals tötet.", completion = "Gute Arbeit, Freund.\n\nEure Fähigkeiten haben uns die nötige Zeit verschafft, um die Bombe vorzubereiten. Sie ist fast fertig!", sourceObjectiveStatus = "unverified-source-field" }
quests[13981] = { id = 13981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombenlieferung gefällig?", description = "Das ist sicherlich die größte Sprengstoffladung, die Ihr je zu Gesicht bekommen habt. Was in aller Welt würden die Goblins mit so einem Monstrum bombardieren wollen?\n\nSoweit Ihr das beurteilen könnt, ist das Werk fast vollendet. Die Goblins scheinen den Sprengsatz gut konstruiert zu haben. Es sieht so aus, als ob er gut geschützt ist gegen jeden Schaden, den Ihr ihm zufügen könntet. Und die Bombe ist sicherlich zu groß, als dass Ihr sie von hier forttragen könntet.\n\nIhr solltet die Bombe besser Jägerin Jalin auf der Sternenstaubspitze im Südwesten melden!", sourceObjective = "Berichtet Jägerin Jalin auf der Sternenstaubspitze im Südwesten des Eschentals von der Existenz der Bombe.", completion = "Sie haben was? SIE IST WIE GROSS?!!!\n\nDas hört sich gar nicht gut an, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13982] = { id = 13982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Ketten gelegt", description = "{name}, Ihr müsst vorsichtig sein. Kaliva ist noch immer in der Nähe und als sie uns gefangen nahm, erwähnte sie ganz besonders Euren Namen.\n\nNur ihr Herz kann uns von diesen Ketten befreien, aber ich glaube, dies alles ist eine Falle nur für Euch!", sourceObjective = "Beschafft Kalivas Herz.", progress = "Um freizukommen, brauchen wir Kalivas Herz.", completion = "Es ist ekelerregend, ich weiß, aber wenn wir drei diese Ketten von Kaliva loswerden wollen, reicht es nicht, dass sie tot ist.\n\nWir müssen von ihrem teuflischen Herzen essen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13983] = { id = 13983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baut Euren eigenen Sarg", description = "Sobald sie fertig ist, müssen wir die Bombe zu Saurboz schaffen.\n\nUnd mit 'wir' meine ich 'Ihr'.\n\nBei all den Feinden, die sich hier herumtreiben, muss ich etwas ganz Besonderes bauen, wenn Ihr mit dieser Aufgabe Erfolg haben wollt.\n\nIch könnte einen dieser kaputten Schredder umbauen, aber dazu brauche ich ein paar Teile. In den Wäldern im Westen solltet Ihr eigentlich alles problemlos finden.\n\nBeschafft mir die Teile, während ich die Bombe fertig baue.", sourceObjective = "Vorarbeiter Jinx möchte, dass Ihr 3 Bronzeräder, 3 Stück Kupferbeschlag und 5 Klemmbolzen sammelt.", progress = "Habt Ihr die Teile, die ich brauche, Freund?", completion = "Das sieht gut aus, {class}.\n\nEuer Schredder sollte im Handumdrehen bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13985] = { id = 13985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leert den Schrein", description = "Dem Bösen dieser Brennenden Legion muss ein Ende gesetzt werden!\n\n{name}, Ihr habt einen ihrer Mächtigsten besiegt, aber es gibt noch immer zahlreiche Dämonen, die die Wälder im Osten im Schrein des Sengenden Feuers verseuchen.\n\nWerdet Ihr als ein Freund des Waldes diese Kreaturen vernichten und dann den Großen Baobob, das große Urtum des Krieges am Schrein von Aessina im Nordosten warnen?", sourceObjective = "Vernichtet 12 beliebige Dämonen am Schrein des Sengenden Feuers.", completion = "Das war gute Arbeit, {race}. Aber Ihr seht, dass ich hier ein wenig beschäftigt bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[13986] = { id = 13986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verletzter Kollege", description = "Es war ein harter Kampf hier oben, {class}, wie Ihr sicher wisst. Wir harren aus, doch ist nicht jeder unversehrt geblieben.\n\nEine der Kriegerinnen unserer Gruppe, Aponi Lichtmähne, leidet an einer infizierten Wunde an ihrem Arm. Sie wurde zur Erholung nach Donnerfels zurückgebracht. Es scheint jedoch, als hätte sie in der ganzen Aufregung ihren Schild hier an der Front vergessen - könntet Ihr es ihr bringen, zusammen mit unseren Genesungswünschen? Uns fehlt ihr Lächeln hier sehr.\n\nIhr könnt sie auf der Anhöhe der Ältesten finden.", sourceObjective = "Bringt Aponi Lichtmähne auf der Anhöhe der Ältesten in Donnerfels den ramponierten Stammesschild.", progress = "Oh! Hallo. Ich glaube nicht, dass wir uns schon kennengelernt haben. Gibt es etwas, was ich für Euch tun kann?", completion = "Oh, mein Schild! Ich werde ihn in naher Zukunft wohl nicht brauchen, aber ich danke Euch. Ich verabscheue es, hier nutzlos herumzusitzen, wenn ich an der Front helfen könnte, doch würde es niemandem helfen, wenn ich mich in den Kampf werfe, solange mein Arm in diesem Zustand ist.\n\nGebt gut auf Euch acht da draußen, in Ordnung?", sourceObjectiveStatus = "unverified-source-field" }
quests[13987] = { id = 13987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Gefecht", description = "{name}, ich brauche unbedingt Eure Hilfe! Ich kann gegen diesen Ansturm der Dämonen nicht ewig standhalten. Wenn ich falle, ist Astranaar als nächstes dran!\n\nBitte helft mir!", sourceObjective = "Tötet 30 dämonische Eindringlinge.", progress = "Nur noch ein paar und wir werden es schaffen.", completion = "Ihr habt uns alle gerettet, {name}! Ich habe genug Kräfte, um diesen letzten Rest zu erledigen.\n\nDieser Wald wird die Brennende Legion nicht mehr länger fürchten müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13988] = { id = 13988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit eigenen Augen", description = "Das Leben explodiert förmlich auf diesem kargen Boden... Mein Gefährte Jerrik hat erzählt, dass sich ähnliche Dinge überall im Brachland ereignen. Ich muss es mit eigenen Augen sehen, aber ich darf meinen Posten nicht verlassen.\n\nHier, {name}, ich werde Euch meine 'Augen' leihen. Seit dem Tag, an dem ich meinen Namen erhalten habe, hat mein Adlergefährte hier mir gut gedient. Bitte begleitet ihn zum Donnerkopfgipfel, wo Jerrik Euch erwartet und wir werden uns umsehen.\n\nUm auf die Spitze zu gelangen, folgt der Straße Richtung Osten am Wegekreuz. Wendet Euch nach Süden, sobald Ihr einen großen Stein erreicht, der mit Malereien übersäht ist.", sourceObjective = "Bringt Tongas Augen zum Donnerkopfgipfel südwestlich von Ratschet.", progress = "Tonga kennt dieses Land besser als wir alle, und ich glaube, es hat ihm große Schmerzen bereitet, zu sehen, wie es auseinandergerissen wurde.", completion = "Ich bin froh, dass Tonga in der Lage war, die Überwucherung aus erster Hand mitzuerleben – Wörter können das Ausmaß der Zerstörung nicht angemessen beschreiben. Habt Ihr sein Totem dabei? Ich werde es ihm wiederbringen, wenn ich hier fertig bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[13989] = { id = 13989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König der Fäulnisklauen", description = "Es interessiert mich herzlich wenig, wer Ihr seid, {race}. Worauf es mir ankommt ist die Rettung der Furbolgs.\n\nBringt dieses Blutreißerbanner das kurze Stück in Richtung Nordosten zur Laubtatzenlichtung und platziert es auf ihrem Totemhügel. Sie werden es als einen Angriff ansehen und versuchen, das Banner zu zerstören. Haltet die Stellung. Häuptling Murgut wird auftauchen, um das Gesicht des Stammes zu wahren. Wartet auf ihn und dann tötet den Verräter!\n\nTeilt Eure Kräfte gut ein. Euch steht ein langer Kampf bevor.", sourceObjective = "Platziert das Blutreißerbanner auf dem Totemhügel der Fäulnisklauen. Die Furbolgs dürfen das Banner nicht zerstören, bevor ihr Häuptling kommt. Besiegt Häuptling Murgut.", completion = "Gut. Murgut hat seinen Stamm an die Horde verkauft und sich mit ihr verbündet, als sie Eure kostbare Silberwindzuflucht eingenommen hat, um sein Volk zu 'retten'.\n\nEr hat sie in die Sklaverei verkauft – oder Schlimmeres. Und jetzt hat er bekommen, was er verdient!\n\nLasst uns nun über einen anderen Verräter sprechen. Ich glaube, er besitzt etwas, das Eurer Rute mehr Durchschlagskraft verleihen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13991] = { id = 13991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gestohlene Lohnliste", description = "Und, {name}. Ich gebe zu, dass Ihr gut in meine geliebte Horde passen würdet. Ihr habt Stärke, List und Einsatz bewiesen... Sogar Thork erwähnte Euch kürzlich namentlich, und weder er noch ich sind leicht zu beeindrucken. Gute Arbeit.\n\nJetzt wird es Zeit, dass Ihr Euch weiter in die Riemen legt. Die wöchentliche Lohnliste für die Wachen des Wegekreuzes ist verloren gegangen. Gazrog in Ratschet führt eine Untersuchung an. Sprecht mit ihm!\n\nFolgt einfach der Straße von hier Richtung Osten zur Küste.", sourceObjective = "Sprecht mit Gazrog in der Nähe des Eingangs nach Ratschet.", completion = "Ich hatte auf eine Truppe von Grunzern gehofft... Aber wenn Ihr Euch Sergras Anerkennung verdient habt, schätze ich, dass Ihr der Aufgabe mehr als gewachsen seid. Lasst mich erklären, was hier geschehen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13992] = { id = 13992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kleine Ablenkung", description = "Ich wurde hierher geschickt, um die Aktivitäten der Zentauren auszukundschaften. Ich habe all ihre Bewegungen seit Tagen beobachtet! Es wird Zeit für mich, mich wieder davonzuschleichen, aber sie haben diesen Ort umzingelt.\n\nIhr seht aus, als ob Ihr gefährlich seid. Könnt Ihr ein wenig Chaos für mich veranstalten? Sie aufwühlen! Metzelt sie wahllos nieder. Während sie nach Euch suchen, schleiche ich mich davon, um meinen Bericht an Regthar Totenfurt zu überbringen.", sourceObjective = "Tötet 8 Zentauren der Kolkar.", completion = "Oh ho! Das war wunderbar. Ich hätte vermutlich nicht bleiben und zusehen dürfen. Jetzt suchen sie nach Euch. Ich stehle mich im Staub ihres ziellosen Herumgaloppierens heimlich davon.\n\nHaltet an den anderen Teichen nach meinen Kameraden Ausschau. Der Boss hat an jedem seine Leute.", sourceObjectiveStatus = "unverified-source-field" }
quests[13995] = { id = 13995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der König vom Berge der Zentauren", description = "Wir wurden hierhergeschickt, um die Bewegungen der Zentauren der Kolkar zu beobachten, aber nachdem wir diesen dreckigen Tieren eine Woche dabei zugesehen haben, wie sie um die Oase galoppieren, juckt es mich, meiner Axt ihre Hälse zu schmecken zu geben. Was sagt Ihr, {class}? Wollt Ihr mit mir ein wenig Chaos verbreiten?\n\nMal sehen, ob wir die Aufmerksamkeit ihres stärksten Kriegers Kurak auf uns lenken können.", sourceObjective = "Sorgt dafür, dass Gorgal Zornesnarbe am Leben bleibt, während er sich mit den Zentauren anlegt und helft ihm, Kurak zu töten.", completion = "Warum musstet Ihr Gorgal denn so verärgern? Das Ergebnis gibt Euch allerdings recht. Wir müssen diese Tiere weiterhin gut beobachten, um zu sehen, was sie tun, jetzt wo Kurak aus dem Weg geräumt ist.\n\nAlso weiter beobachten, abwarten und Tee trinken. Gorgal wird das nicht mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13997] = { id = 13997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If You're Reading This While I'm In Combat..." }
quests[13998] = { id = 13998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Pilzkultur", description = "Wir haben diese ungewöhnlichen Sporen kultiviert, die Ihr ausgegraben habt. Das gelang mir mit einer wundervollen Mischung aus... Reagenzien... auf die ich sehr stolz bin. Ich kann es nicht erwarten, zu sehen, wie meine manipulierten Sporen auf die Gewässer in den Oasen am Wegekreuz reagieren.\n\nDie Brackige Oase im Südosten bietet uns eine unverseuchte Region für unsere Experimente. Sät diese Kulturen in der feuchten Erde irgendwo in der Nähe der Oase für mich aus und dokumentiert die Ergebnisse.\n\nAchtet darauf, dass Ihr Euren Mund bedeckt, {class}.\n\n<Helbrim grinst entwaffnend.>", sourceObjective = "Pflanzt eine Pilzkultur in der Nähe der Brackigen Oase und beobachtet das Ergebnis.", completion = "Explosive Sporenwolken? Was Ihr nicht sagt... Erzählt mir mehr. Erstickung? Stechen? Brennen in den Augen? Hat es gejuckt? Übelkeit? Krankheit? Entzückend, ENTZÜCKEND! Ihr habt Euch Eure Bezahlung redlich verdient, {name}.\n\nUnd Euer Hautausschlag müsste eigentlich in ein oder zwei Tagen wieder weg sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13999] = { id = 13999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer hat meinen Zauberpilz gegessen?", description = "Stellt Euch mal vor, was wir damit anstellen können, {name}! Schnellwachsende Pilze, die jedes beliebige Gift übertragen können. Meine Gefährten in der Unterstadt wird das sicher interessieren.\n\nHier sind meine Aufzeichnungen und ein paar Proben. Wenn wir schnell sind, erwischen wir das nächste Schiff, das in Richtung der Östlichen Königreiche in See sticht. Nehmt die Straße östlich von hier und folgt ihr zur Goblinstadt Ratschet. Sucht nach der Taverne 'Zum geborstenen Kiel' im Südteil der Stadt und übergebt dies an meinen Mitarbeiter Sashya.", sourceObjective = "Bringt Helbrims Forschungsergebnisse zu Sashya in Ratschet im Nördlichen Brachland.", progress = "Wer seid Ihr? Hat Helbrim Euch gesandt? Verhaltet Euch unauffällig.", completion = "Ruhe! Gebt mir die Aufzeichnungen. Ist Euch jemand gefolgt?", sourceObjectiveStatus = "unverified-source-field" }
quests[14001] = { id = 14001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettungskapseln der Goblins", description = "{name}, es tut mir leid. Ich dachte, Ihr wärt tot!\n\nEs ist einfach Irrsinn! Wir sind direkt in einen Kampf zwischen der Allianz und der Horde gesegelt.\n\nWir müssen unsere Brüder und Schwestern retten.\n\n<Er zeigt auf die Rettungskapseln, die um Euch herum im Wasser verstreut sind.>\n\nIch glaube, ich bleibe hier noch ein wenig sitzen und komme zu Atem. Könntet Ihr aufs Meer hinausschwimmen und sie herauslassen? Nehmt meine thermohydraulischen Flossen, damit könnt Ihr Euch schneller fortbewegen.\n\nLasst Sassy wissen, dass ich gleich losschwimme.", sourceObjective = "Rettet 6 überlebende Goblins.", completion = "Oh, dem Himmel sei Dank, dass Ihr überlebt habt, {name}! Ich war mir so sicher, dass Ihr ertrunken seid, nachdem ich Euch über Bord habe gehen sehen.\n\n\n\nSchaut nur, wie viele Leute Ihr gerettet habt!\n\n\n\nDas habe ich ja fast vergessen. Ich habe ein paar Eurer Sachen aufgehoben. Nur für den Fall, dass Ihr es schafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[14003] = { id = 14003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Samophlang repariert", description = "Nun, das lief leider nicht so, wie erwartet. Ich glaube, ich habe es kaputt gemacht.\n\nAber kein Grund zur Panik. Tut mir einen Gefallen und folgt diesem Weg zu Brak hier im Lager. Er dengelt dieses Ding schnell wieder in die richtige Form!", sourceObjective = "Bringt das zerbrochene Samophlang hinüber zu Brak Polterrohr innerhalb des Lagers.", progress = "Sagtet Ihr... Samophlang!?", completion = "Stotterspritter hat uns ein Samophlang beschafft? Lasst mich das Ding mal sehen!\n\nJupp, das kriegen wir wieder hin. Kein Problem. Reicht mir den großen Hammer...", sourceObjectiveStatus = "unverified-source-field" }
quests[14004] = { id = 14004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt das Samophlang zurück", description = "Nun, das hat nicht funktioniert. Ich habe ein paar zusätzliche Anzeigegeräte an dem Samophlang angebracht, die seine strukturelle Integrität messen. Sie zeigen stets einen absoluten Tiefstand an. Ich könnte einige Wählscheiben und vielleicht einen Hebel oder zwei hinzufügen und versuchen, es zu reparieren, aber... Ich glaube, das könnte alles nur noch schlimmer machen.\n\nSeht mal, was ich entdeckt habe, als ich das Ablassventil blockiert habe und die Ummantelung des Differentialgehäuses abgeflogen ist: das persönliche Gravurzeichen von 'Boss Kupferdraht'. Bringt dies zurück zu Stotterspritter und sagt ihm, er soll dieses Genie Kupferdraht auftreiben.", sourceObjective = "Bringt das Wrack des überarbeiteten Samophlangs zurück zu Stotterspritter in Düsentopfs Außenposten. Sprecht mit Wenikee, um direkt dorthin teleportiert zu werden.", progress = "Ist das mein Samophlang? Es ist kaum wiederzuerkennen.", completion = "Was hat Wenikee gesagt? Kupferdraht? BOSS Kupferdraht? Oh je, das könnte sich als kompliziert erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14005] = { id = 14005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Rache", description = "Während Teldrassil sich selbst von der Verderbnis reinigt, welche sein Wachstum all die Jahre entstellt hat, hat sich südlich von hier am Rand des Baumes eine bösartige Wucherung gebildet. Wir haben die Möglichkeit, anzugreifen und die Quelle des Teufelsmooses, das die Knarzklauen, die Bäumlinge und alles andere verdorben hat, zu säubern.\n\nMit dem Wasser, das Ihr in den Mondbrunnen gesammelt habt, und der erneuerten Kraft von Teldrassil selbst kann ich Euch eine kurze Zeit große Macht gewähren. Setzt der Verderbnis ein Ende, {name}.", sourceObjective = "Nutzt die Macht, die Tarindrella Euch gewährt hat, um Euch zum Herz der Verderbnis durchzukämpfen und es zu zerstören.", completion = "Elune sei gepriesen!\n\nAlles, worauf ich gestoßen bin, deutet darauf hin, dass die Verderbnis tief in Teldrassil selbst vergraben liegt... Ich hatte schon befürchtet, wir würden die Quelle niemals angreifen können, ohne den Weltenbaum dabei zu töten. Ich bin so dankbar, dass ich falsch lag!\n\nDiese günstige Wendung des Schicksals haben wir Malfurion zu verdanken. Vielleicht werde ich ihn aufsuchen, bevor ich wieder in die Wildnis aufbreche.\n\nVielen Dank, {name}. Danke für alles, was Ihr getan habt. Sicherlich werdet Ihr eines Tages eine große Heldin sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[14006] = { id = 14006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lest das Handbuch", description = "Damals, als ich noch in der Tüftlerverbindung war, war Boss Kupferdraht der beste Ingenieur, den wir hatten. Er wurde abtrünnig und ging zur Venture Company, kurz bevor ich die Tüftlerverbindung verließ, und er nahm seine größten Technologien mit. Er hortete seine Geheimnisse und gab nur hier und da ein Geheimnis an den inneren Kreis seiner Vertrauten weiter.\n\nWenn er das Samophlang gebaut hat, dann besitzt er wahrscheinlich das Handbuch. Das Letzte, was ich von ihm gehört habe, war, dass er hier in der Nähe vor der Felsadermine im Nordosten arbeitet. Besorgt das Handbuch von ihm und sammelt die Seiten ein, die seine Anhänger noch haben.", sourceObjective = "Sammelt die Teile des Samophlanghandbuchs ein.", progress = "Habt Ihr Kupferdraht gefunden?", completion = "Ihr habt es gefunden! Puh, es hat über 600 Seiten, und nur 30 davon wurden absichtlich frei gelassen.\n\nSehen wir uns das mal an. Kapitel drei: Rückspleißung der obenliegenden Kropfachswelle im Schwungrad-Flaschenzug? Interessant. Kapitel Sieben: Ventilsteuerung für die Hochdruck-Expansionskondensatoren!? Was für ein tolles Buch! Und ich weiß immer noch nicht, was dieses Ding macht.\n\nHier, nehmt ein paar meiner alten Werkzeuge. Lassen wir das Ding noch ein letztes Mal an!", sourceObjectiveStatus = "unverified-source-field" }
quests[14007] = { id = 14007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuverlässiger Schuss", description = "Ich bin Bäm Megabombe, Euer persönlicher Lehrer, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als {class} interessiert?\n\nDann seid Ihr hier an der richtigen Adresse. Ich glaube, Ihr werdet davon profitieren, wenn ich Euch die Kunst des zuverlässigen Schusses beibringe. Unter Umständen ist es genau das, was Ihr braucht, um eine weitere Stufe auf der Karriereleiter zu erklimmen, wenn Ihr wisst, was ich meine.\n\nLernt die Fähigkeit bei mir, und übt sie dann an der Trainingsattrappe hier.", sourceObjective = "Sprecht mit Bäm Megabombe, um 'Zuverlässiger Schuss' zu lernen und schießt dann dreimal auf eine Trainingsattrappe.", completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[14008] = { id = 14008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Geschosse", description = "Ich bin Zisch Zündel, Euer persönlicher Lehrer, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als {class} interessiert?\n\nDann seid Ihr hier an der richtigen Adresse. Ich glaube, Ihr werdet davon profitieren, wenn ich Euch die Kunst der arkanen Geschosse beibringe. Unter Umständen ist es genau das, was Ihr braucht, um eine weitere Stufe auf der Karriereleiter zu erklimmen, wenn Ihr wisst, was ich meine.\n\nLernt den Zauber von mir, dann übt ihn ein paarmal an einer Trainingsattrappe am Hof im Südosten.", sourceObjective = "Sprecht mit Zisch Zündel, um 'Arkane Geschosse' zu lernen und wendet den Zauber dann zweimal auf eine Trainingsattrappe an.\n\nBedenkt dabei, dass für 'Arkane Geschosse' die Chance besteht, durch die Nutzung anderer offensiver Zauber ausgelöst zu werden. Verwendet zuerst Euren Zauber 'Feuerball' auf eine Trainingsattrappe, um 'Arkane Geschosse' zu ermöglichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14009] = { id = 14009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzheilung", description = "Ich bin Schwester Goldglanz, Eure persönliche Lehrerin, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als {class} interessiert?\n\nDann seid Ihr hier an der richtigen Adresse. Ich glaube, Ihr werdet davon profitieren, wenn ich Euch die Kunst der Blitzheilung beibringe. Unter Umständen ist es genau das, was Ihr braucht, um eine weitere Stufe auf der Karriereleiter zu erklimmen, wenn Ihr wisst, was ich meine.\n\nLernt den Zauber von mir, dann benutzt ihn, um die verletzten Angestellten im Hof zu heilen.", sourceObjective = "Sprecht mit Schwester Goldschimmer, um 'Blitzheilung' zu lernen, und wendet den Zauber dann dreimal auf einen verletzten Angestellten an.", sourceObjectiveStatus = "unverified-source-field" }
quests[14010] = { id = 14010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausweiden", description = "Ich bin Slinky Scharfklinge, Euer persönlicher Lehrer, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als {class} interessiert?\n\nDann seid Ihr hier an der richtigen Adresse. Ich glaube, Ihr werdet davon profitieren, wenn ich Euch die Kunst des Ausweidens beibringe. Unter Umständen ist es genau das, was Ihr braucht, um eine weitere Stufe auf der Karriereleiter zu erklimmen, wenn Ihr wisst, was ich meine.\n\nLernt die Fähigkeit von mir, dann übt sie an einer Trainingsattrape in der südöstlichen Ecke des Hofs.", sourceObjective = "Sprecht mit Slinky Scharfklinge, um 'Ausweiden' zu lernen, und wendet es dann dreimal auf eine Trainingsattrappe an.\n\nDenkt daran, 'Ausweiden' erfordert Combopunkte, also schlagt die Trainingsattrappe zunächst mit 'Finsterer Stoß'.", progress = "Wann immer Ihr dazu bereit seid, mein Herr.", completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[14011] = { id = 14011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urtümlicher Schlag", description = "Ich bin Lawinus Maximus, Euer persönlicher Lehrer, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als {class} interessiert?\n\nDann seid Ihr hier an der richtigen Adresse. Ich glaube, Ihr werdet davon profitieren, wenn ich Euch die Kunst des urtümlichen Schlags beibringe. Unter Umständen ist es genau das, was Ihr braucht, um eine weitere Stufe auf der Karriereleiter zu erklimmen, wenn Ihr wisst, was ich meine.\n\nLernt ihn von mir, dann benutzt ihn an einer der Trainingsattrappen im Südosten.", sourceObjective = "Sprecht mit Lawinus Maximus, um 'Urtümlicher Schlag' zu lernen und wendet ihn dann zweimal auf eine Trainingsattrappe an.", progress = "Wann immer Ihr dazu bereit seid, mein Herr.", completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[14012] = { id = 14012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerbrand", description = "Ich bin Bosa Blick, Euer persönlicher Lehrer, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als {class} interessiert?\n\nDann seid Ihr hier an der richtigen Adresse. Ich glaube, Ihr werdet davon profitieren, wenn ich Euch die Kunst des Feuerbrands beibringe. Unter Umständen ist es genau das, was Ihr braucht, um eine weitere Stufe auf der Karriereleiter zu erklimmen, wenn Ihr wisst, was ich meine.\n\nLernt den Zauber von mir, dann wirkt ihn auf eine der Trainingsattrappen im Südosten.", sourceObjective = "Sprecht mit Bosa Blick, um 'Feuerbrand' zu lernen, dann wirkt den Zauber 3-mal auf eine Trainingsattrappe.", completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[14013] = { id = 14013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmangriff", description = "<Der Kriegomatic NX-01 schaltet sich ein.>\n\nBoss {name} erkannt. Ich bin Kriegomatic NX-01.\n\nMünzen einwerfen, um Sturmangriff auf Feinde zu lernen. Nach Ausbildung bitte auf Trainingsattrappe in der Nähe anwenden.", sourceObjective = "Sprecht mit dem Kriegomatic NX-01, um 'Sturmangriff' zu lernen. Führt den Angriff dann auf eine Trainingsattrappe aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[14014] = { id = 14014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt unsere Sachen zurück!", description = "Unsere Bomben und Werkzeuge! Diese hinterhältigen Affen aus dem Osten haben sie alle im Schutz der Dunkelheit gestohlen!\n\nKönnt Ihr dorthin gehen und sie für uns zurückholen, {name}? Ohne diese Werkzeuge haben wir keine Chance, von dieser Insel herunterzukommen!", sourceObjective = "Besorgt 8 Werkzeugkisten.", progress = "Bombenwerfende Affen?! Nicht auszudenken!!!", completion = "<Sassy atmet beim Anblick der Werkzeuge und Bomben, die Ihr zurückgeholt habt, erleichtert auf.>\n\nIch dachte, das wäre unser sicherer Untergang. Aber jetzt können wir daran arbeiten, von dieser Insel zu fliehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14016] = { id = 14016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluch des Schwarzen Ritters", description = "Ich wollte die Überreste des Schwarzen Ritters nach Eurem Sieg vom Turnierplatz entfernen lassen, aber Argentumbeichtpatin Blondlocke bestand darauf, dass er ein ordentliches Begräbnis erhält. Seither hält sich eine düstere Gegenwart hartnäckig auf dem Friedhof, und niemand wagt sich mehr dorthin, um die Gefallenen zu ehren.\n\nWürdet Ihr dem Friedhof gleich außerhalb des Turnierplatzes im Osten einen Besuch abstatten und sehen, ob Ihr herausfinden könnt, was dort vor sich geht?", sourceObjective = "Kreuzfahrerin Rhydalla auf dem Argentumturnierplatz möchte, dass Ihr das Grab des Schwarzen Ritters untersucht.", completion = "<Kreuzfahrerin Rhydalla runzelt die Stirn.>\n\nGlaubt Ihr, sie haben das geplant? Spielt vermutlich keine Rolle, doch es gefällt mir nicht, dass wir ihnen womöglich genau in die Hände gespielt haben. Was immer auch vor sich geht, wir müssen es vereiteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[14017] = { id = 14017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal des Schwarzen Ritters", description = "Ihr sagt, dass Kultisten die Leiche entfernt haben? Mir fällt da nur ein Ort ein, zu dem sie sie gebracht haben können: Todessprechers Wacht, das Lager auf der Anhöhe westlich des Turnierplatzes.\n\nWas auch immer die Kultisten vorhaben, man muss sie aufhalten. Die Gerüchte, die ich gehört habe, können also nur wahr sein. Der berüchtigte Doktor Kohler muss unter den Kultisten sein und seine Kunst ausüben. Sucht nach einer Anhöhe oder einem Altar, von dem aus man Sicht auf das Kultistenlager hat. Tötet den Doktor und sucht nach Beweisen über seine Machenschaften. Bremst ihn bei seiner Arbeit, egal wie.", sourceObjective = "Geht nach Todessprechers Wacht, bringt Doktor Kohlers Befehle in Euren Besitz und kehrt dann zu Kreuzfahrerin Rhydalla auf dem Argentumturnierplatz zurück.", progress = "Habt Ihr herausgefunden, was sie mit den Überresten des Schwarzen Ritters machen?", completion = "Der Doktor wird keine Zeit haben, sein Werk zu vollenden, aber sein Plan wurde schon ins Rollen gebracht. Laut Euren Berichten haben die Diener des Lichkönigs den Schwarzen Ritter wiederbelebt und mit neuer Kraft erfüllt - niemand kann sagen, was sein Meister im Schilde führt. Diese Verschwörung aufzudecken war gute Arbeit. Ich werde dem Hochmeister Adelard von Euren Funden berichten und gemeinsam werden wir die Teilnehmer des Turniers davor warnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14018] = { id = 14018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jener, der nach Vergebung sucht", description = "Die Stimme der Göttin hat am Mondbrunnen zu Euch gesprochen, {name}. Das Heilmittel für Relara liegt im Osten beim Rajenbaumturm, der dem Verderben anheimgefallen ist.\n\nAvrus Böswisper wünscht Vergebung und Erlösung. Es liegt an Euch, ihn zu unterstützen und dabei hoffentlich auch meinem Kind zu helfen.", sourceObjective = "Sprecht mit Avrus Böswisper beim Rajenbaumturm im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[14019] = { id = 14019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Affentheater", description = "Wir haben immense Probleme mit den Affen im Dschungel östlich von hier. Sie haben all unseren Sprengstoff gestohlen und jetzt fangen sie an, damit durch die Gegend zu werfen.\n\nUnd manchmal sogar auf uns!\n\nIch habe Zisch Zündel befohlen, etwas von seinem Nitro in diese Bananen zu füllen. Kein Affe kann einer leckeren Banane widerstehen!\n\nIhr müsst sie nur damit füttern.", sourceObjective = "Füttert 10 bombenwerfende Affen, indem Ihr ihnen Nitrokaliumbananen zuwerft.", completion = "Sie sind in die Luft gegangen, als sie die Bananen gegessen haben?! Das ist ja urkomisch!\n\nIch glaube, ich ziehe auch los und füttere ein paar.", sourceObjectiveStatus = "unverified-source-field" }
quests[14021] = { id = 14021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minenarbeiter in Not", description = "Kluge Bergbauaffen!\n\nSie sind in der ganzen Höhle verstreut und bauen Erz ab… mit Spitzhacken! Das ist doch nicht normal. Ich bin mir sicher, dass es an dem Kaja'mit liegt.\n\nKeiner meiner Minenarbeiter ist wieder herausgekommen. Und ich habe nicht mehr viele! Ihr könnt also meine Not erkennen, {name}.\n\n<Der Vorarbeiter senkt die Stimme.>\n\nDiese Typen sind nicht mal annähernd so gut wie meine alte Dschungeltrolltruppe. Ah, das waren noch Zeiten!\n\nVielleicht könnt Ihr meinen letzten Minenarbeiter hier durch die Höhle begleiten und ihm die Affen vom Leib halten? Wir brauchen dieses Kaja'mit!", sourceObjective = "Eskortiert den verängstigten Minenarbeiter durch die Kaja'mithöhle.", completion = "Wir haben die Hauptader gefunden!!!\n\nSo, was hat es mit diesem Hexendoktor der Pygmäen auf sich, der die Affen kontrolliert? Wenn er nämlich tot ist, kann ich ganz legal Anspruch geltend machen… Nicht, dass ich das nicht sowieso vorgehabt hätte. Nach Goblinrecht gehört die Kaja'mithöhle uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[14022] = { id = 14022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilgerfreuden", description = "Möchtet Ihr nicht vielleicht das Pilgerfreudenfest mit uns feiern, {name}? Dies ist eine Zeit des Besinnens auf Eure Reisen und Euer Glück, eine Zeit des Teilens - von gutem Essen und unterhaltsamen Geschichten!\n\nIhr könnt an den wundervollen Pilgerfreudenfeierlichkeiten in der Nähe der größeren Städte teilhaben, indem Ihr an einer der Festtafeln Platz nehmt und das vorhandene Essen verteilt.\n\nWenn Ihr lernen möchtet, wie man die traditionellen Pilgerfreudenspeisen zubereitet, sucht Gregory Tabor auf. Ihr findet ihn vor den Toren von Sturmwind.", sourceObjective = "Sprecht mit Gregory Tabor außerhalb der Tore Sturmwinds.", completion = "Wenn Ihr an der Zubereitung traditioneller Pilgerfreudengerichte interessiert seid, kann ich Euch helfen. Falls Ihr noch keine Kochkenntnisse besitzt, braucht ihr nur ein wenig zu üben und im Nu seid Ihr ein richtiger Koch!", sourceObjectiveStatus = "unverified-source-field" }
quests[14023] = { id = 14023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzbrotfüllung", description = "Unsere Gewürzbrotfüllung ist das Prunkstück der Pilgerfreudentafel. Das Rezept war schon immer besonders beliebt in Sturmwind und hat nun seinen rechtmäßigen Platz im Pilgerfreudenfest-Kochbuch eingenommen.\n\nWenn Ihr in der Kochkunst bereits bewandert seid, könnt Ihr Euer Exemplar des Kochbuchs und alle benötigten Zutaten für ein Festmahl vom Händler des Pilgerfreudenfests erstehen. Und seid Ihr es nicht, so ist jetzt die beste Gelegenheit, dies zu ändern!\n\nHabt Ihr die Gewürzbrotfüllung zubereitet, bringt sie zu Jasper Moore, in der Nähe der Festtafel.", sourceObjective = "Bereitet 5 Portionen Gewürzbrotfüllung zu und bringt sie zu Jasper Moore an die Festtafel außerhalb der Tore Sturmwinds.", progress = "Wir können immer etwas von der köstlichen Gewürzbrotfüllung gebrauchen, sie ist ausgesprochen beliebt.", completion = "Ausgezeichnet. Genau was wir brauchen! Es ist harte Arbeit, dafür zu sorgen, dass die Tische niemals leer werden, doch es lohnt sich!", sourceObjectiveStatus = "unverified-source-field" }
quests[14024] = { id = 14024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kürbiskuchen", description = "Eure Gewürzbrotfüllung riecht ausgesprochen verlockend, doch keine Pilgerfreudentafel ist ohne einen prächtigen Kürbiskuchen komplett. Dies ist ein weiteres sehr beliebtes Gericht hier in Sturmwind, denn Kürbiskuchen wird aus den reifen Elwynnkürbissen zubereitet, die nur hier gedeihen.\n\nSolltet Ihr nicht wissen, wie man ihn zubereitet, könnt Ihr das Rezept in Eurem Pilgerfreundenfest-Kochbuch finden.\n\nWürde es Euch etwas ausmachen, einige Kuchen zuzubereiten und sie Edward Winslow zu bringen, außerhalb von Eisenschmiede? Sein Vorrat ist sicherlich schon knapp geworden.", sourceObjective = "Bereitet 5 Kürbiskuchen zu und bringt sie Edward Winslow an die Festtafel außerhalb von Eisenschmiede.", progress = "Mehr Kürbiskuchen? Genau rechtzeitig.", completion = "Der Kürbiskuchen ist hier oben ausgesprochen beliebt. Ich habe noch nie zuvor gesehen, dass Zwerge über ein Gemüsegericht so aus dem Häuschen geraten!", sourceObjectiveStatus = "unverified-source-field" }
quests[14028] = { id = 14028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moosbeerenchutney", description = "Wenn Ihr bislang noch nie Moosbeerenchutney versucht habt, dann entgeht Euch etwas! Es wird aus den frischesten, schmackhaftesten Moosbeeren des ganzen Sumpflands zubereitet. Ersteht einfach welche vom nächsten Händler des Pilgerfreudenfests, wenn Ihr Euch an der Zubereitung versuchen wollt.\n\nDas Rezept findet Ihr in Eurem Pilgerfreudenfest-Kochbuch.\n\nWenn Ihr nicht in Eile seid, würdet Ihr vielleicht etwas Chutney zubereiten und zu Jasper Moore bringen, außerhalb Sturmwinds? Ich habe ihm versprochen, es gegen den Kuchen einzutauschen, den Ihr mir gebracht habt.", sourceObjective = "Bereitet 5 Portionen Moosbeerenchutney zu und bringt sie zu Jasper Moore an die Festtafel außerhalb Sturmwinds.", progress = "Rieche ich da etwa Moosbeerenchutney?", completion = "Endlich, das versprochene Moosbeerenchutney! Ihr glaubt ja nicht, wie schnell die Feiernden das immer verputzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14030] = { id = 14030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darnassus darbt", description = "Vielen Dank für das Moosbeerenchutney. Es gibt so viel zuzubereiten, ich kann kaum noch einen klaren Gedanken fassen! Und zu all dem kommt nun noch, dass Isaac Allerton in Darnassus mittlerweile praktisch alle Zutaten ausgegangen sind! Ich kann wohl kaum erwarten, dass Ihr so gut wäret, einzuspringen und etwas mehr Gewürzbrotfüllung und Kürbiskuchen zuzubereiten, oder? Der Händler sollte alle Zutaten parat haben, die Ihr benötigen würdet.\n\nIhr könnt ihn in der Nähe der Festtafel finden, auf der Wiese hinter der Terrasse der Krieger in Darnassus.", sourceObjective = "Bringt 5 Portionen Gewürzbrotfüllung und 5 Kürbiskuchen zu Isaac Allerton in der Nähe des Eingangs nach Darnassus.", progress = "Seid Ihr gekommen, um am Pilgerfreudenfestmahl teilzunehmen?", completion = "Vielen Dank für alles! Ich hatte schon begonnen, mir Sorgen zu machen. Da Ihr schon mal hier seid, könntet Ihr gleich auch noch Euer Glück mit der Zubereitung kandierter Süßkartoffeln versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14031] = { id = 14031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfasst das Unbekannte", description = "Hey, {name}, da sind Höhlenmalereien und andere Artefakte überall in der Höhle.\n\nKönntet Ihr Eure am Gürtel befestigte HGK Schnappblitz verwenden, um an den markierten Orten Bilder aufzunehmen? Nehmt im hinteren Teil der Höhle ein Bild des Altars auf.\n\nIch bin sicher, Sassy würde diese Informationen gern in die Hände bekommen.", sourceObjective = "Verwendet Eure HGK Schnappblitz, um Bilder an den springenden Kameras der drei Höhlenmalereien und dem Altar der Pygmäen aufzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14032] = { id = 14032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung im Koboldlager", description = "Eure erste Aufgabe ist eine Säuberung, {name}. Ein Koboldklan hat sich in den Wäldern im Norden eingenistet. Begebt Euch dorthin und bekämpft das Koboldgezücht, das Ihr dort finden werdet. Dezimiert es, damit wir die Kobolde eines Tages gänzlich aus Nordhain vertreiben können.", sourceObjective = "Tötet 8 von dem Koboldgezücht und kehrt dann zu Marschall McBride zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[14033] = { id = 14033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kandierte Süßkartoffeln", description = "Solange Ihr hier seid, solltet Ihr Euch einen Vorrat an Süßkartoffeln von Teldrassil zulegen. Aus ihnen werden die köstlichsten kandierten Süßkartoffeln zubereitet, die Ihr je schmecken werdet!\n\nWenn Ihr mir nicht glaubt, sucht das Rezept aus Eurem Pilgerfreudenfest-Kochbuch heraus und probiert es mal! Und solltet Ihr welche übrig haben, könntet Ihr sie mit Gregory Tabor in der Nähe der Festtafel außerhalb Sturmwinds teilen. Er liebt diese Kartöffelchen! Aber wenn man ihm so zuhört, gewinnt man den Eindruck, er liebt alles, was man essen kann.", sourceObjective = "Bereitet 5 Portionen kandierte Süßkartoffeln zu und bringt sie zu Gregory Tabor außerhalb der Tore Sturmwinds.", progress = "{name}, wie schön, Euch zu sehen.", completion = "Aaah, kandierte Süßkartoffeln! Meine Leibspeise! Hat Isaac Euch davon erzählt?", sourceObjectiveStatus = "unverified-source-field" }
quests[14034] = { id = 14034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foote, der Mann mit dem Plan", description = "Wir haben von den Spannungen zwischen der Allianz und der Horde profitiert, bis Konteradmiral Hartley in MEINEM Hafen angelegt hat und angefangen hat, seine Nase in meine Angelegenheiten zu stecken. Er hat Schiffe gejagt und beschlagnahmt, die unter der Flagge der Horde gesegelt sind, mit dem Ziel, sie davon abzuhalten, einen neutralen Hafen anzulaufen.\n\nIch werde sicher keinem wurstfingrigen Menschen erlauben, meinen Profit zu schmälern! Besorgt mir die Pläne des Flaggschiffs. Hartleys Chefingenieur pichelt sich in der Taverne zum geborstenen Kiel einen an, einfach den Hügel hinauf...", sourceObjective = "Besorgt die Schiffsschemata von Chefingenieur Foote in der Taverne 'Zum geborstenen Kiel' in Ratschet.", progress = "Habt Ihr, was ich brauche?", completion = "Ah, da sind sie – da steht es, genau hier! Sein Flaggschiff heißt also 'Die Kriegsmächtige', wie?\n\nWollen wir mal sehen, was man braucht, um diesen Plagegeist auf den Meeresgrund zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[14035] = { id = 14035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langsam gerösteter Truthahn", description = "Jedes Pilgerfreudenfestmahl benötigt einen Mittelpunkt der Tafel, und damit meine ich kein dekoratives Füllhorn. Nein, die wahre Krönung der Tafel ist ein schmackhafter gerösteter Truthahn.\n\nIhr findet ein fabelhaftes Rezept dafür in Eurem Pilgerfreudenfest-Kochbuch. Warum erlegt Ihr nicht ein paar wilde Truthähne und bereitet sie selbst zu? Diese Tierchen sind überall im Wald von Elwynn unterwegs, Ihr solltet sie leicht aufspüren können.\n\nKönnt Ihr sie zu Isaac Allerton an die Tore von Darnassus bringen, sobald sie fertig zubereitet sind?", sourceObjective = "Bereitet 5 langsam geröstete Truthähne zu und bringt sie zu Isaac Allerton, in der Nähe der Tore von Darnassus.", progress = "Was hat Euch denn wieder nach Darnassus verschlagen, {name}?", completion = "Die sind grandios! Und sie kommen genau rechtzeitig, um hungrige Mäuler zu stopfen. Danke, {name}! Ihr habt wahrlich alle Gänge eines traditionellen Pilgerfestmahls gemeistert.", sourceObjectiveStatus = "unverified-source-field" }
quests[14036] = { id = 14036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilgerfreuden", description = "Seid Ihr hier, um mit uns das Pilgerfreudenfest zu feiern? Dies war einst eine Zeit der Einkehr und des Gedenkens an getane Reisen und das Glück, ein gutes Mahl mit Freunden teilen zu können. Noch heute feiern viele das Fest.\n\nIhr könnt an Pilgerfreudenfeierlichkeiten in der Nähe größerer Städte teilnehmen, indem Ihr an einer der Festtafeln Platz nehmt und das dort vorhandene Essen verteilt.\n\nWenn Ihr an der Zubereitung traditioneller Pilgerfreudengerichte interessiert seid, wendet Euch an Miles Standish im Innenhof über Unterstadt.", sourceObjective = "Sprecht mit Miles Standish im Innenhof über Unterstadt.", completion = "Wenn Ihr an der Zubereitung traditioneller Pilgerfreudengerichte interessiert seid, kann ich Euch helfen. Falls Ihr noch keine Kochkenntnisse besitzt, braucht ihr nur ein wenig zu üben und im Nu seid Ihr ein richtiger Koch!", sourceObjectiveStatus = "unverified-source-field" }
quests[14037] = { id = 14037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzbrotfüllung", description = "Unsere Gewürzbrotfüllung ist das A und O der Pilgerfreudentafel. Das Rezept stammt aus besseren Tagen in Lordaeron und hat nun seinen Platz unter den traditionellen Gerichten gefunden.\n\nSeid Ihr bereits in der Kochkunst bewandert, stattet dem Händler des Pilgerfreudenfests einen Besuch ab und Ihr erhaltet Euer eigenes Exemplar des Pilgerfreundenfest-Kochbuchs und alle hiesigen Zutaten, die Ihr benötigt, um ein Festmahl zuzubereiten. Seid Ihr noch unerfahren in der Kunst des Kochens, so ist dies die beste Gelegenheit für Euch, zu beginnen!\n\nSobald Ihr die Füllung zubereitet habt, übergebt sie William Mullins in der Nähe der Festtafel.", sourceObjective = "Bereitet 5 Portionen der Gewürzbrotfüllung zu und bringt sie dann zu William Mullins an die Festtafel im Innenhof über Unterstadt.", progress = "Die Tafel könnte wirklich noch etwas mehr Gewürzbrotfüllung vertragen.", completion = "Dafür zu sorgen, dass die ganze Festtafel immer schön gefüllt bleibt, ist keine einfache Aufgabe. Und wenn man bedenkt, dass wir eigentlich gar nicht mehr zu essen brauchen, kommt es einem besonders eigenartig vor.\n\n<William zuckt mit den Achseln.>\n\nTradition ist Tradition.", sourceObjectiveStatus = "unverified-source-field" }
quests[14038] = { id = 14038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minenarbeit", description = "<Gazlowe breitet die Pläne auf dem Tisch aus und tippt mit seinem kleinen Finger auf das Achterdeck eines Schiffes unter der Wasserlinie.>\n\nDa! Dort ist der Rumpf am dünnsten, wo die Kurbelwelle auf das Schaufelrad trifft. Und das ist direkt neben dem Magazin!\n\n{name}, man wird mich doch nicht zur Verantwortung ziehen können, wenn so ein tollkühner {class} der Horde eine Haftmine an dieser Stelle des Rumpfs anbringt. Nicht einmal, wenn ich die Mine zur Verfügung stelle. Und ihn bezahle. Großzügig. Das Schiff liegt südöstlich von hier vor Anker... nichts wie hin!\n\nDann funkt mich über diesen gestohlenen Gnomcorder an.", sourceObjective = "Setzt eine Haftmine an den dünnsten Teil des Rumpfs der Kriegsmächtigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14039] = { id = 14039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heimat der Kaldorei", description = "Es war zweifellos eine große Ehre, Euch kennengelernt zu haben. Ihr seid der lebende Beweis dafür, wie nobel Euer Volk ist.\n\nGeht jetzt und beendet diese letzte Aufgabe. Bringt das Wasser zu Tyrande Wisperwind in Darnassus.", sourceObjective = "Bringt das gefüllte Gefäß zu Tyrande Wisperwind in Darnassus.", progress = "Wie ist es Euch ergangen, junge Dame?", completion = "Ah, gesegnetes Wasser aus unseren Mondbrunnen. Ihr seid also Zeuge des Geistes der Kaldorei geworden?\n\nIn letzter Zeit fällt mir immer mehr auf, dass dieser Geist mehr Fragen aufwirft als beantwortet. Aber so ist nun mal die ständige Natur der Entdeckungen, die uns in unseren dunkelsten Stunden umtreibt.\n\nIch werde Euch die einfachsten Antworten geben, die mir zur Verfügung stehen. Malfurion ist zu mir... zu uns... zurückgekehrt, dennoch sind wir schweren Zeiten ausgesetzt. Hirschhaupt ist verschwunden und die Welt windet sich vor Schmerzen - Malfurion muss viel heilen und er wird Hilfe benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14040] = { id = 14040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kürbiskuchen", description = "Eure Gewürzbrotfüllung ist einfach wunderbar, aber uns fehlt noch der ein oder andere Kürbiskuchen zum Glück. Ein weiteres traditionelles Gericht der Region, denn hierzu werden reife Tirisfalkürbisse verwendet, die nirgends sonst gedeihen. \n\nFalls Ihr nicht wisst, wie man sie zubereitet, findet Ihr das Rezept in Eurem Pilgerfreudenfest-Kochbuch.\n\nMacht es Euch etwas aus, uns ein paar zuzubereiten und sie Francis Eaton außerhalb von Orgrimmar zu bringen? Ich bin sicher, es sind nicht mehr viele übrig.", sourceObjective = "Bereitet 5 Stücke Kürbiskuchen zu und bringt sie zu Francis Eaton an die Festtafel außerhalb von Orgrimmar.", progress = "Wir können immer frischen Kürbiskuchen gebrauchen.", completion = "Der Kuchen geht weg wie warme Semmeln. Ich glaube ja, die Leute halten sich gar nicht erst mit dem Hauptgericht auf, sondern gehen gleich über zum Nachtisch. Habt Ihr den Kuchen denn schon selbst einmal versucht?", sourceObjectiveStatus = "unverified-source-field" }
quests[14041] = { id = 14041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moosbeerenchutney", description = "Habt Ihr einmal das Moosbeerenchutney versucht? Es wird aus frischen, schmackhaften säuerlichen Moosbeeren vom Südstrom zubereitet. Besorgt Euch einfach welche vom Händler des Pilgerfreudenfests, wenn Ihr Euch mal am Rezept versuchen wollt.\n\nIhr findet es in Eurem Pilgerfreudenfest-Kochbuch.\n\nWenn Ihr nicht zu viel zu tun habt, könntet Ihr vielleicht etwas Chutney zubereiten und es zu Dokin Grasland am Fuße des Aufzugs bringen, westlich von Donnerfels?", sourceObjective = "Bereitet 5 Portionen Moosbeerenchutney zu und bringt sie zu Dokin Grasland am Fuße des Aufzugs westlich von Donnerfels.", progress = "Wie gefallen Euch die Pilgerfreuden, {class}?", completion = "Ah, endlich, mehr Moosbeerenchutney! Es ist unfassbar, wie schnell die Feiernden es vertilgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14042] = { id = 14042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kabummition", description = "Hartley muss all seine Sprengmittel am Strand entladen haben. Ziehen wir ihm diesen Zahn, {name}!\n\nGeht den Strand entlang und sucht nach seinen Sprengstoffvorräten. Zündet sie an und er sitzt ohne Bewaffnung an Land fest, während die Kriegsmächtige repariert wird.\n\nIch treffe Euch wieder hier in Ratschet.", sourceObjective = "Zerstört 5 Munitions-Vorratslager von Theramore an der Küste.", completion = "Ha! Sehr gut gemacht, {name}. Diese Idioten von der Allianz werden das niemals zu mir zurückverfolgen können. Inzwischen heißt es wieder zurück zur Tagesordnung: Schmuggel, doppelte Spielchen und Wucher... Ich habe viel nachzuholen.\n\nHier habt Ihr einen Anteil von meinen Gewinnen. Viel Spaß damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[14043] = { id = 14043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kandierte Süßkartoffeln", description = "Da Ihr schon mal hier seid, solltet Ihr gleich Euren Vorrat an Süßkartoffeln aus Mulgore aufstocken. Sie werden für die Zubereitung kandierter Süßkartoffeln verwendet, mein absoluter Favorit auf der Festtafel.\n\nWenn Ihr meinem Urteil nicht traut, sucht Euch das Rezept heraus und probiert es einmal! Solltet Ihr unterwegs nach Orgrimmar sein, könnt Ihr sie gleich zu Francis Eaton in der Nähe der Festtafel direkt außerhalb der Stadt bringen. Ich bemühe mich, ihn ausreichend zu versorgen, aber dort geht immer alles so schnell weg!", sourceObjective = "Bereitet 5 Portionen kandierte Süßkartoffeln zu und bringt sie zu Francis Eaton außerhalb der Tore Orgrimmars.", progress = "Willkommen zurück, {name}.", completion = "Dokin hat Euch also dazu überredet, mit den kandierten Süßkartoffeln auszuhelfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14044] = { id = 14044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstadt ist unterversorgt", description = "Vielen Dank für die kandierten Süßkartoffeln. Es gibt soviel zu kochen, ich komme kaum hinterher! Und jetzt schickt mir Miles auch noch eine Nachricht, dass ihm Gewürzbrotfüllung und Moosbeerenchutney ausgehen! Ihr hättet nicht zufällig Zeit, mir damit noch etwas unter die Arme zu greifen und ein wenig mehr von beidem zu kochen? Der Händler sollte alle nötigen Zutaten vorrätig haben.\n\nIhr könnt Miles Standish in der Nähe der Festtafel finden, im Innenhof in den Ruinen über Unterstadt.", sourceObjective = "Bringt 5 Portionen Gewürzbrotfüllung und 5 Portionen Moosbeerenchutney zu Miles Standish in der Nähe des Eingangs von Unterstadt.", progress = "Wie gut, Euch wiederzusehen, {name}.", completion = "Vielen Dank für alles, was Ihr gebracht habt. Einige der Tische machen schon langsam einen etwas kahlen Eindruck.", sourceObjectiveStatus = "unverified-source-field" }
quests[14045] = { id = 14045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Baron Küstenschipper", description = "Der ruchlose Pirat Baron Küstenschipper war der Schrecken dieser Meere, bevor die Allianz seine Flotte zerstört hat und die Überlebenden gefangen genommen hat. Gefällt mir das? Sehe ich aus, als ob ich vor Freude hüpfe und springe, {name}?\n\nKüstenschipper hat einige meiner wertvollsten Ladungen vor seiner Gefangennahme geraubt. Man sagt, er habe sie vergraben, bevor er gefangen genommen wurde. Ich will meine Waren wieder zurück haben! Findet Küstenschipper im Lager der Allianz südlich von hier und versucht, ihm zu entlocken, wo mein Schatz ist.", sourceObjective = "Findet den berüchtigten Piraten Baron Küstenschipper und sprecht mit ihm.", completion = "Ha ha! Der alte Gazlowe hat seine Schätze also noch nicht abgeschrieben, oder? Nun, es sieht so aus, als ob mir das alte, goldgierige Langohr was zum Verhandeln gegeben hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[14046] = { id = 14046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ehemaliger Baron", description = "Ich werd' sicher am Galgen landen, Kamerad. Jetzt nützt mir der Schatz nur noch herzlich wenig...\n\nEs sei denn, ich kann mir damit mein Leben erkaufen. Ich schlag Euch'n Geschäft vor, {race}. Befreit mich von diesen Handschellen und ich sage Euch, wo der Schatz verbuddelt ist.\n\nUnd auf mein Wort ist Verlass. Ich war mal ein richtiger Baron, müsst Ihr wiss'n.", sourceObjective = "Wenn Ihr ihm traut, sprecht mit Baron Küstenschipper, um ihn von seinen Handschellen zu befreien.", completion = "<Der Baron reibt sich seine wunden Handgelenke und bricht in ein bösartiges Grinsen aus.>\n\nOh, ich werde mich noch nicht dünne machen. Ich befreie meine Kameraden und haue und steche mir meinen Weg hier heraus, sobald mir danach ist. Und was Euch angeht – versprochen ist versprochen. Reden wir über diesen Schatz...", sourceObjectiveStatus = "unverified-source-field" }
quests[14047] = { id = 14047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langsam gerösteter Truthahn", description = "Zu jedem Pilgerfreudenfestmahl gehört ein kulinarischer Höhepunkt - für uns ist das ein langsam gerösteter Truthahn. Es gibt nichts besseres, um ein reichhaltiges Mahl angemessen zu krönen!\n\nIhr findet ein gutes Rezept dafür in Eurem Pilgerfreudenfest-Kochbuch. Warum jagt Ihr nicht ein paar Truthähne und bereitet sie dann zu? Sie sind überall in Tirisfal zu finden.\n\nWenn sie fertig sind, könntet Ihr sie dann zu Francis Eaton außerhalb von Orgrimmar bringen?", sourceObjective = "Bereitet 5 langsam geröstete Truthähne zu und bringt sie zu Francis Eaton, in der Nähe der Tore von Orgrimmar.", progress = "Was hat Euch denn wieder nach Orgrimmar verschlagen, {name}?", completion = "Die sehen köstlich aus. Vielen Dank, {name}. Ihr habt wahrlich alle Gänge eines traditionellen Pilgerfestmahls gemeistert.", sourceObjectiveStatus = "unverified-source-field" }
quests[14048] = { id = 14048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich krieg einfach nicht genug ... Truthahn", description = "Ich hab schon vor den Feiertagen angefangen zu kochen und seitdem nicht mehr aufgehört! Und es ist trotzdem nie genug - könnte ich Euch vielleicht überreden, mir zur Hand zu gehen?\n\nTruthahn bekommt man hier schwer, wenn Ihr mir also ein paar langsam geröstete Truthähne bringen könntet, wäre das eine enorme Hilfe. Möchtet Ihr ihn selbst zubereiten, könnt Ihr die Truthähne überall in Tirisfal selbst erjagen. Alle weiteren Zutaten erhaltet Ihr bei jedem Händler des Pilgerfreudenfests.", sourceObjective = "Bringt 20 langsam geröstete Truthähne zu Caitrin Eisenkessel außerhalb von Eisenschmiede.", progress = "Habt Ihr ein paar Truthähne aufgespürt?", completion = "Genau das Richtige, vielen Dank, {name}. Ihr habt es genau getroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14049] = { id = 14049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine äußerst ungewöhnliche Karte", description = "Also, es ist so, Kamerad: Um meine Schatzkarte zu beschützen, habe ich sie auf die Kopfhaut meines ersten Steuermanns tätowiert.\n\nNatürlich ist er bereits genauso tot wie der Großteil vom Rest meiner Mannschaft. Die Mitglieder der Allianz wissen nicht einmal, was sie da in Händen halten. Sein abgeschlagener Kopf hängt an einem Baum am Eingang zu diesem Lager.\n\nSchnappt Euch den Kopf und bringt ihn zu Gazlowe in Ratschet.", sourceObjective = "Besorgt Euch den tätowierten Piratenkopf vom Eingang des Geländes der Allianz.", progress = "War Baron Küstenschipper noch am Leben? Habt Ihr etwas für mich?", completion = "Was? Was ist das? Ich schicke Euch los, meinen Schatz zu finden und Ihr bringt mir einen verlausten Kopf?", sourceObjectiveStatus = "unverified-source-field" }
quests[14050] = { id = 14050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gazlowes Vermögen", description = "Verteufelt noch eins, Ihr hattet recht! Auf die Kopfhaut ist eine Karte tätowiert.\n\nDieser verfluchte Baron! Er hat meinen Schatz direkt unter meiner Nase vergraben. Oder über meinem Kopf. Diese Karte deutet auf einen Ort an den Steilufern über Ratschet im Süden.\n\nFolgt der Straße nach Westen aus der Stadt, begebt Euch auf den Hügel, geht nach Süden, dann lauft zurück zur Küste und sucht nach dem riesigen Baum, von dem aus man die Bucht überblickt. Schnappt Euch meinen Schatz und ich werde ihn mit Euch teilen!", sourceObjective = "Gazlowe will, dass Ihr seinen verscharrten Schatz an den Klippen mit Meerblick ausgrabt.", progress = "Ich schließe jetzt meine Augen, {name}. Und wenn ich sie wieder öffne, erwarte ich, dass dieser Raum randvoll mit Schätzen ist. Einverstanden?", completion = "Gute Arbeit, {name}!\n\nOh, der Baron hat versucht, Euch aufzuhalten, wie? Nun, ich hoffe, Ihr habt's ihm gezeigt.\n\nNun, ich habe Euch einen Anteil an dem Schatz versprochen, den Ihr zurückgebracht habt. Mal sehen... Wie viel ist ein Prozent von einem halben Prozent? Ah, hier bitte schön.", sourceObjectiveStatus = "unverified-source-field" }
quests[14051] = { id = 14051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Füllung ist alles!", description = "Dafür zu sorgen, dass die Festtafeln gefüllt bleiben, ist kein Kinderspiel! Ich muss das Moosbeerenchutney zubereiten, die Süßkartoffeln im Auge behalten und gleichzeitig auch noch dafür sorgen, dass der Kürbiskuchen nicht anbrennt.\n\nIch glaube, ich habe alles soweit im Griff. Moment, ich habe doch irgendwas vergessen ... Oh nein, die Füllung! Jetzt bleibt mir keine Zeit mehr dafür, bevor ich nicht mit dem Rest fertig bin. Äh, vielleicht könntet Ihr mir da aushelfen? Es sollte nicht allzu lang dauern, etwas Gewürzbrotfüllung zu kaufen oder selbst zuzubereiten, die Zutaten könnt Ihr direkt hier besorgen.", sourceObjective = "Bringt 20 Portionen Gewürzbrotfüllung zu Caitrin Eisenkessel nahe der Festtafel außerhalb von Eisenschmiede.", progress = "Wie sieht es mit der Füllung aus?", completion = "Ein Glück, Ihr habt es geschafft! Ohne Gewürzbrotfüllung wäre das ganze Festmahl ein einziger Reinfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[14052] = { id = 14052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter vier Augen mit Tony", description = "Die Situation mit den Piraten behindert meine Unternehmungen erheblich. Käpt'n Garvey greift jedes Schiff an, das er erblickt - sogar diejenigen, von deren Besitzern ich mir ein 'Schutz'-Geld erschwindelt habe. Wir müssen diese Piraten auf frischer Tat ertappen und zwar bald!\n\nIch kenne genau den richtigen Gesellen, ein Leutnant von Garvey, der sich auf die Kungeleien vom alten Flunkerblick einlässt. Er hat mir angeboten, für mich eine kleine 'Meuterei' anzuzetteln. Sobald diese Jungs für uns arbeiten, ist das ein Kinderspiel, nicht wahr?\n\nSprecht mit Tony Zweihauer auf Prügeleiland im Süden.", sourceObjective = "Sprecht mit Tony Zweihauer auf Prügeleiland im Nördlichen Brachland.", completion = "Heiho Mann, hat Flunkerblick Euch geschickt? Gut, gut. Habt Ihr das Geld dabei? Nein?...Was ist mit den Gewehren?", sourceObjectiveStatus = "unverified-source-field" }
quests[14053] = { id = 14053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schon wieder kein Moosbeerenchutney mehr?", description = "Mein Mann Jasper wollte eigentlich noch mehr Moosbeerenchutney zubereiten, aber wie es scheint, hat er schon genug mit den kandierten Süßkartoffeln für all die Gäste zu tun. Würdet ihr vielleicht aushelfen? Wenn Ihr in der Kochkunst bewandert seid, braucht Ihr nur die säuerlichen Sumpfmoosbeeren, die Ihr beim Händler des Pilgerfreudenfests außerhalb von Eisenschmiede bekommen könnt.\n\nFalls Euch nicht nach Kochen ist, könnt Ihr auch jederzeit jemand anderen um die Zubereitung des Chutneys bitten.", sourceObjective = "Bringt 20 Portionen Moosbeerenchutney zu Ellen Moore an die Festtafel außerhalb Sturmwinds.", progress = "Konntet Ihr etwas Moosbeerenchutney auftreiben?", completion = "Danke. Das sieht wirklich köstlich aus, und Ihr seid ein ganzes Stück schneller als Jasper - aber verratet ihm nicht, dass ich das gesagt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[14054] = { id = 14054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuchen versuchen", description = "Isaac arbeitet hart, um den Feiernden die traditionellen Ursprünge des Pilgerfreudenfests und die Zubereitung aus all den geernteten Zutaten in dieser Jahreszeit näher zu bringen. Ich bemühe mich, die Festtafeln schön gefüllt zu halten, aber Isaacs Leibspeise geht langsam zur Neige - Kürbiskuchen!\n\nKönntet Ihr welchen für uns organisieren? Wenn Ihr ihn selbst zubereiten wollt, benötigt Ihr reife Elwynnkürbisse vom Händler des Pilgerfreudenfests außerhalb Sturmwinds.", sourceObjective = "Bringt 20 Kürbiskuchen zu Mary Allerton an die Festtafel vor den Toren von Darnassus.", progress = "Wie geht es mit dem Kuchen voran?", completion = "Die sind wunderbar. Isaac wird begeistert sein, und nicht nur er!", sourceObjectiveStatus = "unverified-source-field" }
quests[14055] = { id = 14055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rein in die Kartoffeln, raus aus den Kartoffeln", description = "Meine Frau Ellen hat mich damit beauftragt, für gedeckte Tafeln zu sorgen, doch sie ändert ständig ihre Meinung. Zuerst sollte ich Kürbiskuchen zubereiten, nun sind es plötzlich kandierte Süßkartoffeln.\n\nIch habe aber schon mit dem Kuchen angefangen! Vielleicht könntet Ihr mir ja mit den Süßkartoffeln aushelfen? Sie wird sicher angenehm überrascht sein, wenn wir alle ihre Wünsche erfüllen.\n\nSolltet Ihr die Süßkartoffeln selbst kandieren wollen, müsst Ihr sie beim Händler des Pilgerfreudenfests in Darnassus erstehen. Ich danke Euch, {name}.", sourceObjective = "Bringt 20 kandierte Süßkartoffeln zu Jasper Moore an die Festtafel außerhalb von Sturmwind.", progress = "Habt ihr die kandierten Süßkartoffeln dabei?", completion = "Die sind genau richtig! Vielen Dank für Eure Hilfe, {name}. Das Festmahl wird rechtzeitig fertig sein, und Ellen wird sich sicher freuen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14056] = { id = 14056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glomp sitzt darauf", description = "Was? Glaubt Flunkerblick etwa, dass eine Meuterei so einfach und so billig ist?\n\nEgal, Mann, das wird schon hinhauen. Zunächst brauchen wir Geld. Käpt'n Garvey hortet gerne die Schätze, die wir erbeutet haben. Mit diesem Geld könnten wir meine handverlesenen Meuterer bezahlen.\n\nDer Schatz befindet sich direkt vor den Baracken hier. Ihr müsst Euch um Käpt'n Garveys 'Schatzmeister' kümmern. Allerdings lässt sich Glomp nicht so einfach herumschubsen. Glaubt mir, ich habe schon mal geschubst, und... Sagen wir, den haut nichts so schnell um.", sourceObjective = "Tötet Glomp und schnappt Euch Glomps Beute.", progress = "Habt Ihr das Gold? Das Geld reicht allemal, um die Köpfe und Herzen der hirnlosen und herzlosen Halsabschneider zu gewinnen.", completion = "Sieh mal. Wir sind steinreich! Für eine Meuterei braucht man zuerst Geld. Wenn man das Geld hat, bekommt man die Macht. Holen wir uns die Macht, {name}...", sourceObjectiveStatus = "unverified-source-field" }
quests[14057] = { id = 14057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewehre. Wir brauchen Gewehre.", description = "Für jede gute Meuterei braucht man ordentlich Feuerkraft. Käpt'n Garvey beansprucht die besten Schusswaffen für sich: eine ganze Ladung schwerer, zwergischer Steinschlossbüchsen. Er lagert sie bei sich im anderen Gebäude auf der anderen Seite der Insel. Bringt mir sechs dieser Büchsen und ich gebe sie an meine zukünftigen Offiziere weiter...", sourceObjective = "Besorgt 6 schwere, zwergische Gewehre.", progress = "Gewehre, Mann. Habt Ihr sie?", completion = "<Tony schnappt sich eine der Waffen und schaut durch den Lauf.>\n\nOh, sehr schön. Glänzend. Laut. Die können sich sehen lassen.\n\nEs bleibt nicht mehr viel zu tun, bis wir alles soweit haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[14058] = { id = 14058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rein in die Kartoffeln, raus aus den Kartoffeln", description = "Roberta Carter hat mich beauftragt, eines der Festtagsgerichte zuzubereiten. Kandierte Süßkartoffeln! Normalerweise würde ich mich darum reißen, aber ich habe der Gastgeberin versprochen, mit ihr auf die Tafeln zu achten.\n\nEs wäre eine große Hilfe, wenn Ihr stattdessen für mich einige kandierte Süßkartoffeln organisieren könntet! Roberta würde mir nie vergeben, wenn ich sie im Stich lasse. \n\nWenn Ihr die Süßkartoffeln selbst kandieren wollt, müsst Ihr zunächst welche vom Händler des Pilgerfreudenfests in Donnerfels erstehen. Ich danke Euch für Eure Hilfe, {name}!", sourceObjective = "Bringt 20 kandierte Süßkartoffeln zu William Mullins an die Festtafel oberhalb von Unterstadt.", progress = "Habt Ihr die kandierten Süßkartoffeln?", completion = "Vielen Dank, {name}. Ich kann der Gastgeberin helfen und brauche Roberta dennoch nicht zu enttäuschen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14059] = { id = 14059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schon wieder kein Moosbeerenchutney mehr?", description = "Ich wünschte, ich wüsste, warum das Moosbeerenchutney immer so schnell alle ist. Manchmal habe ich das Gefühl, sie verfüttern es heimlich an die Monstrositäten, wenn gerade keiner hinschaut. Würdet Ihr uns helfen, für Nachschub zu sorgen? Wenn Ihr in der Kochkunst bewandert seid, könnt Ihr die benötigten säuerlichen Moosbeeren vom Südstrom vom Händler des Pilgerfreudenfests außerhalb von Orgrimmar bekommen.\n\nSteht Euch nicht der Sinn nach Kochen, könnt Ihr auch jederzeit jemand anderen darum bitten.", sourceObjective = "Bringt 20 Portionen Moosbeerenchutney zu Roberta Carter an die Festtafel in den Innenhof oberhalb von Unterstadt.", progress = "Konntet Ihr etwas Moosbeerenchutney auftreiben?", completion = "Vielen Dank für Eure Hilfe, und gebt mir Bescheid, falls Ihr jemals hinter das Geheimnis des ständig verschwindenden Chutneys kommen solltet!", sourceObjectiveStatus = "unverified-source-field" }
quests[14060] = { id = 14060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuchen versuchen", description = "Dokin und Laha bemühen sich, den Feiernden die Hintergründe des Fests und die Zubereitung der traditionellen Gerichte aus all den frisch geernteten Zutaten nahe zu bringen. Ich versuche, die Tische mit so viel Essen wie nur möglich gefüllt zu halten, aber uns geht langsam der Kürbiskuchen aus.\n\nWürdet Ihr vielleicht welchen für uns besorgen? Wenn Ihr ihn selbst zubereiten wollt, benötigt Ihr dafür reife Tirisfalkürbisse, die Ihr beim Händler des Pilgerfreudenfests oberhalb von Unterstadt bekommen könnt.", sourceObjective = "Bringt 20 Kürbiskuchen zu Mahara Goldweizen nahe der Festtafel außerhalb von Donnerfels.", progress = "Wie steht es mit dem Kuchen?", completion = "Die sind fantastisch. Danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14061] = { id = 14061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich krieg einfach nicht genug … Truthahn", description = "Ich hab schon vor den Feiertagen angefangen zu kochen und seitdem nicht mehr aufgehört! Und es ist trotzdem nie genug - könnte ich Euch vielleicht überreden, mir zur Hand zu gehen?\n\nTruthahn bekommt man hier schwer, wenn Ihr mir also ein paar langsam geröstete Truthähne bringen könntet, wäre das eine enorme Hilfe. Möchtet Ihr ihn selbst zubereiten, könnt Ihr die Truthähne überall in Tirisfal selbst erjagen. Alle weiteren Zutaten erhaltet Ihr bei jedem Händler des Pilgerfreudenfests.", sourceObjective = "Bringt 20 langsam geröstete Truthähne zu Ondani Mühlenrad außerhalb von Orgrimmar.", progress = "Wie steht's mit der Truthahnjagd?", completion = "Prächtige Truthähne, genau was ich brauche! Ihr habt mir wirklich aus der Klemme geholfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14062] = { id = 14062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Füllung ist alles!", description = "Dafür zu sorgen, dass die Festtafeln gefüllt bleiben, ist kein Kinderspiel! Ich muss das Moosbeerenchutney zubereiten, die Süßkartoffeln im Auge behalten und gleichzeitig auch noch dafür sorgen, dass der Kürbiskuchen nicht anbrennt.\n\nIch glaube, ich habe alles soweit im Griff. Moment, ich habe doch irgendwas vergessen ... Oh nein, die Füllung! Jetzt bleibt mir keine Zeit mehr dafür, bevor ich nicht mit dem Rest fertig bin. Äh, vielleicht könntet Ihr mir da aushelfen? Es sollte nicht allzu lang dauern, etwas Gewürzbrotfüllung zu kaufen oder selbst zuzubereiten, die Zutaten könnt Ihr direkt hier besorgen.", sourceObjective = "Bringt 20 Portionen Gewürzbrotfüllung zu Ondani Mühlenrad an die Festtafel außerhalb von Orgrimmar.", progress = "Wie sieht es mit der Füllung aus?", completion = "Gerade rechtzeitig! Ich hätte das Festmahl ohne Gewürzbrotfüllung gar nicht auftischen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[14063] = { id = 14063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meuterei, Mann!", description = "Nun zum schönsten Teil einer Meuterei: dem Abmurksen! Piraten interessieren sich nicht so sehr für die Frage, wer das Sagen haben soll, sondern es geht ihnen nur darum, wer das Schiff beherrscht. Im Ostende dieser Insel liegt die 'Dolch der Maid', das alte Flaggschiff von Käpt'n Garvey. Er hat die Aufsicht dem Offizier überlassen, dem er am meisten vertraut: Alicia Cuthbert. Sobald wir sie erledigt haben, gehört das Schiff uns – und damit auch das Meer.\n\nIch gebe meinen Männern den Befehl, in die Boote zu steigen. Ihr müsst an Bord der 'Dolch' gehen und an Deck in dieses Horn tuten. Das wird unser Signal sein, das Schiff zu kapern. Jippieh!", sourceObjective = "Verwendet das Signalhorn der Piraten, um Tony Zweihauer und seine Mannschaft an Bord der 'Dolch der Maid' zu rufen. Helft ihm, Alicia Cuthbert unter Deck zu besiegen.", progress = "Ist das die 'Dolch der Maid', die dort in der Entfernung den Anker lichtet? Habt Ihr etwas damit zu schaffen?", completion = "Schmeißt Tony dort jetzt also den Laden? Gut! Wir brauchen in diesen Gewässern mehr Piraten wie ihn. Er ist ein echter Geschäftsmann.\n\n<Flunkerblick reibt seine Hände gierig aneinander.>\n\nWo wir vom Geschäft reden: ich schätze, ich bin Euch einen Anteil schuldig. Wäret Ihr daran interessiert, einen Teil Eurer Beute zu versichern? Man weiß nie, was in einer Stadt wie dieser geschieht...", sourceObjectiveStatus = "unverified-source-field" }
quests[14064] = { id = 14064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teilen an der Festtafel", description = "Ihr habt nicht wirklich die Pilgerfreuden genossen, wenn Ihr Euch nicht ordentlich an einem der reich gedeckten Tische den Bauch vollgeschlagen habt.\n\nBitte, setzt Euch doch und speist, soviel Ihr nur könnt! Ihr könnt selbst von Stuhl zu Stuhl rücken, oder andere darum bitten, Euch einige der Speisen weiterzureichen.\n\nSobald Ihr genug von jedem Gericht verspeist habt, kommt Ihr zu der Erkenntnis: Teilen macht Freude!", sourceObjective = "Verspeist fünf Portionen jedes Gerichts an einem reich gedeckten Tisch, bis Ihr zu der Erkenntnis kommt: Teilen macht Freude.", completion = "Was für ein Festmahl, hm?\n\nEs freut mich, dass Ihr zusammen mit uns die Bedeutung des Pilgerfreudenfests zelebrieren konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14065] = { id = 14065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teilen an der Festtafel", description = "Ihr habt nicht wirklich die Pilgerfreuden genossen, wenn Ihr Euch nicht ordentlich an einem der reich gedeckten Tische den Bauch vollgeschlagen habt.\n\nBitte, setzt Euch doch und speist, soviel Ihr nur könnt! Ihr könnt selbst von Stuhl zu Stuhl rücken, oder andere darum bitten, Euch einige der Speisen weiterzureichen.\n\nSobald Ihr genug von jedem Gericht verspeist habt, kommt Ihr zu der Erkenntnis: Teilen macht Freude!", sourceObjective = "Verspeist fünf Portionen jedes Gerichts an einem reich gedeckten Tisch, bis Ihr zu der Erkenntnis kommt: Teilen macht Freude.", completion = "Was für ein Festmahl, hm?\n\nEs freut mich, dass Ihr zusammen mit uns die Bedeutung des Pilgerfreudenfests zelebrieren konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14066] = { id = 14066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung des Wracks", description = "Vor nicht allzu langer Zeit wurde eine Ladung Silber auf dem Weg von hier zum Wegekreuz gestohlen. Es war als Bezahlung für die Wachen gedacht und wir wollen das Silber zurück haben.\n\nIch habe mich nach Hinweisen umgehört, aber ich will, dass Ihr den Tatort untersucht. Begebt Euch nach Westen und sucht nach einem verunglückten Wagen einer Karawane an der Straße von hier Richtung Norden auf dem Weg zum Wegekreuz. Findet heraus, wer das Silber an sich genommen hat und holt es Euch zurück!", sourceObjective = "Findet den verunglückten Wagen in der Nähe der Straße zwischen Ratschet und dem Wegekreuz, und sucht das Gebiet nach Spuren und Hinweisen ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[14067] = { id = 14067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gestohlene Silber", description = "Offensichtlich haben diese Raptoren alleine gehandelt, als sie das Silber der Horde raubten.\n\nEs wird Zeit, diesen Bestien eine Lektion zu erteilen.", sourceObjective = "Tötet 8 Felshetzer der Sonnenschuppen, 4 Sensenklauen und findet das gestohlene Silber.", progress = "Ihr seht mitgenommen aus, {class}. Habt Ihr Euch mit den Dieben gerangelt?", completion = "<Gazrog öffnet die Schließkassette und zählt das Silber, während Ihr berichtet.>\n\nWas!? Raptoren? Nur die Raptoren? Alleine? Greifen unsere Karawanen an und plündern sie aus? Vielleicht sind sie doch so intelligent, wie die Gerüchte besagen. Als ob wir nicht schon genug Probleme hätten, müssen wir uns jetzt auch noch um diese schlauköpfigen und geldgierigen Echsen kümmern.\n\nHier, {name} – Ihr habt Euch einen Teil des Silbers verdient. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[14068] = { id = 14068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waptorfalle", description = "Waptoren zu fangen, ist ganz schön schwiewig, aber ich habe eine neue Waptorfalle entwickelt, die den Gwoßteil der Wisiken ausschaltet.\n\nStellt die Falle auf dem Boden auf und sie quietscht wie ein Waptor und lockt so einen andewen in die Falle.\n\nWenn ein Waptor in meine Waptorfalle twitt, schwumpft sie ihn zusammen, sodass er nicht mehr so gefährlich ist. Es ist schwecklich einfach! Ich würde es selbst machen, aber ich bin neulich König Schnitterklaue begegnet.", sourceObjective = "Verwendet Kala'mas \"Waptorfalle\", um 5 kleine Waptoren zu fangen.", progress = "Wo sind die kleinen Waptoren?", completion = "Huwwa! Ihr habt die Waptoren gefangen, nach denen ich gesucht habe! Jetzt dwessieren wir sie so, dass Twolle auf ihnen weiten können, um die Allianz zu vernichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[14069] = { id = 14069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutes Personal ist schwer zu finden", description = "Ich habe versagt! Ich habe alles versucht, um unser Kaja'Cola-Soll zu erreichen, aber Ihr wisst doch, wie das mit den Trollsklaven heutzutage ist. Gutes Personal ist schwer zu finden!\n\nIch glaube, Ihr müsst hier selbst Hand anlegen. Ein kleiner Stromschlag mit der Batterie Eures goblinischen Alles-in-1-zigartigen Gürtels sollte Wunder wirken. Wenn Ihr die Arbeitsmoral von ein paar Trollen da unten anpasst, ziehen die anderen sicher schnell nach.\n\nDie Kaja'Cola-Produktion muss weitergehen, sonst macht uns der Handelsprinz einen Kopf kürzer!", sourceObjective = "Verbessert die Arbeitsmoral von 8 widerspenstigen Trollen.", completion = "Ich hätte es selbst nicht besser machen können. Und das habe ich auch nicht.\n\nIhr seid uns allen eine Inspiration, {name}. Ich bin mir sicher, dass die Großartigkeit, die Macht und, wenn ich hinzufügen darf, der extreme Reichtum des neuen Handelsprinzen {name} bald in aller Munde sein werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[14070] = { id = 14070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbst ist der Goblin", description = "Wir müssen gleich mehreren Schuldnern eine Nachricht zukommen lassen. Natürlich versteckt sich dieser Abschaum im Malocherviertel. Ich weiß, wie ungern Ihr in die Slums geht, <Herr/Frau> Boss, aber was soll man schon machen?\n\n<Sassy blättert durch einen Stapel Papiere.>\n\nIch habe alle Namen hier.\n\nDarf ich vielleicht vorschlagen, dass Ihr ihnen einen \"persönlichen Besuch\" abstattet? Ein paar strategisch geplante Schlägereien setzen deutliche Zeichen für die anderen Schuldner UND Eure Konkurrenten.\n\n{name} ist kein Goblin, mit dem man sich anlegen sollte!", sourceObjective = "Verprügelt Bruno Flammhemmer, Frankie Gangschalter, Jack den Hammer und Sudsy Magee.", completion = "Das nenne ich einen absoluten Erfolg, mein Herr! Eure Schuldner werden es sich jetzt sicher zweimal überlegen, bevor sie Euch nicht bezahlen!\n\n<Sassy kaut einen Augenblick gedankenverloren auf ihrem Stift herum.>\n\nVielleicht sollten wir die Verleihzinsen erhöhen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14071] = { id = 14071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cruisen", description = "{name}, ich habe gehört, dass Ihr die Mutter aller Firmenpartys ausrichten werdet. Laut meinen Berechnungen sollte Euer Beförderungsquotient raketenhaft in die Höhe schießen und explodieren, wenn man sieht, dass Ihr auf der Party Spaß habt!\n\nDaher schlage ich vor, Ihr unternehmt eine kleine Spritztour mit dem Hot Rod und holt Eure Freunde in der Stadt ab.\n\nVergesst mich nur nicht, wenn alles am Schnürchen läuft und Ihr <der neue Handelsprinz/die neue Handelsprinzessin> werdet, ja?", sourceObjective = "Fahrt mit dem Hot Rod durch die Gegend und holt Eure Freunde Ass, Gobber und Izzy ab.", completion = "Gut gemacht, mein Herr. Der Hot Rod steht Euch wirklich ausgezeichnet. Ihr habt die Bevölkerung sicher schwer beeindruckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14072] = { id = 14072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verog aufstöbern", description = "Regthar Totenfurt hat mich hierhergeschickt, um die Aktivitäten der Zentauren zu beobachten, aber der Anführer der Gruppe ist schwer auszumachen. Ich habe herausgefunden, dass er 'Verog der Derwisch' heißt, aber sein Aufenthaltsort bleibt unbekannt.\n\nKönnt Ihr mir ein wenig beim Auskundschaften helfen? Man würde bei den Zentauren eigentlich keine echten 'Geheiminformationen' erwarten, aber häufig befinden sich in ihren Lagern massenhaft wichtige Papiere. Sucht die Zelte der Zentauren um die Brackige Oase ab und bringt mir ein paar Informationen.", sourceObjective = "Sammelt 4 Geheiminformationen der Zentauren aus der Umgebung der Brackigen Oase.", progress = "Durchsucht diese Zelte, {name}. Versucht, den Gestank zu ignorieren.", completion = "Gute Arbeit, {name}! Habt Ihr diese Papiere schon angesehen? Sie sind kaum lesbar und sehen eher wie eine wilde Schmiererei aus als wie Kriegspläne. Hass, Eifersucht, Wut, Zwietracht – es ist ein Wunder, dass Verog diese Zentauren davon abhalten kann, sich gegenseitig zu töten, ganz zu schweigen davon, sie zu einer Armee vereinen.\n\nDas können wir ausnutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14073] = { id = 14073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung für Totenfurt", description = "{name}! Euer Ruf für die Horde wächst. Mir sind Berichte von den Vergessenen Teichen und der Brackigen Oase zu Ohren gekommen, dass Ihr unseren Zentauren-Feinden großen Schaden zugefügt habt. Gute Arbeit, in der Tat.\n\nRegthar Totenfurt leitet die Einsätze gegen die Zentauren im gesamten Nördlichen Brachland. Er könnte jemanden wie Euch zur Unterstützung seiner Streitkräfte gut gebrauchen. Meldet Euch bei ihm in seinem Vorposten an der Straße in Richtung Westen und lasst ihm jede Hilfe zukommen, die in Eurer Macht steht.", sourceObjective = "Meldet Euch bei Regthar Totenfurt an seinem Vorposten westlich vom Wegekreuz im Nördlichen Brachland.", completion = "Ah, ich habe schon von Eurer Arbeit gehört, {class}. Ihr habt den Zeitpunkt Eures Eintreffens gut gewählt. Ich arbeite derzeit an einer Großoffensive.", sourceObjectiveStatus = "unverified-source-field" }
quests[14074] = { id = 14074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legt mal ein Bein zu", description = "Der Argentumkreuzzug hatte ein schnelles Schiff mit einer Ladung Weitschreiterfleisch und weiteren Vorräten entsendet, die für uns hier am Turnierplatz vorgesehen waren, doch nie eingetroffen sind. Späher berichteten uns von einem Angriff der Kvaldir, räuberische Vrykul, die Angst und Schrecken auf den Meeren verbreiten.\n\nSie haben die Crew erschlagen und die Ladung auf eine Insel namens Hrothgars Landestelle gebracht. Wenn Ihr Richtung Norden blickt, könnt Ihr sie schemenhaft erkennen, verborgen im Nebel. Würdet Ihr uns helfen, das Diebesgut zurückzubeschaffen? Ohne diese Weitschreiterbeine werden wir bald hungern müssen.", sourceObjective = "Beschafft 10 gestohlene Weitschreiterbeine zurück und bringt sie zu Narasi Schneedämmerung auf dem Argentumturnierplatz.", progress = "Konntet Ihr die gestohlenen Vorräte wiederbeschaffen?", completion = "Sie sehen etwas mitgenommen aus, doch sie sind noch immer genießbar. Die Kreuzzügler werden glücklich sein, dass etwas von der Ladung gerettet werden konnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[14075] = { id = 14075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in den Minen", description = "Wir haben schon wieder Ärger in der Kaja'mine, Boss. Die Tunnelwürmer sind zurück und fressen wortwörtlich den gesamten Profit der Handelsgesellschaft von Kajaro auf!\n\nWir können kein Kaja'mit abbauen, was die Produktion von Kaja'Cola schwer beeinträchtigt!\n\nIch habe schon versucht, den Kammerjäger zu rufen, aber er hat sich mit unserer letzten Zahlung aus dem Staub gemacht.\n\nMeint Ihr, Ihr könntet selbst in die drei Minen gehen und Euch darum kümmern? Ich würde Euch ja helfen, aber ich habe noch nicht am vom Kartell vorgeschriebenen Nahkampftraining teilgenommen.", sourceObjective = "Tötet 6 Tunnelwürmer.", completion = "Auf Nimmerwiedersehen, Ungeziefer!", sourceObjectiveStatus = "unverified-source-field" }
quests[14076] = { id = 14076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühstück der Champions", description = "Nun, da das Kolosseum fertiggestellt ist, haben wir vom Argentumkreuzzug die Bitte erhalten, bei der Pflege der Kreaturen zu helfen, die als Gegner für die Champions dienen werden.\n\nDie riesigen Jormungar ernähren sich womöglich auf die seltsamste Art und Weise: Sie wachsen heran, indem sie die Eier ihrer eigenen Artgenossen fressen, und die besten Eier stammen von den Tiefenjormungar.\n\nNehmt diese Trommel und begebt Euch in die Fußmarschen im Zentrum der Sturmgipfel. Spielt sie anschließend in der Nähe der Schneehügel, die Ihr dort seht. Scheucht die Tiefenjormungar auf, tötet sie und sammelt ihre Eiersäcke ein.", sourceObjective = "Beschafft Euch 4 Eiersäcke eines Jormungars und bringt sie zu Savinia Lehrensang auf dem Argentumturnierplatz.", progress = "Habt Ihr die Eier besorgen können? Diese Würmer werden anfangen, ihre Tierführer zu fressen, wenn sie nicht schon bald gefüttert werden.", completion = "Gut gemacht, {name}. Ich werde diese hier umgehend zu den Tierführern des Argentumkreuzzugs bringen. Sie werden keine andere Wahl haben und anerkennen müssen, dass wir um einiges mehr leisten als die Sonnenhäscher, wenn es darum geht, für den reibungslosen Ablauf im Kolosseum zu sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14077] = { id = 14077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Barmherzigkeit des Lichts", description = "Ich habe Beichtpatin Blondlocke aufmerksam gelauscht, und ich sage Euch, ihre Worte gaben mir zu denken. Es genügt nicht, einfach nur an der Seite der Kreuzfahrer zu kämpfen, wir müssen uns ihre Mission zu Eigen machen.\n\nAn der Nordküste liegt Hrothgars Landestelle, wo die seefahrenden Kvaldir eine alte Tuskarrsiedlung überrannt und deren Bewohner getötet haben. Nehmt dieses Buch und lest den Leichen der Dorfbewohner ihre Sterbesakramente. So ermöglicht Ihr ihren Seelen, die Fesseln der Nebel um die Insel abzustreifen und ihren Frieden zu finden.", sourceObjective = "Benutzt das Gebetsbuch der Beichtpatin, um 8 erschlagenen Tualiq-Bewohnern ihre Sterbesakramente zu lesen, und kehrt dann zu Narasi Schneedämmerung auf dem Argentumturnierplatz zurück.", progress = "Habt Ihr Euch der Seelen der erschlagenen Tualiq-Bewohner angenommen?", completion = "<Narasi nimmt das Gebetbuch von Euch entgegen.>\n\nIch danke Euch. Dieses Buch war ein Geschenk der Beichtpatin Blondlocke selbst. Sie wäre sicher hocherfreut, dass Ihr es eingesetzt habt, um das Leid der erschlagenen Seelen zu lindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[14078] = { id = 14078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgeriegelt!", description = "Was tut Ihr noch hier, <Bürger/Bürgerin>? Habt Ihr nicht gehört? Über die Stadt wurde eine vollständige Ausgangssperre verhängt.\n\nSprecht mit Leutnant Walden und befolgt seine Evakuierungsanweisungen.", sourceObjective = "Findet Leutnant Walden am nordwestlichen Ende des Händlerplatzes.", completion = "Die Leiche des Mannes ist von tiefen Klauenspuren gezeichnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14079] = { id = 14079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen im Wald von Elwynn", description = "Dieser Handzettel bewirbt das bei Randal Waidmann erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nRandal Waidmann befindet sich im Holzfällerlager des Osttals im Wald von Elwynn, von Sturmwind aus östlich die Straße entlang.", sourceObjective = "Bringt diesen Handzettel zu Randal Waidmann beim Holzfällerlager des Osttals im Wald von Elwynn.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14080] = { id = 14080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einhalt den Aggressoren", description = "Die Kvaldir, räuberische Vrykul, die überall Angst und Schrecken verbreiten, haben unsere Lieferungen abgefangen und sämtliche Tuskarrbewohner einer Insel im Norden ermordet. Sie haben die Insel bereits in Hrothgars Landestelle umbenannt. Wenn es ihnen gelingt, dort langfristig Fuß zu fassen, werden wir mit Sicherheit zu ihrem nächsten Ziel.\n\nDie Streitkräfte des Kreuzzugs haben jedoch alle Hände voll zu tun mit der Geißel, und wir müssen den Turnierplatz beschützen. Fliegt vom Platz aus Richtung Norden, bis Ihr die Insel erreicht und nehmt Euch der Kvaldir an, bevor sie noch mehr zerstören können!", sourceObjective = "Narasi Schneedämmerung auf dem Argentumturnierplatz möchte, dass Ihr 10 Kvaldir tötet.", completion = "Eure Taten haben bewiesen, dass wir Schulter an Schulter mit dem Argentumkreuzzug stehen, während die Sonnenhäscher zu viel Zeit mit Herumstolzieren verschwenden, um noch zu den Waffen greifen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[14081] = { id = 14081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen im Immersangwald", description = "Dieser Handzettel bewirbt das bei Perascamin erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nPerascamin befindet sich bei Thurons Aufzucht, südöstlich des Hirtentors außerhalb von Silbermond.", sourceObjective = "Bringt diesen Handzettel zu Perascamin bei Turons Aufzucht in Silbermond.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14082] = { id = 14082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in der Exodar", description = "Dieser Handzettel bewirbt das bei Aalun erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nAalun befindet sich am Eingang zur Exodar auf der Azurmythosinsel.", sourceObjective = "Bringt diesen Handzettel zu Aalun außerhalb der Exodar auf der Azurmythosinsel.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14083] = { id = 14083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Dun Morogh", description = "Dieser Handzettel bewirbt das bei Ultham Eisenhorn erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nUltham Eisenhorn befindet sich im Gehöft Bernruh in Dun Morogh, von Eisenschmiede aus östlich die Straße entlang.", sourceObjective = "Bringt diesen Handzettel zu Ultham Eisenhorn beim Gehöft Bernruh in Dun Morogh.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14084] = { id = 14084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Dun Morogh", description = "Dieser Handzettel bewirbt das bei Binjy Federpfiff erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nBinjy Federpfiff befindet sich bei Stahlrosts Depot, direkt nordöstlich von Kharanos in Dun Morogh.", sourceObjective = "Bringt diesen Handzettel zu Binjy Federpfiff bei Stahlrosts Depot in Dun Morogh.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14085] = { id = 14085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Darnassus", description = "Dieser Handzettel bewirbt das bei Jartsam erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nJartsam befindet sich in der Enklave des Cenarius in Darnassus.", sourceObjective = "Bringt diesen Handzettel zu Jartsam bei der Enklave des Cenarius in Darnassus.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14086] = { id = 14086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Orgrimmar", description = "Dieser Handzettel bewirbt das bei Kildar erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nKildar befindet sich im Tal der Ehre in Orgrimmar.", sourceObjective = "Bringt diesen Handzettel zu Kildar im Tal der Ehre in Orgrimmar.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14087] = { id = 14087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Mulgore", description = "Dieser Handzettel bewirbt das bei Kar Sturmsang erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nKar Sturmsang befindet sich im Dorf der Bluthufe in Mulgore.", sourceObjective = "Bringt diesen Handzettel zu Kar Sturmsang beim Dorf der Bluthufe in Mulgore.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14088] = { id = 14088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Durotar", description = "Dieser Handzettel bewirbt das bei Xar'Ti erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nXar'Ti befindet sich in Sen'jin in Durotar.", sourceObjective = "Bringt diesen Handzettel zu Xar'Ti in Sen'jin im südlichen Durotar.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14089] = { id = 14089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Tirisfal", description = "Dieser Handzettel bewirbt das bei Velma Warnam erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nVelma Warnam befindet sich in Brill in Tirisfal.", sourceObjective = "Bringt diesen Handzettel zu Velma Warnam in Brill in Tirisfal.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14090] = { id = 14090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormok will seine Schneebolde", description = "Zwei meiner Männer kamen schon bei dem Versuch um, den Magnatauren namens Gormok den Pfähler einzusperren, doch die Kreatur treibt noch immer ihr Unwesen. Sie heult und jammert stundenlang darüber, dass ihr Lieblingsschneebold nicht da ist.\n\nIch würde sie mit eigenen Händen töten, wenn der Argentumkreuzzug dieses Monster nicht ins Kolosseum schicken wollte. Vielleicht ist es an der Zeit, der Bestie ihr Spielzeug zu bringen. Hier, nehmt dieses Netz und begebt Euch nach Garms Bann im Südosten der Sturmgipfel gleich nordöstlich von K3. Fangt ein paar dieser Schneebolde und betet zum Licht, dass Ihr den richtigen gefunden habt.", sourceObjective = "Fangt mithilfe des beschwerten Netzes 8 schneeblinde Anhänger und bringt sie zu Savinia Lehrensang auf dem Argentumturnierplatz.", completion = "Je eher diese stinkenden Dinger aus meinen Augen verschwinden und in ihren Käfigen landen, um so schneller wird sich meine Stimmung bessern. Ich wünschte, der Argentumkreuzzug hätte den Sonnenhäschern die Aufsicht über diese Kreatur gegeben. Sie sind sich so ähnlich, dass sie sich eigentlich verstehen sollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14091] = { id = 14091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da stimmt was nicht", description = "Der Leutnant scheint seinen schweren Wunden erlegen zu sein. Der Prinz wird die Neuigkeiten bestimmt hören wollen.\n\nIhr hört Kampfgeräusche, die aus der Richtung des Marktes kommen.", sourceObjective = "Kehrt zu Prinz Liam Graumähne auf dem Händlerplatz zurück.", completion = "Ihr seid es wieder. Sieht aus, als ob Ihr niemand wärt, der im Angesicht der Gefahr den Schwanz einziehen würde. Nun dann.", sourceObjectiveStatus = "unverified-source-field" }
quests[14092] = { id = 14092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühstück der Champions", description = "Nun, da das Kolosseum fertiggestellt ist, haben wir vom Argentumkreuzzug die Bitte erhalten, bei der Pflege der Kreaturen zu helfen, die als Gegner für die Champions dienen werden.\n\nDie riesigen Jormungar ernähren sich womöglich auf die seltsamste Art und Weise: Sie wachsen heran, indem sie die Eier ihrer eigenen Artgenossen fressen, und die besten Eier stammen von den Tiefenjormungar.\n\nNehmt diese Trommel und begebt Euch in die Fußmarschen im Zentrum der Sturmgipfel. Spielt sie anschließend in der Nähe der Schneehügel, die Ihr dort seht. Ihr Ton wird die Tiefenjormungar aufscheuchen. Tötet sie, sammelt ihre Eiersäcke ein und bringt sie zurück zum Turnierplatz.", sourceObjective = "Beschafft Euch 4 Eiersäcke eines Jormungars und bringt sie zu Tylos Dämmerflucht auf dem Argentumturnierplatz.", progress = "Habt Ihr die Eier besorgen können? Die Jormungar werden unausstehlich, wenn man sie nicht füttert.", completion = "Ich werde die Kreuzfahrer wissen lassen, dass Ihr gerade eine Ladung frisches Futter zurückgebracht habt, während der Silberbund faul herumsitzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14093] = { id = 14093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hölle bricht los", description = "Worgen! Mein Vater hat mich gewarnt, dass die Schöpfungen des Erzmagiers Arugal irgendwann Amok laufen würden.\n\nAber woher kommen sie?\n\nVermutlich macht es keinen Unterschied. Helft uns, kurzen Prozess mit ihnen zu machen. Wir werden ihnen zeigen, aus welchem Holz die Bewohner von Gilneas geschnitzt sind.", sourceObjective = "Prinz Liam Graumähne wünscht, dass Ihr 6 tobende Worgen tötet.", progress = "Habt Ihr Euch um die {race} gekümmert?", completion = "Es hat keinen Zweck, {name}! Sie lassen nicht nach.", sourceObjectiveStatus = "unverified-source-field" }
quests[14094] = { id = 14094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Vorräte", description = "Hört zu, {name}. Wir können nicht zulassen, dass unser Proviant zerstört wird.\n\nDa Gilneas von der Außenwelt abgeschottet ist, werden wir den Winter nicht überleben, wenn wir noch mehr von unseren Vorräten verlieren.\n\nBitte helft mir dabei, zu retten, was zu retten ist.", sourceObjective = "Bergt 4 Vorratskisten.", progress = "Habt Ihr die Vorräte geborgen, {name}?", completion = "Hervorragend! Ich werde sicherstellen, dass sie an einen sicheren Ort gebracht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14095] = { id = 14095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überreste identifizieren", description = "Ein ganzer Zahn eines toten Kraken ist in der Tat ein seltener Fund. Kreuzfahrer Silberdämmerung wird das sehen wollen.", sourceObjective = "Bringt den Krakenzahn zum Beweis Eures Sieges zu Kreuzfahrer Silberdämmerung.", progress = "Was habt Ihr gefunden, Champion?", completion = "Ich wusste, dass die Krake jemandem wie Euch nicht gewachsen sein würde. Nun, da die Boote nicht mehr von ihr belästigt werden, bleibt den Kvaldir keine andere Wahl, als sich zurückzuziehen. Gute Arbeit, Champion!", sourceObjectiveStatus = "unverified-source-field" }
quests[14096] = { id = 14096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diesmal habt Ihr Euch wirklich selbst übertroffen, Kul", description = "Kreuzfahrer Kul hat sich mal wieder in Schwierigkeiten gebracht, nur dieses Mal hat er noch andere mit hineingezogen. Als er sah, wie Kultisten in Todessprechers Wacht westlich des Turnierplatzes ihr Lager aufschlugen, rief er die Streiter für einen Angriff zusammen.\n\nOhne Verstärkung wurden Kul und seine Gefolgschaft schnell gefangengenommen. Ich habe keine Zweifel, dass der Kult die Gefangenen opfern wird - es sei denn, wir können einen Rettungseinsatz in Gang bringen. Jeder von diesen Kultisten könnte Schlüssel für die schwarzen Käfige bei sich haben. Findet die Schlüssel und befreit Kul und die gefangenen Streiter.", sourceObjective = "Rettet Kul den Tollkühnen und 4 gefangene Streiter aus Todessprechers Wacht und kehrt dann zu Narasi Schneedämmerung auf dem Argentumturnierplatz zurück.", completion = "Dank Euch haben Kul und die Streiter überlebt, um weiterhin die Geißel zu bekämpfen. Das ist bei Weitem nicht das erste Mal, dass jemand Kul vor sich selbst retten musste. Ich hoffe nur, dass die Kreuzfahrer ein besseres Ventil für seinen Enthusiasmus finden, als ihm weiter zu gestatten, seine schlechten Angewohnheiten an junge und noch beeindruckbare Streiter weiterzugeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[14098] = { id = 14098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evakuiert den Händlerplatz", description = "Die Zivilisten sind hier nicht mehr sicher. Nicht mal mehr in ihren Häusern.\n\nWir tun, was wir können, um die Worgen davon abzuhalten, in die Häuser zu gelangen, aber es sind einfach zu viele.\n\nHelft uns dabei, die Häuser der Zivilisten zu evakuieren. Die Armee meines Vaters im Gefängnisviertel wird sie besser schützen können.", sourceObjective = "Evakuiert 3 Zivilistenhäuser.", completion = "Gute Arbeit, {name}. Dank Euch werden viele Bürger Gilneas' den morgigen Tag erleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[14099] = { id = 14099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Königlicher Befehl", description = "Es ist Zeit für Euch, uns zu verlassen, {name}. Geht mit den anderen Zivilisten ins Militärviertel.\n\nMeldet Euch bei Gwen Armstead, wenn Ihr die Brücke im Südosten überquert ... seht nach, ob es allen gut geht.\n\nIch werde mit den Wachen hierbleiben und den Rückzug der Zivilisten decken.\n\nGeht nun. Das ist ein Befehl!", sourceObjective = "Sprecht mit Gwen Armstead im Militärviertel im Südosten.", completion = "Es geht uns allen gut. Wir sind ein wenig mitgenommen, aber ... wir leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[14100] = { id = 14100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikt des Irdenen Rings", description = "Ihr seid weit in Eurem Training vorangekommen, {name}. Nun, da Ihr die vier grundlegenden Elemente voll und ganz beherrscht, müsst Ihr Euch darum bemühen, alle vier im Gleichgewicht zu halten. Diese Disziplin hat einen praktischen Vorteil: Mit etwas Übung könnt Ihr nur ein einziges Relikt tragen anstatt alle vier Totems.\n\nSprecht mit Gotura Vierwind im Tal der Weisheit in Orgrimmar und feilt an Eurer Beherrschung der Elemente.", sourceObjective = "Bringt Eure vier Totems nach Orgrimmar zu Gotura Vierwind.", progress = "Hmmm, was verleitet Euch, die Hilfe des Irdenen Rings zu suchen?", completion = "Ah, Ihr beherrscht nun die vier Totems. Ihr solltet stolz auf das sein, was Ihr bisher erreicht habt, junger {race}, aber das ist lediglich der Anfang Eurer Reise.\n\nHier, akzeptiert dies als Geschenk des Irdenen Rings. Tragt dieses Relikt bei Euch und die Macht aller vier Elemente wird Euch zu Diensten stehen.\n\nFührt Euer Training weiter. Diese Welt hat noch Schlimmes vor sich - ich kann es im Wind hören und fühle es im Rumpeln der Erde. Wir müssen auf das Schlimmste vorbereitet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[14101] = { id = 14101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drottinn Hrothgar", description = "Die Kvaldir, seefahrende Vrykul, die Schiffe und Küstensiedlungen überfallen, haben eine Tuskarrinsel auf der anderen Seite der Meerenge gen Norden überrannt. Ihr Anführer ist ein altgedienter Plünderer namens Drottinn Hrothgar, der die Kontrolle über diesen Teil der See erlangen möchte.\n\nMit ihm an der Macht werden unsere Lieferungen und Truppentransporte niemals sicher sein. Wir werden hier gestrandet und dem Lichkönig auf Gedeih und Verderb ausgeliefert sein.\n\nHier, bringt dieses erbeutete Kriegshorn der Kvaldir zum Tuskarrstatuenkreis im nordöstlichen Teil von Hrothgars Landestelle und verwendet es, um den Anführer der Kvaldir herauszufordern.", sourceObjective = "Hochmeister Adelard auf dem Argentumturniergelände möchte, dass Ihr Drottinn Hrothgar besiegt.", completion = "Die Niederlage von Drottinn Hrothgar wird die Kvaldir gegeneinander aufhetzen, was uns genug Zeit verschafft, unseren Vorteil zu nutzen. Der Kreuzzug und das Turnier stehen in unserer Schuld, Champion.", sourceObjectiveStatus = "unverified-source-field" }
